@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --color-success: var(--success);
  --color-warning: var(--warning);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
}

:root {
  --radius: 0.625rem;
  --background: oklch(0.985 0.001 250);
  --foreground: oklch(0.145 0.015 250);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.145 0.015 250);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.145 0.015 250);
  --primary: oklch(0.488 0.243 264);
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.96 0.01 250);
  --secondary-foreground: oklch(0.205 0.015 250);
  --muted: oklch(0.96 0.005 250);
  --muted-foreground: oklch(0.5 0.02 250);
  --accent: oklch(0.96 0.01 250);
  --accent-foreground: oklch(0.205 0.015 250);
  --destructive: oklch(0.577 0.245 27.325);
  --success: oklch(0.627 0.194 149);
  --warning: oklch(0.795 0.184 86);
  --border: oklch(0.912 0.005 250);
  --input: oklch(0.912 0.005 250);
  --ring: oklch(0.488 0.243 264);
  --chart-1: oklch(0.488 0.243 264);
  --chart-2: oklch(0.627 0.194 149);
  --chart-3: oklch(0.795 0.184 86);
  --chart-4: oklch(0.646 0.222 41.116);
  --chart-5: oklch(0.577 0.245 27.325);
  --sidebar: oklch(0.975 0.002 250);
  --sidebar-foreground: oklch(0.205 0.015 250);
  --sidebar-primary: oklch(0.488 0.243 264);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.96 0.01 250);
  --sidebar-accent-foreground: oklch(0.205 0.015 250);
  --sidebar-border: oklch(0.912 0.005 250);
  --sidebar-ring: oklch(0.488 0.243 264);
}

.dark {
  --background: oklch(0.13 0.015 250);
  --foreground: oklch(0.96 0.005 250);
  --card: oklch(0.18 0.015 250);
  --card-foreground: oklch(0.96 0.005 250);
  --popover: oklch(0.18 0.015 250);
  --popover-foreground: oklch(0.96 0.005 250);
  --primary: oklch(0.588 0.243 264);
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.23 0.015 250);
  --secondary-foreground: oklch(0.96 0.005 250);
  --muted: oklch(0.23 0.015 250);
  --muted-foreground: oklch(0.65 0.02 250);
  --accent: oklch(0.23 0.015 250);
  --accent-foreground: oklch(0.96 0.005 250);
  --destructive: oklch(0.637 0.237 22.5);
  --success: oklch(0.667 0.194 149);
  --warning: oklch(0.815 0.184 86);
  --border: oklch(0.28 0.015 250);
  --input: oklch(0.28 0.015 250);
  --ring: oklch(0.588 0.243 264);
  --chart-1: oklch(0.588 0.243 264);
  --chart-2: oklch(0.667 0.194 149);
  --chart-3: oklch(0.815 0.184 86);
  --chart-4: oklch(0.696 0.222 41.116);
  --chart-5: oklch(0.637 0.237 22.5);
  --sidebar: oklch(0.16 0.015 250);
  --sidebar-foreground: oklch(0.96 0.005 250);
  --sidebar-primary: oklch(0.588 0.243 264);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.23 0.015 250);
  --sidebar-accent-foreground: oklch(0.96 0.005 250);
  --sidebar-border: oklch(0.28 0.015 250);
  --sidebar-ring: oklch(0.588 0.243 264);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
    transition-property: color, background-color, border-color, box-shadow;
    transition-duration: 0ms;
    transition-timing-function: ease;
  }

  /* Dark mode theme transition - activates when toggling */
  .theme-transitioning * {
    transition-duration: 300ms !important;
    transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1) !important;
  }
  html {
    scroll-behavior: smooth;
  }
  body {
    @apply bg-background text-foreground;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }
}

/* Custom scrollbar */
@layer base {
  ::-webkit-scrollbar {
    width: 6px;
    height: 6px;
  }
  ::-webkit-scrollbar-track {
    background: transparent;
  }
  ::-webkit-scrollbar-thumb {
    background: oklch(0.7 0.01 250);
    border-radius: 3px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: oklch(0.6 0.01 250);
  }
  .dark ::-webkit-scrollbar-thumb {
    background: oklch(0.35 0.01 250);
  }
  .dark ::-webkit-scrollbar-thumb:hover {
    background: oklch(0.45 0.01 250);
  }
}

/* ── Animations ──────────────────────────────────────────── */

@keyframes fade-in-up {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes scale-in {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes slide-in-right {
  from {
    opacity: 0;
    transform: translateX(12px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes shimmer {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}

@keyframes pulse-subtle {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

@keyframes counter-up {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes sla-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

/* Utility animation classes */
.animate-fade-in-up {
  animation: fade-in-up 0.4s ease-out both;
}

.animate-fade-in {
  animation: fade-in 0.3s ease-out both;
}

.animate-scale-in {
  animation: scale-in 0.25s ease-out both;
}

.animate-slide-in-right {
  animation: slide-in-right 0.35s ease-out both;
}

.animate-pulse-subtle {
  animation: pulse-subtle 2s ease-in-out infinite;
}

/* Staggered grid children animation */
.stagger-children > * {
  animation: fade-in-up 0.4s ease-out both;
}

.stagger-children > *:nth-child(1) { animation-delay: 0ms; }
.stagger-children > *:nth-child(2) { animation-delay: 40ms; }
.stagger-children > *:nth-child(3) { animation-delay: 80ms; }
.stagger-children > *:nth-child(4) { animation-delay: 120ms; }
.stagger-children > *:nth-child(5) { animation-delay: 160ms; }
.stagger-children > *:nth-child(6) { animation-delay: 200ms; }
.stagger-children > *:nth-child(7) { animation-delay: 240ms; }
.stagger-children > *:nth-child(8) { animation-delay: 280ms; }
.stagger-children > *:nth-child(9) { animation-delay: 320ms; }
.stagger-children > *:nth-child(10) { animation-delay: 360ms; }
.stagger-children > *:nth-child(11) { animation-delay: 400ms; }
.stagger-children > *:nth-child(12) { animation-delay: 440ms; }

/* Skeleton shimmer effect */
.skeleton-shimmer {
  background: linear-gradient(
    90deg,
    oklch(0.935 0.005 250) 25%,
    oklch(0.96 0.005 250) 50%,
    oklch(0.935 0.005 250) 75%
  );
  background-size: 200% 100%;
  animation: shimmer 1.5s infinite;
}

.dark .skeleton-shimmer {
  background: linear-gradient(
    90deg,
    oklch(0.22 0.015 250) 25%,
    oklch(0.26 0.015 250) 50%,
    oklch(0.22 0.015 250) 75%
  );
  background-size: 200% 100%;
}

/* ── Focus Styles ───────────────────────────────────────── */

@layer base {
  :focus-visible {
    outline: 2px solid oklch(0.488 0.243 264);
    outline-offset: 2px;
    border-radius: 4px;
  }
  .dark :focus-visible {
    outline-color: oklch(0.588 0.243 264);
  }
}

/* ── Table Enhancements ──────────────────────────────────── */

@layer base {
  /* Sticky table headers */
  thead th {
    position: sticky;
    top: 0;
    z-index: 10;
    background: oklch(1 0 0);
  }
  .dark thead th {
    background: oklch(0.18 0.015 250);
  }
}

/* ── Card Surface Styles ───────────────────────────────── */

/* Glass effect for overlay cards */
.card-glass {
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  background: oklch(1 0 0 / 0.7);
}
.dark .card-glass {
  background: oklch(0.18 0.015 250 / 0.7);
}

/* ── Bottom Navigation (Mobile) ─────────────────────────── */

.bottom-nav-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  padding: 6px 0;
  font-size: 10px;
  font-weight: 500;
  color: oklch(0.5 0.02 250);
  transition: color 0.15s ease;
  min-width: 48px;
}

.bottom-nav-item.active {
  color: oklch(0.488 0.243 264);
}

.dark .bottom-nav-item.active {
  color: oklch(0.588 0.243 264);
}

.bottom-nav-item:hover {
  color: oklch(0.3 0.015 250);
}

.dark .bottom-nav-item:hover {
  color: oklch(0.8 0.005 250);
}

/* ── Selection Styles ────────────────────────────────────── */

::selection {
  background-color: oklch(0.488 0.243 264 / 0.2);
}

.dark ::selection {
  background-color: oklch(0.588 0.243 264 / 0.3);
}

/* ── Card Gradient Accent System ─────────────────────── */

.card-accent-blue {
  border-top: 2px solid oklch(0.488 0.243 264);
}
.card-accent-green {
  border-top: 2px solid oklch(0.627 0.194 149);
}
.card-accent-amber {
  border-top: 2px solid oklch(0.795 0.184 86);
}
.card-accent-red {
  border-top: 2px solid oklch(0.577 0.245 27.325);
}
.card-accent-purple {
  border-top: 2px solid oklch(0.541 0.281 293);
}
.card-accent-cyan {
  border-top: 2px solid oklch(0.705 0.209 219);
}

/* ── Chart Card Hover Effect ──────────────────────────── */

.chart-card {
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.chart-card:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 12px -2px oklch(0 0 0 / 0.1);
}
.dark .chart-card:hover {
  box-shadow: 0 4px 12px -2px oklch(0 0 0 / 0.3);
}

/* ── Activity Timeline ────────────────────────────────── */

.activity-timeline {
  position: relative;
}
.activity-timeline::before {
  content: '';
  position: absolute;
  left: 15px;
  top: 8px;
  bottom: 8px;
  width: 2px;
  background: oklch(0.912 0.005 250);
}
.dark .activity-timeline::before {
  background: oklch(0.28 0.015 250);
}
.activity-item {
  position: relative;
  padding-left: 36px;
}
.activity-dot {
  position: absolute;
  left: 10px;
  top: 6px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 2px solid oklch(0.912 0.005 250);
  background: oklch(1 0 0);
}
.dark .activity-dot {
  border-color: oklch(0.28 0.015 250);
  background: oklch(0.18 0.015 250);
}

/* ── Enhanced Dark Mode for Charts ────────────────────── */

.dark .recharts-text {
  fill: oklch(0.65 0.02 250);
}
.dark .recharts-cartesian-grid-horizontal line,
.dark .recharts-cartesian-grid-vertical line {
  stroke: oklch(0.28 0.015 250);
}

/* ── Pulse Dot Animation (Live indicator) ─────────────── */

@keyframes pulse-dot {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.5; transform: scale(1.5); }
}
.pulse-dot {
  position: relative;
}
.pulse-dot::after {
  content: '';
  position: absolute;
  inset: -2px;
  border-radius: 50%;
  background: inherit;
  animation: pulse-dot 2s ease-in-out infinite;
}

/* ── Smooth Scrollbar (Firefox) ───────────────────────── */

* {
  scrollbar-width: thin;
  scrollbar-color: oklch(0.7 0.01 250) transparent;
}
.dark * {
  scrollbar-color: oklch(0.35 0.01 250) transparent;
}

/* ── App Footer ───────────────────────────────────────── */

.app-footer {
  border-top: 1px solid oklch(0.912 0.005 250);
  background: oklch(0.985 0.001 250);
}
.dark .app-footer {
  border-top-color: oklch(0.28 0.015 250);
  background: oklch(0.13 0.015 250);
}

/* ── KPI Card Shimmer on Hover ────────────────────────── */

.kpi-shimmer {
  position: relative;
  overflow: hidden;
}
.kpi-shimmer::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    transparent 0%,
    oklch(0.488 0.243 264 / 0.04) 50%,
    transparent 100%
  );
  transform: translateX(-100%);
  transition: transform 0.6s ease;
  pointer-events: none;
  z-index: 1;
}
.kpi-shimmer:hover::before {
  transform: translateX(100%);
}
.dark .kpi-shimmer::before {
  background: linear-gradient(
    90deg,
    transparent 0%,
    oklch(0.588 0.243 264 / 0.06) 50%,
    transparent 100%
  );
}

/* ── Table Row Hover Accent ────────────────────────── */

.table-row-hover tbody tr {
  transition: all 0.15s ease;
  border-left: 3px solid transparent;
}
.table-row-hover tbody tr:hover {
  border-left-color: oklch(0.488 0.243 264);
  background: oklch(0.96 0.005 250);
}
.dark .table-row-hover tbody tr:hover {
  background: oklch(0.22 0.015 250);
}

/* ── Card Depth Effect ──────────────────────────────── */

.card-depth {
  box-shadow: inset 0 1px 0 0 oklch(1 0 0 / 0.6), 0 1px 3px 0 oklch(0 0 0 / 0.04);
}
.dark .card-depth {
  box-shadow: inset 0 1px 0 0 oklch(1 0 0 / 0.05), 0 1px 3px 0 oklch(0 0 0 / 0.2);
}

/* ── Gradient Text Utility ──────────────────────────── */

.text-gradient {
  background: linear-gradient(135deg, oklch(0.488 0.243 264), oklch(0.646 0.222 41.116));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* ── Badge Glow Effects ──────────────────────────────── */

.badge-glow-critical {
  box-shadow: 0 0 8px 0 oklch(0.577 0.245 27.325 / 0.3);
}
.badge-glow-warning {
  box-shadow: 0 0 8px 0 oklch(0.795 0.184 86 / 0.3);
}

/* ── Button Press Effect ────────────────────────────── */

.btn-press:active {
  transform: scale(0.97);
  transition: transform 0.1s ease;
}

/* ── Data Row Enter Animation ────────────────────────── */

@keyframes data-row-slide {
  from { opacity: 0; transform: translateX(-4px); }
  to { opacity: 1; transform: translateX(0); }
}
.data-row-enter {
  animation: data-row-slide 0.2s ease-out;
}

/* ── Live Pulse Indicator ──────────────────────────── */

@keyframes live-pulse {
  0%, 100% { box-shadow: 0 0 0 0 oklch(0.627 0.194 149 / 0.5); }
  50% { box-shadow: 0 0 0 6px oklch(0.627 0.194 149 / 0); }
}
.live-indicator {
  animation: live-pulse 2s ease-in-out infinite;
}

/* ── Noise Texture Background ────────────────────────── */

.texture-bg {
  position: relative;
}
.texture-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  opacity: 0.02;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E");
  pointer-events: none;
  border-radius: inherit;
}

/* ── Sidebar Active Bar Indicator ────────────────────── */

.sidebar-active-bar {
  position: relative;
}
.sidebar-active-bar::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 3px;
  height: 60%;
  background: oklch(0.488 0.243 264);
  border-radius: 0 3px 3px 0;
}

/* ── Scroll Reveal Animation ─────────────────────────── */

.scroll-reveal {
  opacity: 0;
  transform: translateY(12px);
  transition: opacity 0.5s ease, transform 0.5s ease;
}
.scroll-reveal.revealed {
  opacity: 1;
  transform: translateY(0);
}

/* ── Card Highlight (Animated Gradient Border) ─────── */

@keyframes border-rotate {
  0% { --angle: 0deg; }
  100% { --angle: 360deg; }
}

@property --angle {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

.card-highlight {
  position: relative;
  border-radius: var(--radius-lg, 0.625rem);
  overflow: hidden;
}
.card-highlight::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 2px;
  background: conic-gradient(
    from var(--angle, 0deg),
    oklch(0.488 0.243 264),
    oklch(0.627 0.194 149),
    oklch(0.795 0.184 86),
    oklch(0.577 0.245 27.325),
    oklch(0.541 0.281 293),
    oklch(0.488 0.243 264)
  );
  mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  mask-composite: exclude;
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  animation: border-rotate 4s linear infinite;
  pointer-events: none;
  z-index: 1;
}

/* ── Data Card (Hover Lift) ────────────────────────── */

.data-card {
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
  border: 1px solid oklch(0.912 0.005 250);
}
.data-card:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 12px -2px oklch(0 0 0 / 0.08);
  border-color: oklch(0.488 0.243 264 / 0.2);
}
.dark .data-card {
  border-color: oklch(0.28 0.015 250);
}
.dark .data-card:hover {
  box-shadow: 0 4px 12px -2px oklch(0 0 0 / 0.3);
  border-color: oklch(0.588 0.243 264 / 0.3);
}

/* ── Table Container ───────────────────────────────── */

.table-container {
  border-radius: var(--radius-lg, 0.625rem);
  overflow: hidden;
  border: 1px solid oklch(0.912 0.005 250);
}
.dark .table-container {
  border-color: oklch(0.28 0.015 250);
}

/* ── Filter Bar ────────────────────────────────────── */

.filter-bar {
  padding: 0.75rem;
  border-radius: 0.75rem;
  background: oklch(0.96 0.005 250 / 0.3);
  gap: 0.5rem;
}
.dark .filter-bar {
  background: oklch(0.23 0.015 250 / 0.3);
}

/* ── Status Dot Pulse ──────────────────────────────── */

@keyframes status-dot-pulse {
  0% { opacity: 0; transform: scale(0.8); }
  50% { opacity: 1; transform: scale(1.2); }
  100% { opacity: 0; transform: scale(0.8); }
}
.status-dot-pulse {
  position: relative;
}
.status-dot-pulse::after {
  content: '';
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  background: inherit;
  opacity: 0;
  animation: status-dot-pulse 2s ease-in-out infinite;
}

/* ── Metric Change Indicator ──────────────────────── */

.metric-change {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  font-size: 0.625rem;
  font-weight: 600;
  line-height: 1;
  padding: 0.125rem 0.375rem;
  border-radius: 0.25rem;
}
.metric-change.positive {
  color: oklch(0.577 0.245 27.325);
  background: oklch(0.577 0.245 27.325 / 0.08);
}
.metric-change.negative {
  color: oklch(0.627 0.194 149);
  background: oklch(0.627 0.194 149 / 0.08);
}
.dark .metric-change.positive {
  color: oklch(0.637 0.237 22.5);
  background: oklch(0.637 0.237 22.5 / 0.12);
}
.dark .metric-change.negative {
  color: oklch(0.667 0.194 149);
  background: oklch(0.667 0.194 149 / 0.12);
}

/* ── Section Divider ────────────────────────────────── */

.section-divider {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.5rem 0;
}
.section-divider::before,
.section-divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: oklch(0.912 0.005 250);
}
.dark .section-divider::before,
.dark .section-divider::after {
  background: oklch(0.28 0.015 250);
}
.section-divider-label {
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: oklch(0.5 0.02 250);
  white-space: nowrap;
}
.dark .section-divider-label {
  color: oklch(0.65 0.02 250);
}

/* ── Progress Bar Animated Fill ──────────────────── */

.progress-animated {
  overflow: hidden;
}
.progress-animated > div,
.progress-animated [role="progressbar"] {
  transition: width 0.8s cubic-bezier(0.4, 0, 0.2, 1);
}

/* ── Card Hover Glow ──────────────────────────────── */

.card-hover-glow {
  transition: box-shadow 0.25s ease, border-color 0.25s ease;
}
.card-hover-glow:hover {
  box-shadow: 0 0 16px -4px oklch(0.488 0.243 264 / 0.15),
              0 4px 12px -2px oklch(0 0 0 / 0.06);
  border-color: oklch(0.488 0.243 264 / 0.25);
}
.dark .card-hover-glow:hover {
  box-shadow: 0 0 20px -4px oklch(0.588 0.243 264 / 0.2),
              0 4px 12px -2px oklch(0 0 0 / 0.3);
  border-color: oklch(0.588 0.243 264 / 0.3);
}

/* ── Badge Bounce Animation ───────────────────────── */

@keyframes badge-bounce-anim {
  0%, 100% { transform: scale(1); }
  15% { transform: scale(1.25); }
  30% { transform: scale(0.95); }
  45% { transform: scale(1.15); }
  60% { transform: scale(0.98); }
  75% { transform: scale(1.05); }
}
.badge-bounce {
  animation: badge-bounce-anim 0.8s ease-out;
}

/* ── Container Glass (Frosted) ────────────────────── */

.container-glass {
  backdrop-filter: blur(16px) saturate(1.4);
  -webkit-backdrop-filter: blur(16px) saturate(1.4);
  background: oklch(0.985 0.001 250 / 0.75);
  border-bottom: 1px solid oklch(0.912 0.005 250 / 0.6);
}
.dark .container-glass {
  background: oklch(0.13 0.015 250 / 0.75);
  border-bottom-color: oklch(0.28 0.015 250 / 0.6);
}

/* ── Tooltip / Popover Scale-In Animation ────────── */

.tooltip-animate {
  animation: tooltip-scale-in 0.18s ease-out both;
}
@keyframes tooltip-scale-in {
  from {
    opacity: 0;
    transform: scale(0.92) translateY(-2px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

/* ── Table Stripe (Alternating Rows) ──────────────── */

.table-stripe tbody tr:nth-child(even) {
  background: oklch(0.96 0.005 250 / 0.5);
}
.dark .table-stripe tbody tr:nth-child(even) {
  background: oklch(0.22 0.015 250 / 0.4);
}

/* ── Input Focus Ring ──────────────────────────────── */

.input-focus-ring {
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.input-focus-ring:focus {
  border-color: oklch(0.488 0.243 264);
  box-shadow: 0 0 0 3px oklch(0.488 0.243 264 / 0.12);
  outline: none;
}
.dark .input-focus-ring:focus {
  border-color: oklch(0.588 0.243 264);
  box-shadow: 0 0 0 3px oklch(0.588 0.243 264 / 0.18);
}

/* ── Icon Spin (Loading) ──────────────────────────── */

@keyframes icon-spin-anim {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}
.icon-spin {
  animation: icon-spin-anim 1s linear infinite;
}

/* ── Wave Divider ──────────────────────────────────── */

.wave-divider {
  position: relative;
  height: 32px;
  overflow: hidden;
  line-height: 0;
}
.wave-divider svg {
  position: absolute;
  bottom: 0;
  width: 100%;
  height: 100%;
  fill: oklch(0.96 0.005 250);
}
.dark .wave-divider svg {
  fill: oklch(0.22 0.015 250);
}

/* ── Chip / Pill ───────────────────────────────────── */

.chip {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.125rem 0.625rem;
  font-size: 0.6875rem;
  font-weight: 500;
  line-height: 1.5;
  border-radius: 9999px;
  background: oklch(0.96 0.005 250);
  color: oklch(0.35 0.015 250);
  border: 1px solid oklch(0.912 0.005 250);
  transition: background 0.15s ease, border-color 0.15s ease;
  white-space: nowrap;
}
.chip:hover {
  background: oklch(0.93 0.005 250);
  border-color: oklch(0.85 0.01 250);
}
.dark .chip {
  background: oklch(0.23 0.015 250);
  color: oklch(0.8 0.005 250);
  border-color: oklch(0.28 0.015 250);
}
.dark .chip:hover {
  background: oklch(0.28 0.015 250);
  border-color: oklch(0.35 0.015 250);
}

/* ── Stat Card Highlight ──────────────────────────── */

.stat-card-highlight {
  position: relative;
  border-left: 3px solid oklch(0.488 0.243 264);
  background: linear-gradient(
    135deg,
    oklch(0.488 0.243 264 / 0.03) 0%,
    oklch(1 0 0) 60%
  );
}
.dark .stat-card-highlight {
  border-left-color: oklch(0.588 0.243 264);
  background: linear-gradient(
    135deg,
    oklch(0.588 0.243 264 / 0.06) 0%,
    oklch(0.18 0.015 250) 60%
  );
}

/* ── Dashboard Header Gradient ───────────────────── */

.dashboard-header-gradient {
  background: linear-gradient(
    135deg,
    oklch(0.985 0.002 250) 0%,
    oklch(0.97 0.008 200) 50%,
    oklch(0.985 0.003 280) 100%
  );
}
.dark .dashboard-header-gradient {
  background: linear-gradient(
    135deg,
    oklch(0.15 0.01 250) 0%,
    oklch(0.13 0.015 200) 50%,
    oklch(0.15 0.01 280) 100%
  );
}

/* ── Stat Card Hover Lift ────────────────────────── */

.stat-card-lift {
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.stat-card-lift:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 16px -4px oklch(0 0 0 / 0.1);
}
.dark .stat-card-lift:hover {
  box-shadow: 0 8px 16px -4px oklch(0 0 0 / 0.3);
}

/* ── Animated Gradient Text ──────────────────────── */

@keyframes gradient-shift {
  0%, 100% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
}

.gradient-text {
  background: linear-gradient(135deg, oklch(0.488 0.243 264), oklch(0.6 0.2 160), oklch(0.488 0.243 264));
  background-size: 200% 200%;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: gradient-shift 6s ease-in-out infinite;
}

/* ── Skeleton Shimmer (Dark Mode) ────────────────── */

.skeleton-shimmer {
  position: relative;
  overflow: hidden;
}
.skeleton-shimmer::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    transparent 0%,
    oklch(1 0 0 / 0.3) 50%,
    transparent 100%
  );
  animation: shimmer-slide-translate 1.8s ease-in-out infinite;
}
.dark .skeleton-shimmer::after {
  background: linear-gradient(
    90deg,
    transparent 0%,
    oklch(1 0 0 / 0.06) 50%,
    transparent 100%
  );
}

@keyframes shimmer-slide-translate {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}

/* ── Dock Board Grid ─────────────────────────────── */

.dock-grid {
  display: grid;
  gap: 0.75rem;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
}
@media (min-width: 1024px) {
  .dock-grid {
    grid-template-columns: repeat(5, 1fr);
  }
}

/* ── 3D Perspective Card ───────────────────────────── */

.card-3d {
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1), box-shadow 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  transform-style: preserve-3d;
  perspective: 1000px;
}
.card-3d:hover {
  transform: perspective(1000px) rotateX(1deg) rotateY(-1deg) translateY(-4px);
  box-shadow: oklch(0 0 0 / 0.1) 0px 20px 40px -8px, oklch(0 0 0 / 0.05) 0px 8px 16px -4px;
}

/* ── Thin Custom Scrollbar ──────────────────────────── */

.scrollbar-thin {
  scrollbar-width: thin;
  scrollbar-color: oklch(0.7 0.02 250) transparent;
}
.scrollbar-thin::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
.scrollbar-thin::-webkit-scrollbar-track {
  background: transparent;
}
.scrollbar-thin::-webkit-scrollbar-thumb {
  background-color: oklch(0.7 0.02 250);
  border-radius: 3px;
}
.scrollbar-thin::-webkit-scrollbar-thumb:hover {
  background-color: oklch(0.6 0.02 250);
}
.dark .scrollbar-thin {
  scrollbar-color: oklch(0.4 0.02 250) transparent;
}
.dark .scrollbar-thin::-webkit-scrollbar-thumb {
  background-color: oklch(0.4 0.02 250);
}
.dark .scrollbar-thin::-webkit-scrollbar-thumb:hover {
  background-color: oklch(0.5 0.02 250);
}

/* ── Text Balance ──────────────────────────────────── */

.text-balance {
  text-wrap: balance;
}

/* ── Glassmorphism Panel ───────────────────────────── */

.glass-panel {
  backdrop-filter: blur(24px) saturate(180%);
  -webkit-backdrop-filter: blur(24px) saturate(180%);
  background: oklch(1 0 0 / 0.72);
  border: 1px solid oklch(1 0 0 / 0.2);
}
.dark .glass-panel {
  background: oklch(1 0 0 / 0.06);
  border-color: oklch(1 0 0 / 0.1);
}

/* ── Hover Lift Effects ───────────────────────────── */

.hover-lift-sm {
  transition: transform 0.2s cubic-bezier(0.4, 0, 0.2, 1), box-shadow 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}
.hover-lift-sm:hover {
  transform: translateY(-2px);
  box-shadow: oklch(0 0 0 / 0.08) 0px 4px 8px -2px;
}
.dark .hover-lift-sm:hover {
  box-shadow: oklch(0 0 0 / 0.2) 0px 4px 8px -2px;
}

.hover-lift-md {
  transition: transform 0.25s cubic-bezier(0.4, 0, 0.2, 1), box-shadow 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}
.hover-lift-md:hover {
  transform: translateY(-4px);
  box-shadow: oklch(0 0 0 / 0.1) 0px 12px 24px -4px;
}
.dark .hover-lift-md:hover {
  box-shadow: oklch(0 0 0 / 0.25) 0px 12px 24px -4px;
}

/* ── Focus Ring ────────────────────────────────────── */

.ring-focus {
  outline: none;
}
.ring-focus:focus-visible {
  outline: 2px solid oklch(0.488 0.243 264);
  outline-offset: 2px;
  border-radius: var(--radius-sm);
}
.dark .ring-focus:focus-visible {
  outline-color: oklch(0.588 0.243 264);
}

/* ── In-View Animation ─────────────────────────────── */

.animate-in-view {
  opacity: 0;
  transform: translateY(16px);
  transition: opacity 0.5s cubic-bezier(0.4, 0, 0.2, 1), transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}
.animate-in-view.is-visible {
  opacity: 1;
  transform: translateY(0);
}

/* ── Soft Badge ────────────────────────────────────── */

.badge-soft {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  border-radius: 9999px;
  padding: 0.125rem 0.625rem;
  font-size: 0.75rem;
  font-weight: 500;
  background: oklch(0.96 0.01 250);
  border: 1px solid oklch(0.912 0.005 250);
  color: oklch(0.35 0.02 250);
}
.dark .badge-soft {
  background: oklch(0.25 0.015 250);
  border-color: oklch(0.3 0.015 250);
  color: oklch(0.75 0.02 250);
}

/* ── Gradient Divider ──────────────────────────────── */

.divider-gradient {
  height: 1px;
  border: none;
  background: linear-gradient(to right, transparent, oklch(0.85 0.01 250), transparent);
  margin: 1rem 0;
}
.dark .divider-gradient {
  background: linear-gradient(to right, transparent, oklch(0.3 0.015 250), transparent);
}

/* ── Card Shadows ─────────────────────────────────── */

.shadow-card {
  box-shadow: oklch(0 0 0 / 0.04) 0px 1px 3px, oklch(0 0 0 / 0.03) 0px 1px 2px;
}
.dark .shadow-card {
  box-shadow: oklch(0 0 0 / 0.15) 0px 1px 3px, oklch(0 0 0 / 0.1) 0px 1px 2px;
}

.shadow-card-hover {
  box-shadow: oklch(0 0 0 / 0.06) 0px 10px 15px -3px, oklch(0 0 0 / 0.04) 0px 4px 6px -2px;
}
.dark .shadow-card-hover {
  box-shadow: oklch(0 0 0 / 0.2) 0px 10px 15px -3px, oklch(0 0 0 / 0.15) 0px 4px 6px -2px;
}

/* ── 2-Line Text Truncation ─────────────────────────── */

.truncate-2 {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ── Smooth Transition Utility ──────────────────────── */

.transition-smooth {
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

/* ── Skeleton Base ─────────────────────────────────── */

.skeleton-base {
  animation: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
  border-radius: var(--radius);
  background: oklch(0.96 0.005 250 / 0.6);
}
.dark .skeleton-base {
  background: oklch(0.25 0.015 250 / 0.4);
}

/* ── Dot Pattern Background ────────────────────────── */

.dot-pattern {
  background-image: radial-gradient(oklch(0.85 0.01 250) 1px, transparent 1px);
  background-size: 16px 16px;
}
.dark .dot-pattern {
  background-image: radial-gradient(oklch(0.3 0.015 250) 1px, transparent 1px);
}

/* ── Sidebar Item Transition ──────────────────────────────────── */

.sidebar-item-transition {
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  border-radius: 8px;
  margin: 2px 8px;
}
.sidebar-item-transition:hover {
  transform: translateX(4px);
  background-color: oklch(from var(--accent) l c h / 0.3);
}
.sidebar-item-transition.active {
  background: oklch(from var(--primary) l c h / 0.15);
  box-shadow: inset 3px 0 0 var(--primary);
}

/* ── Chart Gradient Fill ──────────────────────────────────────── */

.chart-gradient-fill {
  background: linear-gradient(
    180deg,
    oklch(from var(--chart-1) l c h / 0.4) 0%,
    oklch(from var(--chart-1) l c h / 0.02) 100%
  );
}

/* ── Hover Glow Effects ──────────────────────────────────────── */

.hover-glow-blue {
  transition: box-shadow 0.3s ease;
}
.hover-glow-blue:hover {
  box-shadow:
    0 0 20px oklch(0.65 0.2 250 / 0.15),
    0 4px 12px oklch(0 0 0 / 0.08);
}

.hover-glow-emerald {
  transition: box-shadow 0.3s ease;
}
.hover-glow-emerald:hover {
  box-shadow:
    0 0 20px oklch(0.7 0.2 160 / 0.15),
    0 4px 12px oklch(0 0 0 / 0.08);
}

.hover-glow-amber {
  transition: box-shadow 0.3s ease;
}
.hover-glow-amber:hover {
  box-shadow:
    0 0 20px oklch(0.75 0.18 85 / 0.15),
    0 4px 12px oklch(0 0 0 / 0.08);
}

.dark .hover-glow-blue:hover {
  box-shadow:
    0 0 24px oklch(0.55 0.18 250 / 0.25),
    0 4px 16px oklch(0 0 0 / 0.3);
}
.dark .hover-glow-emerald:hover {
  box-shadow:
    0 0 24px oklch(0.6 0.18 160 / 0.25),
    0 4px 16px oklch(0 0 0 / 0.3);
}
.dark .hover-glow-amber:hover {
  box-shadow:
    0 0 24px oklch(0.65 0.16 85 / 0.25),
    0 4px 16px oklch(0 0 0 / 0.3);
}

/* ── Animate Count Up ────────────────────────────────────────── */

.animate-count-up {
  animation: countUp 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}
@keyframes countUp {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ── Badge Status Dot ────────────────────────────────────────── */

.badge-status-dot {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 500;
  padding: 2px 10px;
  border-radius: 9999px;
}
.badge-status-dot::before {
  content: '';
  width: 6px;
  height: 6px;
  border-radius: 50%;
  flex-shrink: 0;
}
.badge-status-dot.success::before {
  background-color: oklch(0.65 0.2 145);
}
.badge-status-dot.warning::before {
  background-color: oklch(0.75 0.18 85);
}
.badge-status-dot.critical::before {
  background-color: oklch(0.6 0.22 25);
}
.badge-status-dot.info::before {
  background-color: oklch(0.65 0.2 250);
}

.dark .badge-status-dot.success::before {
  background-color: oklch(0.7 0.18 145);
}
.dark .badge-status-dot.warning::before {
  background-color: oklch(0.8 0.16 85);
}
.dark .badge-status-dot.critical::before {
  background-color: oklch(0.65 0.2 25);
}
.dark .badge-status-dot.info::before {
  background-color: oklch(0.7 0.18 250);
}

/* ── Page Transition ─────────────────────────────────────────── */

.page-transition {
  animation: pageIn 0.35s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}
@keyframes pageIn {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ── Card Grid Pattern ───────────────────────────────────────── */

.card-grid-pattern {
  background-image:
    linear-gradient(oklch(from var(--border) l c h / 0.3) 1px, transparent 1px),
    linear-gradient(90deg, oklch(from var(--border) l c h / 0.3) 1px, transparent 1px);
  background-size: 24px 24px;
}

/* ── Nav Icon Animated ───────────────────────────────────────── */

.nav-icon-animated {
  transition: transform 0.25s cubic-bezier(0.34, 1.56, 0.64, 1), color 0.2s ease;
}
.sidebar-item-transition:hover .nav-icon-animated {
  transform: scale(1.15) rotate(-5deg);
}

/* ── Table Header Sticky Glass ───────────────────────────────── */

.table-header-sticky-glass thead th {
  position: sticky;
  top: 0;
  z-index: 10;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  background: oklch(from var(--background) l c h / 0.85);
  border-bottom: 1px solid var(--border);
}
.dark .table-header-sticky-glass thead th {
  background: oklch(from var(--background) l c h / 0.75);
}

/* ── Content Fade In ─────────────────────────────────────────── */

.content-fade-in {
  animation: contentFade 0.4s ease-out forwards;
}
@keyframes contentFade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

/* ── Pulse Ring ──────────────────────────────────────────────── */

.pulse-ring {
  position: relative;
}
.pulse-ring::after {
  content: '';
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  border: 2px solid currentColor;
  animation: pulseRing 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
  opacity: 0;
}
@keyframes pulseRing {
  0% {
    transform: scale(0.8);
    opacity: 0.6;
  }
  100% {
    transform: scale(1.4);
    opacity: 0;
  }
}

/* ── Scrolling Ticker ──────────────────────────────────────── */
.animate-scroll-ticker {
  animation: scrollTicker 60s linear infinite;
}
@keyframes scrollTicker {
  0% { transform: translateX(0); }
  100% { transform: translateX(-33.333%); }
}
.animate-scroll-ticker:hover {
  animation-play-state: paused;
}

/* ── Micro-interaction utility classes ──────────────────── */

.hover-scale-sm {
  transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.hover-scale-sm:hover {
  transform: scale(1.02);
}

.hover-scale-md {
  transition: transform 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.hover-scale-md:hover {
  transform: scale(1.04);
}

.shimmer-loading {
  position: relative;
  overflow: hidden;
}
.shimmer-loading::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    transparent 0%,
    oklch(from var(--background) l c h / 0.4) 50%,
    transparent 100%
  );
  animation: shimmerLoading 2s ease-in-out infinite;
  pointer-events: none;
}
@keyframes shimmerLoading {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}

.border-glow-blue {
  border: 1px solid oklch(0.65 0.15 250 / 0.3);
  transition: border-color 0.3s ease, box-shadow 0.3s ease;
}
.border-glow-blue:hover {
  border-color: oklch(0.65 0.2 250 / 0.6);
  box-shadow: 0 0 12px oklch(0.65 0.2 250 / 0.1);
}
.border-glow-emerald {
  border: 1px solid oklch(0.65 0.15 160 / 0.3);
  transition: border-color 0.3s ease, box-shadow 0.3s ease;
}
.border-glow-emerald:hover {
  border-color: oklch(0.65 0.2 160 / 0.6);
  box-shadow: 0 0 12px oklch(0.65 0.2 160 / 0.1);
}

.card-shine {
  position: relative;
  overflow: hidden;
}
.card-shine::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(
    circle at 30% 30%,
    oklch(1 0 0 / 0.08) 0%,
    transparent 60%
  );
  opacity: 0;
  transition: opacity 0.4s ease;
  pointer-events: none;
  z-index: 1;
}
.card-shine:hover::before {
  opacity: 1;
}

.text-number {
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum";
  letter-spacing: -0.02em;
}

.animate-breathe {
  animation: breathe 3s ease-in-out infinite;
}
@keyframes breathe {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

.ripple-effect {
  position: relative;
  overflow: hidden;
}
.ripple-effect::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0;
  height: 0;
  border-radius: 50%;
  background: oklch(from var(--primary) l c h / 0.15);
  transform: translate(-50%, -50%);
  transition: width 0.4s ease-out, height 0.4s ease-out, opacity 0.4s ease-out;
  opacity: 0;
}
.ripple-effect:active::after {
  width: 200%;
  height: 200%;
  opacity: 1;
  transition: width 0s, height 0s, opacity 0s;
}

.scroll-fade-edges {
  mask-image: linear-gradient(
    to right,
    transparent,
    black 3%,
    black 97%,
    transparent
  );
  -webkit-mask-image: linear-gradient(
    to right,
    transparent,
    black 3%,
    black 97%,
    transparent
  );
}

.status-online {
  color: oklch(0.65 0.2 145);
}
.status-online::after {
  content: '';
  display: inline-block;
  width: 6px;
  height: 6px;
  margin-left: 6px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 6px currentColor;
}
.status-offline {
  color: oklch(0.5 0 0);
}
.status-offline::after {
  content: '';
  display: inline-block;
  width: 6px;
  height: 6px;
  margin-left: 6px;
  border-radius: 50%;
  background: currentColor;
}
.status-busy {
  color: oklch(0.75 0.18 85);
}
.status-busy::after {
  content: '';
  display: inline-block;
  width: 6px;
  height: 6px;
  margin-left: 6px;
  border-radius: 50%;
  background: currentColor;
  animation: breathe 1.5s ease-in-out infinite;
}

/* ── Round 14 Mobile + Interaction CSS ─────────────────────── */

/* Mobile swipe hint indicator */
.swipe-hint-left {
  position: fixed;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 24px;
  height: 64px;
  background: linear-gradient(to right, oklch(from var(--primary) l c h / 0.15), transparent);
  border-radius: 0 8px 8px 0;
  pointer-events: none;
  z-index: 30;
  opacity: 0;
  transition: opacity 0.3s ease;
}
.swipe-hint-left.visible {
  opacity: 1;
}

.swipe-hint-right {
  position: fixed;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 24px;
  height: 64px;
  background: linear-gradient(to left, oklch(from var(--primary) l c h / 0.15), transparent);
  border-radius: 8px 0 0 8px;
  pointer-events: none;
  z-index: 30;
  opacity: 0;
  transition: opacity 0.3s ease;
}
.swipe-hint-right.visible {
  opacity: 1;
}

/* Mobile overflow scroll indicator */
.mobile-scroll-hint {
  position: relative;
}
.mobile-scroll-hint::after {
  content: '';
  position: absolute;
  right: 0;
  top: 0;
  bottom: 0;
  width: 24px;
  background: linear-gradient(to left, oklch(from var(--card) l c h / 1), transparent);
  pointer-events: none;
  border-radius: 0 8px 8px 0;
}

/* Nav item tap feedback */
.nav-tap-feedback {
  transition: transform 0.1s ease;
}
.nav-tap-feedback:active {
  transform: scale(0.92);
}

/* Ripple effect for nav buttons */
.ripple-effect {
  position: relative;
  overflow: hidden;
}
.ripple-effect::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at var(--ripple-x, 50%) var(--ripple-y, 50%), oklch(from var(--primary) l c h / 0.12) 0%, transparent 70%);
  opacity: 0;
  transition: opacity 0.4s ease;
  pointer-events: none;
}
.ripple-effect:active::after {
  opacity: 1;
}

/* Mobile safe area padding bottom for scrollable content */
.mobile-safe-bottom {
  padding-bottom: calc(4rem + env(safe-area-inset-bottom, 0px));
}

/* Glass morphism card for mobile */
.mobile-glass-card {
  background: oklch(from var(--card) l c h / 0.7);
  backdrop-filter: blur(12px) saturate(1.3);
  border: 1px solid oklch(from var(--border) l c h / 0.3);
}

/* Responsive text truncation */
.line-clamp-1 {
  display: -webkit-box;
  -webkit-line-clamp: 1;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.line-clamp-2 {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* Active nav bottom bar */
.nav-active-bar {
  position: absolute;
  bottom: 0;
  left: 8px;
  right: 8px;
  height: 2px;
  border-radius: 1px;
  background: currentColor;
  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Pulse animation for live indicators */
.live-pulse {
  animation: livePulse 2s ease-in-out infinite;
}
@keyframes livePulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

/* Smooth page content transition on mobile */
.page-content-transition {
  transition: opacity 0.2s ease, transform 0.2s ease;
}
.page-content-transition.entering {
  opacity: 0;
  transform: translateX(8px);
}
.page-content-transition.exiting {
  opacity: 0;
  transform: translateX(-8px);
}

/* ── Round 14 CSS Utilities ──────────────────────────────── */

/* Toast notification entrance animation */
.toast-enter {
  animation: toastSlideIn 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}
@keyframes toastSlideIn {
  from { opacity: 0; transform: translateX(100%) scale(0.95); }
  to { opacity: 1; transform: translateX(0) scale(1); }
}

/* Glass card with gradient border */
.card-glass-gradient {
  position: relative;
  background: oklch(from var(--card) l c h / 0.6);
  backdrop-filter: blur(16px) saturate(1.2);
  border: 1px solid oklch(from var(--border) l c h / 0.4);
}
.card-glass-gradient::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(135deg, oklch(0.65 0.2 250 / 0.3), oklch(0.7 0.15 160 / 0.2), oklch(0.75 0.15 85 / 0.2));
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
}

/* Skeleton with gradient animation */
.skeleton-gradient {
  background: linear-gradient(
    90deg,
    oklch(from var(--muted) l c h / 0.5) 0%,
    oklch(from var(--muted) l c h / 0.8) 50%,
    oklch(from var(--muted) l c h / 0.5) 100%
  );
  background-size: 200% 100%;
  animation: skeletonGradient 1.5s ease-in-out infinite;
}
@keyframes skeletonGradient {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

/* Hover zoom effect */
.hover-zoom {
  transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}
.hover-zoom:hover {
  transform: scale(1.02);
}

/* Animated underline */
.animated-underline {
  position: relative;
  display: inline-block;
}
.animated-underline::after {
  content: '';
  position: absolute;
  left: 0;
  bottom: -2px;
  width: 0;
  height: 2px;
  background: oklch(from var(--primary) l c h / 0.6);
  transition: width 0.3s ease;
  border-radius: 1px;
}
.animated-underline:hover::after {
  width: 100%;
}

/* Dot grid pattern background */
.dot-grid-pattern {
  background-image: radial-gradient(circle, oklch(from var(--border) l c h / 0.4) 1px, transparent 1px);
  background-size: 16px 16px;
}

/* Fade from bottom */
.fade-from-bottom {
  animation: fadeFromBottom 0.5s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}
@keyframes fadeFromBottom {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Status indicator bar (vertical) */
.status-bar {
  position: relative;
}
.status-bar::before {
  content: '';
  position: absolute;
  left: 0;
  top: 4px;
  bottom: 4px;
  width: 3px;
  border-radius: 2px;
  background: oklch(from var(--primary) l c h / 0.6);
}
.status-bar-success::before { background: oklch(0.65 0.2 145); }
.status-bar-warning::before { background: oklch(0.75 0.18 85); }
.status-bar-critical::before { background: oklch(0.6 0.24 25); }
.status-bar-info::before { background: oklch(0.6 0.15 250); }

/* Numeric tabular with monospace for data grids */
.data-grid-nums {
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum", "ss01";
  font-family: var(--font-mono), ui-monospace, monospace;
}

/* Card hover border transition */
.hover-border-accent {
  transition: border-color 0.3s ease, box-shadow 0.3s ease;
}
.hover-border-accent:hover {
  border-color: oklch(from var(--primary) l c h / 0.5);
  box-shadow: 0 0 0 1px oklch(from var(--primary) l c h / 0.1);
}

/* Pill badge with left indicator */
.pill-indicator {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 10px;
  border-radius: 9999px;
  font-size: 11px;
  font-weight: 500;
  background: oklch(from var(--muted) l c h / 0.5);
  color: oklch(from var(--foreground) l c h / 0.8);
}
.pill-indicator::before {
  content: '';
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}

/* Smooth scroll container */
.scroll-smooth-container {
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
}

/* Text gradient for headings */
.heading-gradient {
  background: linear-gradient(135deg, oklch(from var(--foreground) l c h / 1) 0%, oklch(from var(--primary) l c h / 0.8) 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

/* ── Print Styles ──────────────────────────────────────────── */
@media print {
  /* Hide interactive elements */
  .no-print,
  [data-slot="sidebar"],
  [role="navigation"],
  button:not(.print-include),
  .mobile-bottom-nav,
  .command-palette-overlay,
  .toast-container {
    display: none !important;
  }

  /* Full-width content */
  main {
    padding: 0 !important;
    margin: 0 !important;
  }

  /* Card borders for print */
  .card, .rounded-xl {
    border: 1px solid #e0e0e0 !important;
    box-shadow: none !important;
    break-inside: avoid;
  }

  /* Remove dark mode */
  .dark {
    color-scheme: light !important;
  }

  :root {
    color-scheme: light !important;
  }

  /* Page headers */
  h1, h2, h3, h4 {
    page-break-after: avoid;
    break-after: avoid;
  }

  /* Avoid breaking inside cards and tables */
  .card, .rounded-xl, table, tr, td, th {
    break-inside: avoid;
  }

  /* Hide interactive elements */
  button, nav, [role="navigation"], [role="tablist"], [role="menubar"],
  [data-radix-popper-content-wrapper], .sidebar, .mobile-bottom-nav,
  .filter-bar, input, select, .export-button, .scroll-area-viewport {
    display: none !important;
  }

  /* Show link URLs */
  a[href]::after {
    content: " (" attr(href) ")";
    font-size: 9pt;
    color: #666;
  }

  body {
    background: white !important;
    color: black !important;
    font-size: 11pt;
  }

  /* Card borders for print */
  .card, .rounded-xl {
    border: 1px solid #e0e0e0 !important;
    box-shadow: none !important;
  }

  /* Table borders for print */
  table {
    border-collapse: collapse !important;
  }
  th, td {
    border: 1px solid #d0d0d0 !important;
  }
  th {
    background: #f5f5f5 !important;
  }

  /* Show print header on reports */
  .print-header {
    display: flex !important;
  }

  /* Remove hover effects */
  .hover\:bg-muted\/40, .group:hover {
    background: inherit !important;
  }

  /* Ensure adequate margins */
  @page {
    margin: 1.5cm;
    @top-right {
      content: "AutoFlow Logistics — Confidential";
      font-size: 8pt;
      color: #999;
    }
    @bottom-center {
      content: "Page " counter(page) " of " counter(pages);
      font-size: 8pt;
      color: #999;
    }
  }

  /* Charts should be visible */
  svg, canvas {
    max-width: 100% !important;
    break-inside: avoid;
  }
}

/* ============================================================
   Custom Toast Styles — overrides Sonner defaults to match theme
   ============================================================ */

/* Container */
.toast-custom {
  --border-radius: 12px;
  --box-shadow: 0 1px 3px 0 rgb(0 0 0 / 0.06), 0 1px 2px -1px rgb(0 0 0 / 0.06);
  --border-color: var(--border);
  font-family: var(--font-geist-sans), ui-sans-serif, system-ui, sans-serif;
}

/* Individual toast item */
[data-sonner-toast] {
  border-radius: var(--border-radius) !important;
  box-shadow: var(--box-shadow) !important;
  border: 1px solid color-mix(in srgb, var(--border) 50%, transparent) !important;
  padding: 12px 14px;
  animation: toast-enter 0.35s cubic-bezier(0.21, 1.02, 0.73, 1) forwards;
}

[data-sonner-toast][data-removed="true"] {
  animation: toast-exit 0.25s cubic-bezier(0.06, 0.71, 0.55, 1) forwards;
}

/* Smooth enter animation */
@keyframes toast-enter {
  0% {
    opacity: 0;
    transform: translateX(40px) scale(0.96);
  }
  100% {
    opacity: 1;
    transform: translateX(0) scale(1);
  }
}

/* Smooth exit animation */
@keyframes toast-exit {
  0% {
    opacity: 1;
    transform: translateX(0) scale(1);
  }
  100% {
    opacity: 0;
    transform: translateX(40px) scale(0.96);
  }
}

/* Title */
.toast-title {
  font-size: 0.8125rem;
  font-weight: 600;
  line-height: 1.3;
}

/* Description */
.toast-description {
  font-size: 0.75rem;
  color: var(--muted-foreground);
  line-height: 1.4;
  margin-top: 2px;
}

/* Close button */
.toast-close {
  top: 8px;
  right: 8px;
  height: 20px;
  width: 20px;
  opacity: 0.4;
  transition: opacity 0.15s;
}
.toast-close:hover {
  opacity: 1;
}

/* Action button */
.toast-action {
  font-size: 0.75rem;
  font-weight: 500;
  padding: 4px 12px;
  border-radius: 8px;
}

/* Cancel button */
.toast-cancel {
  font-size: 0.75rem;
  font-weight: 500;
  padding: 4px 12px;
  border-radius: 8px;
}

/* ============================================================
   Theme Transition — Smooth light/dark mode switching
   ============================================================ */

.theme-transition,
.theme-transition *,
.theme-transition *::before,
.theme-transition *::after {
  transition: background-color 0.35s cubic-bezier(0.4, 0, 0.2, 1),
              color 0.25s cubic-bezier(0.4, 0, 0.2, 1),
              border-color 0.3s cubic-bezier(0.4, 0, 0.2, 1),
              box-shadow 0.3s cubic-bezier(0.4, 0, 0.2, 1),
              opacity 0.25s cubic-bezier(0.4, 0, 0.2, 1) !important;
}

html.theme-transition,
html.theme-transition body {
  transition: background-color 0.35s cubic-bezier(0.4, 0, 0.2, 1),
              color 0.25s cubic-bezier(0.4, 0, 0.2, 1) !important;
}

/* Theme flash overlay animation */
@keyframes theme-flash {
  0% { opacity: 0.15; }
  100% { opacity: 0; }
}
.theme-flash::after {
  content: '';
  position: fixed;
  inset: 0;
  z-index: 9999;
  pointer-events: none;
  background: oklch(1 0 0);
  animation: theme-flash 0.4s ease-out forwards;
}

/* Theme toggle button */
.theme-toggle-btn {
  position: relative;
  border-radius: 9999px;
  overflow: hidden;
}
.theme-toggle-btn::before {
  content: '';
  position: absolute;
  inset: -2px;
  border-radius: 9999px;
  background: conic-gradient(
    from 0deg,
    oklch(0.6 0.15 250),
    oklch(0.7 0.15 180),
    oklch(0.6 0.15 250)
  );
  opacity: 0;
  transition: opacity 0.3s ease;
  z-index: -1;
}
.theme-toggle-btn:hover::before {
  opacity: 0.5;
}
.theme-toggle-btn:active {
  transform: scale(0.92);
}
.theme-toggle-btn svg {
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}
.theme-toggle-btn:active svg {
  transform: rotate(180deg);
}

/* ============================================================
   New CSS Utility Classes — Round 15
   ============================================================ */

/* ── Card Spotlight ────────────────────────────────── */

.card-spotlight {
  position: relative;
  overflow: hidden;
}
.card-spotlight::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: radial-gradient(
    400px circle at var(--mouse-x, 50%) var(--mouse-y, 50%),
    oklch(0.95 0.02 250 / 0.3),
    transparent 60%
  );
  opacity: 0;
  transition: opacity 0.4s ease;
  pointer-events: none;
}
.card-spotlight:hover::after {
  opacity: 1;
}
.dark .card-spotlight::after {
  background: radial-gradient(
    400px circle at var(--mouse-x, 50%) var(--mouse-y, 50%),
    oklch(0.4 0.04 250 / 0.25),
    transparent 60%
  );
}

/* ── Glass Morphism ───────────────────────────────── */

.glass-morphism {
  backdrop-filter: blur(24px) saturate(200%) brightness(1.1);
  -webkit-backdrop-filter: blur(24px) saturate(200%) brightness(1.1);
  background: oklch(0.98 0.002 250 / 0.6);
  border: 1px solid oklch(1 0 0 / 0.25);
  box-shadow: 0 1px 3px oklch(0 0 0 / 0.05), 0 4px 16px oklch(0 0 0 / 0.03);
}
.dark .glass-morphism {
  background: oklch(0.15 0.015 250 / 0.6);
  border-color: oklch(1 0 0 / 0.08);
  box-shadow: 0 1px 3px oklch(0 0 0 / 0.2), 0 4px 16px oklch(0 0 0 / 0.15);
}

/* ── Border Gradient ───────────────────────────────── */

.border-gradient {
  border: 2px solid transparent;
  border-image: linear-gradient(
    135deg,
    oklch(0.55 0.18 250),
    oklch(0.65 0.15 200),
    oklch(0.55 0.18 250)
  ) 1;
}
.dark .border-gradient {
  border-image: linear-gradient(
    135deg,
    oklch(0.5 0.15 250),
    oklch(0.6 0.12 200),
    oklch(0.5 0.15 250)
  ) 1;
}

/* ── Text Glow Blue ────────────────────────────────── */

.text-glow-blue {
  color: oklch(0.55 0.2 250);
  text-shadow: 0 0 8px oklch(0.55 0.2 250 / 0.5), 0 0 20px oklch(0.55 0.2 250 / 0.2);
}
.dark .text-glow-blue {
  color: oklch(0.7 0.18 250);
  text-shadow: 0 0 10px oklch(0.7 0.18 250 / 0.6), 0 0 25px oklch(0.7 0.18 250 / 0.3);
}

/* ── Text Glow Emerald ────────────────────────────── */

.text-glow-emerald {
  color: oklch(0.55 0.17 160);
  text-shadow: 0 0 8px oklch(0.55 0.17 160 / 0.5), 0 0 20px oklch(0.55 0.17 160 / 0.2);
}
.dark .text-glow-emerald {
  color: oklch(0.7 0.17 160);
  text-shadow: 0 0 10px oklch(0.7 0.17 160 / 0.6), 0 0 25px oklch(0.7 0.17 160 / 0.3);
}

/* ── Text Glow Amber ──────────────────────────────── */

.text-glow-amber {
  color: oklch(0.65 0.18 80);
  text-shadow: 0 0 8px oklch(0.65 0.18 80 / 0.5), 0 0 20px oklch(0.65 0.18 80 / 0.2);
}
.dark .text-glow-amber {
  color: oklch(0.8 0.16 80);
  text-shadow: 0 0 10px oklch(0.8 0.16 80 / 0.6), 0 0 25px oklch(0.8 0.16 80 / 0.3);
}

/* ── Hover Expand ─────────────────────────────────── */

.hover-expand {
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1),
              box-shadow 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
.hover-expand:hover {
  transform: scale(1.02);
  box-shadow: 0 8px 24px oklch(0 0 0 / 0.08), 0 2px 8px oklch(0 0 0 / 0.04);
}
.dark .hover-expand:hover {
  box-shadow: 0 8px 24px oklch(0 0 0 / 0.3), 0 2px 8px oklch(0 0 0 / 0.2);
}

/* ── Scroll Shadow Top ─────────────────────────────── */

.scroll-shadow-top {
  mask-image: linear-gradient(to bottom, oklch(0 0 0 / 0.12) 0%, transparent 32px);
  -webkit-mask-image: linear-gradient(to bottom, oklch(0 0 0 / 0.12) 0%, transparent 32px);
}

/* ── Scroll Shadow Bottom ──────────────────────────── */

.scroll-shadow-bottom {
  mask-image: linear-gradient(to top, oklch(0 0 0 / 0.1) 0%, transparent 32px);
  -webkit-mask-image: linear-gradient(to top, oklch(0 0 0 / 0.1) 0%, transparent 32px);
}
.dark .scroll-shadow-bottom {
  mask-image: linear-gradient(to top, oklch(0 0 0 / 0.3) 0%, transparent 32px);
  -webkit-mask-image: linear-gradient(to top, oklch(0 0 0 / 0.3) 0%, transparent 32px);
}

/* ── Stack Card ───────────────────────────────────── */

.stack-card {
  margin-top: -0.5rem;
  position: relative;
  z-index: 1;
}
.stack-card + .stack-card { z-index: 2; }
.stack-card + .stack-card + .stack-card { z-index: 3; }

/* ── Progress Bar Animated ─────────────────────────── */

.progress-bar-animated {
  position: relative;
  overflow: hidden;
}
.progress-bar-animated::after {
  content: '';
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    -45deg,
    transparent,
    transparent 6px,
    oklch(1 0 0 / 0.15) 6px,
    oklch(1 0 0 / 0.15) 12px
  );
  animation: progress-stripes 0.8s linear infinite;
}
.dark .progress-bar-animated::after {
  background: repeating-linear-gradient(
    -45deg,
    transparent,
    transparent 6px,
    oklch(1 0 0 / 0.08) 6px,
    oklch(1 0 0 / 0.08) 12px
  );
}
@keyframes progress-stripes {
  0% { transform: translateX(0); }
  100% { transform: translateX(22.63px); }
}

/* ── Tag Chip ──────────────────────────────────────── */

.tag-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 10px;
  border-radius: 9999px;
  font-size: 0.6875rem;
  font-weight: 500;
  background: oklch(0.96 0.01 250);
  border: 1px solid oklch(0.9 0.01 250);
  color: oklch(0.35 0.05 250);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.tag-chip:hover {
  transform: translateY(-1px);
  box-shadow: 0 2px 8px oklch(0 0 0 / 0.08);
}
.dark .tag-chip {
  background: oklch(0.25 0.02 250);
  border-color: oklch(0.35 0.02 250);
  color: oklch(0.8 0.05 250);
}
.dark .tag-chip:hover {
  box-shadow: 0 2px 8px oklch(0 0 0 / 0.3);
}

/* ── Icon Badge ───────────────────────────────────── */

.icon-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 9999px;
  border: 1px solid oklch(0.88 0.01 250);
  background: oklch(0.97 0.002 250);
  color: oklch(0.4 0.05 250);
  transition: background-color 0.2s ease, border-color 0.2s ease;
}
.icon-badge:hover {
  background: oklch(0.93 0.01 250);
  border-color: oklch(0.8 0.02 250);
}
.dark .icon-badge {
  border-color: oklch(0.3 0.02 250);
  background: oklch(0.2 0.015 250);
  color: oklch(0.75 0.06 250);
}
.dark .icon-badge:hover {
  background: oklch(0.28 0.02 250);
  border-color: oklch(0.4 0.03 250);
}

/* ── Shimmer Border ───────────────────────────────── */

@property --shimmer-angle {
  syntax: '<angle>';
  initial-value: 0deg;
  inherits: false;
}
.shimmer-border {
  position: relative;
  overflow: hidden;
  border: 2px solid transparent;
  background-clip: padding-box;
}
.shimmer-border::before {
  content: '';
  position: absolute;
  inset: -2px;
  z-index: -1;
  border-radius: inherit;
  background: conic-gradient(
    from var(--shimmer-angle, 0deg),
    oklch(0.55 0.18 250),
    oklch(0.7 0.15 160),
    oklch(0.65 0.18 80),
    oklch(0.55 0.18 250)
  );
  animation: shimmer-rotate 3s linear infinite;
}
@keyframes shimmer-rotate {
  0% { --shimmer-angle: 0deg; }
  100% { --shimmer-angle: 360deg; }
}

/* ── Tooltip Arrow ────────────────────────────────── */

.tooltip-arrow {
  position: relative;
}
.tooltip-arrow::after {
  content: '';
  position: absolute;
  bottom: -6px;
  left: 50%;
  transform: translateX(-50%) rotate(45deg);
  width: 12px;
  height: 12px;
  background: oklch(0.15 0.01 250);
  border: 1px solid oklch(0.25 0.01 250);
  border-top: none;
  border-left: none;
}
.dark .tooltip-arrow::after {
  background: oklch(0.2 0.015 250);
  border-color: oklch(0.35 0.02 250);
}

/* ── Skeleton Pulse ────────────────────────────────── */

.skeleton-pulse {
  animation: skeleton-pulse-anim 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
  background: oklch(0.93 0.005 250);
  border-radius: 6px;
}
.dark .skeleton-pulse {
  background: oklch(0.25 0.01 250);
}
@keyframes skeleton-pulse-anim {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

/* ── Group Hover Child ─────────────────────────────── */

.group:hover .group-hover-child {
  transform: translateY(-2px);
  opacity: 1;
}
.group-hover-child {
  transform: translateY(0);
  opacity: 0.7;
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1),
              opacity 0.3s ease;
}

/* ── Focus Within Ring ────────────────────────────── */

.focus-within-ring {
  transition: box-shadow 0.2s ease;
}
.focus-within-ring:focus-within {
  box-shadow: 0 0 0 2px oklch(0.985 0.002 250), 0 0 0 4px oklch(0.55 0.18 250);
}
.dark .focus-within-ring:focus-within {
  box-shadow: 0 0 0 2px oklch(0.15 0.015 250), 0 0 0 4px oklch(0.55 0.15 250);
}

/* ── Scroll Indicator ──────────────────────────────── */

.scroll-indicator {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  animation: scroll-bounce 2s ease-in-out infinite;
}
.scroll-indicator svg {
  color: oklch(0.5 0.02 250);
}
@keyframes scroll-bounce {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(6px); }
}

/* ── Resize Handle ────────────────────────────────── */

.resize-handle {
  width: 8px;
  cursor: col-resize;
  background: transparent;
  position: relative;
  transition: background-color 0.2s ease;
  flex-shrink: 0;
}
.resize-handle::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 2px;
  height: 24px;
  border-radius: 1px;
  background: oklch(0.75 0.02 250);
  transition: background-color 0.2s ease, height 0.2s ease;
}
.resize-handle:hover::after,
.resize-handle:active::after {
  background: oklch(0.55 0.18 250);
  height: 32px;
}
.dark .resize-handle::after {
  background: oklch(0.4 0.02 250);
}
.dark .resize-handle:hover::after,
.dark .resize-handle:active::after {
  background: oklch(0.6 0.15 250);
}

/* ── Data Viz Gradient ────────────────────────────── */

.data-viz-gradient {
  background: linear-gradient(
    135deg,
    oklch(0.97 0.01 250) 0%,
    oklch(0.98 0.015 220) 50%,
    oklch(0.97 0.01 250) 100%
  );
}
.dark .data-viz-gradient {
  background: linear-gradient(
    135deg,
    oklch(0.18 0.015 250) 0%,
    oklch(0.16 0.02 220) 50%,
    oklch(0.18 0.015 250) 100%
  );
}

/* ── Card Morph (3D Hover) ──────────────────────── */

.card-morph {
  transition: transform 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94),
              box-shadow 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  transform-style: preserve-3d;
  perspective: 800px;
}
.card-morph:hover {
  transform: rotateX(2deg) translateY(-4px);
  box-shadow: 0 20px 40px oklch(0 0 0 / 0.08), 0 8px 16px oklch(0 0 0 / 0.04);
}
.dark .card-morph:hover {
  box-shadow: 0 20px 40px oklch(0 0 0 / 0.3), 0 8px 16px oklch(0 0 0 / 0.2);
}

/* ── Text Shimmer ────────────────────────────────── */

.text-shimmer {
  background: linear-gradient(
    90deg,
    oklch(0.4 0.05 250) 0%,
    oklch(0.55 0.2 250) 25%,
    oklch(0.7 0.15 200) 50%,
    oklch(0.55 0.2 250) 75%,
    oklch(0.4 0.05 250) 100%
  );
  background-size: 200% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: text-shimmer-move 3s linear infinite;
}
.dark .text-shimmer {
  background: linear-gradient(
    90deg,
    oklch(0.6 0.08 250) 0%,
    oklch(0.75 0.18 250) 25%,
    oklch(0.85 0.12 200) 50%,
    oklch(0.75 0.18 250) 75%,
    oklch(0.6 0.08 250) 100%
  );
  background-size: 200% 100%;
  -webkit-background-clip: text;
  background-clip: text;
}
@keyframes text-shimmer-move {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

/* ── Glow Border Blue ────────────────────────────── */

.glow-border-blue {
  box-shadow: 0 0 0 1px oklch(0.55 0.18 250 / 0.3),
              0 0 15px oklch(0.55 0.18 250 / 0.1);
  transition: box-shadow 0.3s ease;
}
.glow-border-blue:hover {
  box-shadow: 0 0 0 1px oklch(0.55 0.18 250 / 0.5),
              0 0 25px oklch(0.55 0.18 250 / 0.15),
              0 0 50px oklch(0.55 0.18 250 / 0.05);
}
.dark .glow-border-blue {
  box-shadow: 0 0 0 1px oklch(0.55 0.15 250 / 0.4),
              0 0 20px oklch(0.55 0.15 250 / 0.15);
}
.dark .glow-border-blue:hover {
  box-shadow: 0 0 0 1px oklch(0.55 0.15 250 / 0.6),
              0 0 30px oklch(0.55 0.15 250 / 0.2),
              0 0 60px oklch(0.55 0.15 250 / 0.08);
}

/* ── Glow Border Emerald ─────────────────────────── */

.glow-border-emerald {
  box-shadow: 0 0 0 1px oklch(0.65 0.17 160 / 0.3),
              0 0 15px oklch(0.65 0.17 160 / 0.1);
  transition: box-shadow 0.3s ease;
}
.glow-border-emerald:hover {
  box-shadow: 0 0 0 1px oklch(0.65 0.17 160 / 0.5),
              0 0 25px oklch(0.65 0.17 160 / 0.15),
              0 0 50px oklch(0.65 0.17 160 / 0.05);
}
.dark .glow-border-emerald {
  box-shadow: 0 0 0 1px oklch(0.65 0.14 160 / 0.4),
              0 0 20px oklch(0.65 0.14 160 / 0.15);
}
.dark .glow-border-emerald:hover {
  box-shadow: 0 0 0 1px oklch(0.65 0.14 160 / 0.6),
              0 0 30px oklch(0.65 0.14 160 / 0.2),
              0 0 60px oklch(0.65 0.14 160 / 0.08);
}

/* ── Glow Border Amber ───────────────────────────── */

.glow-border-amber {
  box-shadow: 0 0 0 1px oklch(0.75 0.16 80 / 0.3),
              0 0 15px oklch(0.75 0.16 80 / 0.1);
  transition: box-shadow 0.3s ease;
}
.glow-border-amber:hover {
  box-shadow: 0 0 0 1px oklch(0.75 0.16 80 / 0.5),
              0 0 25px oklch(0.75 0.16 80 / 0.15),
              0 0 50px oklch(0.75 0.16 80 / 0.05);
}
.dark .glow-border-amber {
  box-shadow: 0 0 0 1px oklch(0.75 0.14 80 / 0.4),
              0 0 20px oklch(0.75 0.14 80 / 0.15);
}
.dark .glow-border-amber:hover {
  box-shadow: 0 0 0 1px oklch(0.75 0.14 80 / 0.6),
              0 0 30px oklch(0.75 0.14 80 / 0.2),
              0 0 60px oklch(0.75 0.14 80 / 0.08);
}

/* ── Ripple Click Effect ─────────────────────────── */

.ripple {
  position: relative;
  overflow: hidden;
}
.ripple::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0;
  height: 0;
  border-radius: 50%;
  background: oklch(0 0 0 / 0.08);
  transform: translate(-50%, -50%) scale(0);
  transition: width 0.5s ease, height 0.5s ease, opacity 0.5s ease;
  opacity: 0;
}
.ripple:active::after {
  width: 300%;
  height: 300%;
  opacity: 1;
  transition: width 0s, height 0s, opacity 0s;
}
.dark .ripple::after {
  background: oklch(1 0 0 / 0.06);
}

/* ── Float Animation ─────────────────────────────── */

.float-animation {
  animation: float-bob 3s ease-in-out infinite;
}
@keyframes float-bob {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-4px); }
}

/* ── Marquee ──────────────────────────────────────── */

.marquee {
  overflow: hidden;
  white-space: nowrap;
}
.marquee > * {
  display: inline-block;
  animation: marquee-scroll 20s linear infinite;
}
@keyframes marquee-scroll {
  0% { transform: translateX(0%); }
  100% { transform: translateX(-50%); }
}

/* ── Dot Grid Background ─────────────────────────── */

.dot-grid-bg {
  background-image: radial-gradient(circle, oklch(0.7 0.01 250 / 0.4) 1px, transparent 1px);
  background-size: 20px 20px;
}
.dark .dot-grid-bg {
  background-image: radial-gradient(circle, oklch(0.35 0.02 250 / 0.4) 1px, transparent 1px);
}

/* ── Gradient Border Animated ────────────────────── */

@property --border-angle {
  syntax: '<angle>';
  initial-value: 0deg;
  inherits: false;
}
.gradient-border-animated {
  position: relative;
  border: 2px solid transparent;
  background-clip: padding-box;
}
.gradient-border-animated::before {
  content: '';
  position: absolute;
  inset: -2px;
  z-index: -1;
  border-radius: inherit;
  background: conic-gradient(
    from var(--border-angle, 0deg),
    oklch(0.55 0.18 250),
    oklch(0.7 0.15 160),
    oklch(0.65 0.18 80),
    oklch(0.65 0.2 300),
    oklch(0.55 0.18 250)
  );
  animation: gradient-border-spin 4s linear infinite;
}
@keyframes gradient-border-spin {
  0% { --border-angle: 0deg; }
  100% { --border-angle: 360deg; }
}

/* ── Card Stacked ────────────────────────────────── */

.card-stacked + .card-stacked {
  margin-top: -8px;
}
.card-stacked:nth-child(1) { z-index: 3; }
.card-stacked:nth-child(2) { z-index: 2; }
.card-stacked:nth-child(3) { z-index: 1; }
.card-stacked:nth-child(n+4) { z-index: 0; }
.card-stacked:hover {
  z-index: 10 !important;
  transform: translateY(-2px);
  transition: transform 0.25s ease, z-index 0s;
}

/* ── Status Indicator ────────────────────────────── */

.status-indicator {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.status-indicator::before {
  content: '';
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: oklch(0.65 0.17 160);
  box-shadow: 0 0 0 0 oklch(0.65 0.17 160 / 0.4);
  animation: status-indicator-pulse 2s ease-in-out infinite;
  flex-shrink: 0;
}
@keyframes status-indicator-pulse {
  0%, 100% { box-shadow: 0 0 0 0 oklch(0.65 0.17 160 / 0.4); }
  50% { box-shadow: 0 0 0 5px oklch(0.65 0.17 160 / 0); }
}

/* ── Noise Background ────────────────────────────── */

.noise-bg {
  position: relative;
}
.noise-bg::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 0;
  opacity: 0.03;
  border-radius: inherit;
  pointer-events: none;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  background-repeat: repeat;
  background-size: 256px 256px;
}
.noise-bg > * {
  position: relative;
  z-index: 1;
}
.dark .noise-bg::before {
  opacity: 0.05;
}

/* ── Glitch Text ─────────────────────────────────── */

.glitch-text {
  position: relative;
}
.glitch-text:hover {
  animation: glitch-jitter 0.3s ease-in-out;
  text-shadow: 2px 0 oklch(0.55 0.2 250 / 0.6),
               -2px 0 oklch(0.65 0.2 300 / 0.6);
}
@keyframes glitch-jitter {
  0% { text-shadow: 2px 0 oklch(0.55 0.2 250 / 0.6), -2px 0 oklch(0.65 0.2 300 / 0.6); }
  20% { text-shadow: -2px 0 oklch(0.55 0.2 250 / 0.8), 2px 0 oklch(0.65 0.2 300 / 0.8); clip-path: inset(20% 0 60% 0); }
  40% { text-shadow: 2px 1px oklch(0.55 0.2 250 / 0.4), -2px -1px oklch(0.65 0.2 300 / 0.4); clip-path: inset(60% 0 10% 0); }
  60% { text-shadow: -1px -2px oklch(0.55 0.2 250 / 0.6), 1px 2px oklch(0.65 0.2 300 / 0.6); clip-path: inset(40% 0 30% 0); }
  80% { text-shadow: 2px 0 oklch(0.55 0.2 250 / 0.3), -2px 0 oklch(0.65 0.2 300 / 0.3); clip-path: inset(10% 0 70% 0); }
  100% { text-shadow: 2px 0 oklch(0.55 0.2 250 / 0.6), -2px 0 oklch(0.65 0.2 300 / 0.6); clip-path: none; }
}

/* ── Hover Skew ───────────────────────────────────── */

.hover-skew {
  transition: transform 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.hover-skew:hover {
  transform: skewX(-2deg);
}

/* ── Badge Dot ────────────────────────────────────── */

.badge-dot {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  border-radius: 9999px;
  padding-left: 8px;
  font-size: 10px;
  font-weight: 600;
  line-height: 1;
}
.badge-dot::before {
  content: '';
  width: 6px;
  height: 6px;
  border-radius: 50%;
  flex-shrink: 0;
  background: currentColor;
}

/* ── Scrollbar Glass ─────────────────────────────── */

.scrollbar-glass {
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;
  transition: scrollbar-color 0.3s ease;
}
.scrollbar-glass:hover {
  scrollbar-color: oklch(0.8 0.02 250 / 0.3) transparent;
}
.scrollbar-glass::-webkit-scrollbar {
  width: 6px;
}
.scrollbar-glass::-webkit-scrollbar-track {
  background: transparent;
}
.scrollbar-glass::-webkit-scrollbar-thumb {
  background: transparent;
  border-radius: 9999px;
  transition: background 0.3s ease;
}
.scrollbar-glass:hover::-webkit-scrollbar-thumb {
  background: oklch(0.8 0.02 250 / 0.25);
  backdrop-filter: blur(8px);
}
.dark .scrollbar-glass:hover {
  scrollbar-color: oklch(0.4 0.02 250 / 0.4) transparent;
}
.dark .scrollbar-glass:hover::-webkit-scrollbar-thumb {
  background: oklch(0.4 0.03 250 / 0.35);
}

/* ── Accordion Smooth ────────────────────────────── */

.accordion-smooth {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}
.accordion-smooth[data-open="true"] {
  grid-template-rows: 1fr;
}
.accordion-smooth > * {
  overflow: hidden;
}

/* ── Input Underline ─────────────────────────────── */

.input-underline {
  border: none;
  border-bottom: 2px solid oklch(0.85 0.01 250);
  border-radius: 0;
  outline: none;
  background: transparent;
  transition: border-color 0.3s ease;
  position: relative;
}
.input-underline::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 50%;
  width: 0;
  height: 2px;
  background: oklch(0.55 0.18 250);
  transition: width 0.3s ease, left 0.3s ease;
}
.input-underline:focus {
  border-bottom-color: transparent;
}
.input-underline:focus::after {
  width: 100%;
  left: 0;
}
.dark .input-underline {
  border-bottom-color: oklch(0.3 0.02 250);
}
.dark .input-underline::after {
  background: oklch(0.6 0.15 250);
}

/* ── Card Press ──────────────────────────────────── */

.card-press {
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  box-shadow: 0 2px 8px oklch(0 0 0 / 0.06), 0 1px 2px oklch(0 0 0 / 0.04);
}
.card-press:hover {
  transform: translateY(2px);
  box-shadow: 0 1px 3px oklch(0 0 0 / 0.04);
}
.dark .card-press {
  box-shadow: 0 2px 8px oklch(0 0 0 / 0.2), 0 1px 2px oklch(0 0 0 / 0.1);
}
.dark .card-press:hover {
  box-shadow: 0 1px 3px oklch(0 0 0 / 0.15);
}

/* ── Skeleton Wave ───────────────────────────────── */

.skeleton-wave {
  background: linear-gradient(
    90deg,
    oklch(0.93 0.005 250) 0%,
    oklch(0.97 0.002 250) 40%,
    oklch(0.93 0.005 250) 80%
  );
  background-size: 200% 100%;
  border-radius: 6px;
  animation: skeleton-wave-move 1.8s ease-in-out infinite;
}
.dark .skeleton-wave {
  background: linear-gradient(
    90deg,
    oklch(0.22 0.01 250) 0%,
    oklch(0.26 0.008 250) 40%,
    oklch(0.22 0.01 250) 80%
  );
  background-size: 200% 100%;
}
@keyframes skeleton-wave-move {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

