}
.tab-active-indicator::after {
  content: '';
  position: absolute;
  bottom: -1px;
  left: 50%;
  transform: translateX(-50%);
  width: 60%;
  height: 2px;
  background: linear-gradient(90deg, oklch(0.55 0.2 250), oklch(0.65 0.18 160));
