}
.animate-scale-in-bounce {
  animation: animate-scale-bounce 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) both;
}

@keyframes micro-fade-in-up-delayed {
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: translateY(0); }
}
.animate-fade-in-up-delayed {
  opacity: 0;
  animation: micro-fade-in-up-delayed 0.5s ease-out 0.3s both;
}

@keyframes animate-float {
  0%, 100% { transform: translateY(0); }
  50%      { transform: translateY(-4px); }
}
.animate-float {
  animation: animate-float 3s ease-in-out infinite;
}

/* ── Glass & Depth ────────────────────────────────── */

.glass-card-elevated {
  backdrop-filter: blur(20px) saturate(1.3);
  -webkit-backdrop-filter: blur(20px) saturate(1.3);
  background: oklch(1 0 0 / 0.1);
  box-shadow: oklch(0 0 0 / 0.06) 0px 4px 12px -2px,
              oklch(0 0 0 / 0.04) 0px 2px 4px -1px;
  border-radius: 0.75rem;
}
.dark .glass-card-elevated {
  background: oklch(0 0 0 / 0.2);
  box-shadow: oklch(0 0 0 / 0.2) 0px 4px 12px -2px,
              oklch(0 0 0 / 0.15) 0px 2px 4px -1px;
}

.glass-border {
  border: 1px solid oklch(1 0 0 / 0.2);
  box-shadow: inset 0 1px 0 oklch(1 0 0 / 0.05);
}
.dark .glass-border {
  border-color: oklch(1 0 0 / 0.1);
  box-shadow: inset 0 1px 0 oklch(1 0 0 / 0.03);
}

.depth-shadow-sm {
  box-shadow: oklch(0 0 0 / 0.08) 0px 1px 3px;
}
.dark .depth-shadow-sm {
  box-shadow: oklch(0 0 0 / 0.3) 0px 1px 3px;
}

.depth-shadow-md {
  box-shadow: oklch(0 0 0 / 0.1) 0px 4px 12px;
}
.dark .depth-shadow-md {
  box-shadow: oklch(0 0 0 / 0.4) 0px 4px 12px;
}

.depth-shadow-lg {
  box-shadow: oklch(0 0 0 / 0.12) 0px 8px 24px;
}
.dark .depth-shadow-lg {
  box-shadow: oklch(0 0 0 / 0.5) 0px 8px 24px;
}

/* ── Interactive States ───────────────────────────── */

.hover-lift {
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.hover-lift:hover {
  transform: translateY(-2px);
  box-shadow: oklch(0 0 0 / 0.1) 0px 4px 12px -2px;
}
.dark .hover-lift:hover {
  box-shadow: oklch(0 0 0 / 0.25) 0px 4px 12px -2px;
}

.hover-scale-smooth {
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
.hover-scale-smooth:hover {
  transform: scale(1.02);
}

.active-press {
  transition: transform 0.1s ease;
}
.active-press:active {
  transform: scale(0.98);
}

.focus-visible-ring-lg {
  outline: none;
}
.focus-visible-ring-lg:focus-visible {
  box-shadow: 0 0 0 2px oklch(1 0 0),
              0 0 0 4px oklch(0.623 0.214 259.815 / 0.5);
  border-radius: var(--radius);
}
.dark .focus-visible-ring-lg:focus-visible {
  box-shadow: 0 0 0 2px oklch(0.22 0.015 250),
              0 0 0 4px oklch(0.707 0.165 254.624 / 0.5);
}

/* ── Data Visualization ───────────────────────────── */

.data-bar {
  height: 0.5rem;
  border-radius: 9999px;
  background: oklch(0.96 0.005 250);
  overflow: hidden;
}
.dark .data-bar {
  background: oklch(0.25 0.015 250);
}

.data-bar-fill {
  height: 100%;
  border-radius: 9999px;
  background: linear-gradient(to right, oklch(0.623 0.214 259.815), oklch(0.707 0.165 254.624));
  transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}
.dark .data-bar-fill {
  background: linear-gradient(to right, oklch(0.707 0.165 254.624), oklch(0.768 0.149 262.881));
}

.data-bar-fill-success {
  height: 100%;
  border-radius: 9999px;
  background: linear-gradient(to right, oklch(0.696 0.17 163.225), oklch(0.765 0.177 163.223));
  transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.data-bar-fill-warning {
  height: 100%;
  border-radius: 9999px;
  background: linear-gradient(to right, oklch(0.769 0.188 70.08), oklch(0.828 0.189 84.429));
  transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.data-bar-fill-danger {
  height: 100%;
  border-radius: 9999px;
  background: linear-gradient(to right, oklch(0.637 0.237 25.331), oklch(0.704 0.191 22.216));
  transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

/* ── Layout & Container ───────────────────────────── */

.scroll-y-smooth {
  overflow-y: auto;
  scroll-behavior: smooth;
}

.grid-auto-fill {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: 1rem;
}

.stack-y {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.inline-flex-center {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

/* ── Typography & Visual ──────────────────────────── */

.text-muted-dot {
  color: oklch(0.7 0.01 260);
}
.dark .text-muted-dot {
  color: oklch(0.6 0.01 260);
}

.text-label {
  text-transform: uppercase;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  color: oklch(0.55 0.015 260);
}
.dark .text-label {
  color: oklch(0.65 0.015 260);
}

.divider-gradient-subtle {
  height: 1px;
  border: none;
  background: linear-gradient(to right, transparent, oklch(0.8 0.02 260), transparent);
}
.dark .divider-gradient-subtle {
  background: linear-gradient(to right, transparent, oklch(0.3 0.02 260), transparent);
}

@keyframes shimmer-move {
  0%   { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}
.shimmer-surface {
  background: linear-gradient(
    90deg,
    oklch(0.96 0.005 250) 25%,
    oklch(0.93 0.005 250) 50%,
    oklch(0.96 0.005 250) 75%
  );
  background-size: 200% 100%;
  animation: shimmer-move 2s ease-in-out infinite;
}
.dark .shimmer-surface {
  background: linear-gradient(
    90deg,
    oklch(0.22 0.015 250) 25%,
    oklch(0.28 0.015 250) 50%,
    oklch(0.22 0.015 250) 75%
  );
  background-size: 200% 100%;
}

.corner-accent {
  position: relative;
  overflow: hidden;
}
.corner-accent::before {
  content: '';
  position: absolute;
  top: 0;
  right: 0;
  width: 0;
  height: 0;
  border-style: solid;
  border-width: 0 8px 8px 0;
  border-color: transparent oklch(0.488 0.243 264) transparent transparent;
}
.dark .corner-accent::before {
  border-color: transparent oklch(0.588 0.243 264) transparent transparent;
}

/* ============================================================================ */
/* DENSITY SYSTEM */
/* ============================================================================ */

:root {
  --spacing-multiplier: 1;
}

[data-density="compact"] {
  --spacing-multiplier: 0.75;
}
[data-density="comfortable"] {
  --spacing-multiplier: 1;
}
[data-density="spacious"] {
  --spacing-multiplier: 1.25;
}

/* ============================================================================ */
/* ANIMATION DISABLE */
/* ============================================================================ */

.no-animations *,
.no-animations *::before,
.no-animations *::after {
  animation-duration: 0.01ms !important;
  animation-iteration-count: 1 !important;
  transition-duration: 0.01ms !important;
  scroll-behavior: auto !important;
}

/* ============================================================================ */
/* ROUND 12 - NEW CSS MICRO-INTERACTIONS & ENHANCEMENTS
/* ============================================================================ */

/* ---- Tag Chip Pill ---- */
.tag-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  white-space: nowrap;
  border-radius: 9999px;
  transition: all 0.2s ease;
}
.tag-chip:hover {
  filter: brightness(0.95);
}

/* ---- Data Card Hover Glow ---- */
.data-card {
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
.data-card:hover {
  border-color: oklch(var(--primary) / 0.2);
  box-shadow: 0 4px 16px -4px oklch(var(--primary) / 0.08),
              0 2px 4px -2px oklch(var(--border) / 0.5);
  transform: translateY(-1px);
}

/* ---- Table Row Hover Glow ---- */
.table-row-hover tbody tr {
  transition: background-color 0.2s ease, box-shadow 0.2s ease;
}
.table-row-hover tbody tr:hover {
  background-color: oklch(var(--muted) / 0.3);
  box-shadow: inset 3px 0 0 oklch(var(--primary) / 0.5);
}

/* ---- Card Accent Colors ---- */
.card-accent-blue {
  border-top-color: oklch(0.623 0.214 259);
}
.card-accent-green {
  border-top-color: oklch(0.696 0.17 163);
}
.card-accent-red {
  border-top-color: oklch(0.637 0.237 25);
}
.card-accent-amber {
  border-top-color: oklch(0.769 0.188 79);
}
.card-accent-purple {
  border-top-color: oklch(0.585 0.233 293);
}

/* ---- Card Shine Effect ---- */
.card-shine {
  position: relative;
  overflow: hidden;
}
.card-shine::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 50%;
  height: 100%;
  background: linear-gradient(
    90deg,
    transparent,
    oklch(1 / 0.03),
    transparent
  );
  transition: left 0.6s ease;
  pointer-events: none;
  z-index: 1;
}
.card-shine:hover::before {
  left: 150%;
}

/* ---- Button Press Effect ---- */
.btn-press {
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}
.btn-press:active {
  transform: scale(0.96);
  box-shadow: inset 0 1px 2px oklch(0 0 0 / 0.1);
}

/* ---- Float Animation (Infinite) ---- */
@keyframes floatSubtle {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-4px); }
}
.float-animation {
  animation: floatSubtle 3s ease-in-out infinite;
}

/* ---- Status Dot Pulse ---- */
.status-dot-pulse {
  position: relative;
}
.status-dot-pulse::after {
  content: '';
  position: absolute;
  inset: -2px;
  border-radius: 9999px;
  background: inherit;
  opacity: 0.4;
  animation: statusPulse 2s ease-in-out infinite;
}
@keyframes statusPulse {
  0%, 100% { transform: scale(1); opacity: 0.4; }
  50% { transform: scale(1.5); opacity: 0; }
}

/* ---- Scrollbar Glass ---- */
.scrollbar-glass::-webkit-scrollbar {
  width: 6px;
}
.scrollbar-glass::-webkit-scrollbar-track {
  background: transparent;
}
.scrollbar-glass::-webkit-scrollbar-thumb {
  background: oklch(0 0 0 / 0.1);
  border-radius: 3px;
}
.scrollbar-glass::-webkit-scrollbar-thumb:hover {
  background: oklch(0 0 0 / 0.2);
}

/* ---- Card Depth System ---- */
.card-depth {
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}
.card-depth:hover {
  box-shadow: 0 1px 3px oklch(0 0 0 / 0.04),
              0 4px 12px -4px oklch(0 0 0 / 0.08);
}

/* ---- Filter Bar Styling ---- */
.filter-bar {
  padding: 0.25rem 0;
}
.filter-bar [class*="SelectTrigger"],
.filter-bar [class*="Input"] {
  border-radius: 0.5rem;
  transition: all 0.2s ease;
}
.filter-bar [class*="SelectTrigger"]:hover,
.filter-bar [class*="Input"]:hover {
  border-color: oklch(var(--primary) / 0.4);
  box-shadow: 0 0 0 2px oklch(var(--primary) / 0.05);
}

/* ---- Badge Glow Effects ---- */
.badge-glow-critical {
  box-shadow: 0 0 8px oklch(0.637 0.237 25 / 0.3);
}
.badge-glow-warning {
  box-shadow: 0 0 8px oklch(0.769 0.188 79 / 0.3);
}

/* ---- Table Stripe (Alternating Rows) ---- */
.table-stripe tbody tr:nth-child(even) {
  background-color: oklch(var(--muted) / 0.08);
}
.table-stripe tbody tr:nth-child(even):hover {
  background-color: oklch(var(--muted) / 0.15);
}

/* ---- Table Header Sticky Glass ---- */
.table-header-sticky-glass {
  backdrop-filter: blur(8px);
  background: oklch(var(--card) / 0.85) !important;
}

/* ---- Mobile Scroll Hint ---- */
.mobile-scroll-hint {
  -webkit-overflow-scrolling: touch;
}
.mobile-scroll-hint:after {
  content: '';
  position: sticky;
  right: 0;
  top: 0;
  bottom: 0;
  width: 40px;
  background: linear-gradient(to right, transparent, oklch(var(--background)));
  pointer-events: none;
}

/* ---- Gradient Text ---- */
.gradient-text {
  background: linear-gradient(135deg, oklch(0.623 0.214 259), oklch(0.585 0.233 293));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* ---- Text Glow Blue ---- */
.text-glow-blue {
  text-shadow: 0 0 8px oklch(0.623 0.214 259 / 0.5);
}

/* ---- Dashboard Header Gradient ---- */
.dashboard-header-gradient {
  background: linear-gradient(135deg, oklch(var(--card)) 0%, oklch(var(--muted) / 0.3) 100%);
}
.bg-mesh-gradient {
  background-image:
    radial-gradient(at 20% 80%, oklch(var(--primary) / 0.06) 0%, transparent 50%),
    radial-gradient(at 80% 20%, oklch(0.585 0.233 293 / 0.04) 0%, transparent 50%);
}

/* ---- Data Row Enter Animation ---- */
.data-row-enter {
  animation: dataRowEnter 0.4s ease-out both;
}
@keyframes dataRowEnter {
  from {
    opacity: 0;
    transform: translateX(-8px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

/* ---- Number Tabular Fonts ---- */
.text-number,
.tabular-nums {
  font-variant-numeric: tabular-nums;
}

/* ---- Hover Glow Variants ---- */
.hover-glow-blue:hover {
  box-shadow: 0 0 12px oklch(0.623 0.214 259 / 0.2);
}
.hover-glow-amber:hover {
  box-shadow: 0 0 12px oklch(0.769 0.188 79 / 0.2);
}
.hover-glow-red:hover {
  box-shadow: 0 0 12px oklch(0.637 0.237 25 / 0.2);
}

/* ---- Scale Transition Variants ---- */
.hover-scale-sm {
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.hover-scale-sm:hover {
  transform: scale(1.01);
}

/* ---- Shadow Inner Soft ---- */
.shadow-inner-soft {
  box-shadow: inset 0 1px 3px oklch(0 0 0 / 0.06);
}

/* ---- Stagger Children System ---- */
.stagger-children > * {
  animation: staggerFadeIn 0.4s ease-out both;
}
.stagger-children > *:nth-child(1)  { animation-delay: 0ms; }
.stagger-children > *:nth-child(2)  { animation-delay: 50ms; }
.stagger-children > *:nth-child(3)  { animation-delay: 100ms; }
.stagger-children > *:nth-child(4)  { animation-delay: 150ms; }
.stagger-children > *:nth-child(5)  { animation-delay: 200ms; }
.stagger-children > *:nth-child(6)  { animation-delay: 250ms; }
.stagger-children > *:nth-child(7)  { animation-delay: 300ms; }
.stagger-children > *:nth-child(8)  { animation-delay: 350ms; }
.stagger-children > *:nth-child(9)  { animation-delay: 400ms; }
.stagger-children > *:nth-child(10) { animation-delay: 450ms; }
.stagger-children > *:nth-child(11) { animation-delay: 500ms; }
.stagger-children > *:nth-child(12) { animation-delay: 550ms; }
@keyframes staggerFadeIn {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ---- Page Content Transition ---- */
.page-content-transition {
  transition: opacity 0.2s ease, transform 0.2s ease;
}
.page-content-transition.exiting {
  opacity: 0;
  transform: translateX(-16px);
}
.page-content-transition.entering {
  opacity: 0;
  transform: translateX(16px);
}

/* ---- Chart Card Hover ---- */
.chart-card {
  transition: all 0.3s ease;
}
.chart-card:hover {
  border-color: oklch(var(--border));
  box-shadow: 0 4px 20px -4px oklch(0 0 0 / 0.06);
}

/* ---- Flex Center Utility ---- */
.flex-center {
  display: flex;
  flex-direction: column;
  align-items: center;
}

/* ---- Nav Icon Animated ---- */
.nav-icon-animated {
  transition: transform 0.2s ease;
}
.nav-icon-animated:hover {
  transform: scale(1.1);
}

/* ---- Route Line Animated (Warehouse Map) ---- */
.route-line-animated {
  animation: route-dash-flow 20s linear infinite;
}
@keyframes route-dash-flow {
  to {
    stroke-dashoffset: -260;
  }
}

/* ---- Route Particle (animated dots on map) ---- */
.route-particle-animated-1 {
  fill: oklch(0.7 0.15 250);
  opacity: 0.9;
  filter: drop-shadow(0 0 3px oklch(0.7 0.15 250 / 0.6));
}
.route-particle-animated-2 {
  fill: oklch(0.65 0.15 250);
  opacity: 0.7;
  filter: drop-shadow(0 0 2px oklch(0.65 0.15 250 / 0.4));
}
.route-particle-animated-delayed {
  fill: oklch(0.65 0.2 25);
  opacity: 0.9;
  filter: drop-shadow(0 0 3px oklch(0.65 0.2 25 / 0.6));
}

/* ---- Slide In Right Micro ---- */
.animate-slide-in-right-micro {
  animation: slideInRightMicro 0.25s ease-out;
}
@keyframes slideInRightMicro {
  from {
    opacity: 0;
    transform: translateX(12px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

/* ---- Ping Slow (slower pulse ring) ---- */
.animate-ping-slow {
  animation: ping-slow 3s cubic-bezier(0, 0, 0.2, 1) infinite;
}
@keyframes ping-slow {
  75%,
  100% {
    transform: scale(2.5);
    opacity: 0;
  }
}

/* ---- Card Accent Variants ── */
.card-accent-green {
  border-top: 3px solid oklch(0.65 0.2 145 / 0.7);
}
.card-accent-amber {
  border-top: 3px solid oklch(0.75 0.18 85 / 0.7);
}
.card-accent-red {
  border-top: 3px solid oklch(0.6 0.22 25 / 0.7);
}
.card-accent-blue {
  border-top: 3px solid oklch(0.6 0.15 250 / 0.7);
}

/* ---- Breached Flash Animation ── */
@keyframes breached-flash {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}
.animate-breached-flash {
  animation: breached-flash 1s ease-in-out infinite;
}

/* ---- Countdown Pulse ── */
@keyframes countdown-pulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.02); }
}
.animate-countdown-pulse {
  animation: countdown-pulse 2s ease-in-out infinite;
}

/* ---- Slide In Bottom Micro ── */
.animate-slide-in-bottom-micro {
  animation: slideInBottomMicro 0.2s ease-out;
}
@keyframes slideInBottomMicro {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ---- Skeleton Shimmer ── */
@keyframes skeleton-shimmer {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}
.animate-skeleton-shimmer {
  background: linear-gradient(90deg, transparent 25%, oklch(0.5 0.01 260 / 0.1) 50%, transparent 75%);
  background-size: 200% 100%;
  animation: skeleton-shimmer 2s linear infinite;
}

/* ---- Focus Ring Glow ── */
.focus-ring-glow:focus-visible {
  outline: 2px solid oklch(0.6 0.2 250);
  outline-offset: 2px;
  box-shadow: 0 0 0 4px oklch(0.6 0.2 250 / 0.2);
}

/* ---- Number Tabular ── */
.text-number {
  font-variant-numeric: tabular-nums;
}

/* ---- Stagger Children with Variable Delay ── */
.stagger-children > * {
  animation: staggerFadeIn 0.35s ease-out both;
}
/* Note: staggerFadeIn keyframe defined earlier (line 4354) — reused here */
.stagger-children > *:nth-child(1) { animation-delay: 0ms; }
.stagger-children > *:nth-child(2) { animation-delay: 40ms; }
.stagger-children > *:nth-child(3) { animation-delay: 80ms; }
.stagger-children > *:nth-child(4) { animation-delay: 120ms; }
.stagger-children > *:nth-child(5) { animation-delay: 160ms; }
.stagger-children > *:nth-child(6) { animation-delay: 200ms; }
.stagger-children > *:nth-child(7) { animation-delay: 240ms; }
.stagger-children > *:nth-child(8) { animation-delay: 280ms; }
.stagger-children > *:nth-child(9) { animation-delay: 320ms; }
.stagger-children > *:nth-child(10) { animation-delay: 360ms; }

/* ---- Nav Tap Feedback ── */
.nav-tap-feedback {
  transition: transform 0.1s ease, background-color 0.15s ease;
}
.nav-tap-feedback:active {
  transform: scale(0.92);
}

/* ---- Glass Panel Effect ── */
.glass-panel {
  background: oklch(1 0 0 / 0.7);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid oklch(0.5 0.02 260 / 0.15);
}
.dark .glass-panel {
  background: oklch(0.15 0.01 260 / 0.7);
  border-color: oklch(0.5 0.02 260 / 0.2);
}

/* ---- Gradient Text Warm ── */
.gradient-text-warm {
  background: linear-gradient(135deg, oklch(0.65 0.2 25), oklch(0.75 0.18 85));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* ---- Chat Panel Animations ── */
.chat-panel-enter { animation: chat-panel-slide-in 0.3s ease-out; }
@keyframes chat-panel-slide-in {
  from { opacity: 0; transform: translateY(20px) scale(0.95); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

/* Typing indicator */
.typing-dot { animation: typing-bounce 1.4s infinite ease-in-out both; }
.typing-dot:nth-child(1) { animation-delay: -0.32s; }
.typing-dot:nth-child(2) { animation-delay: -0.16s; }
@keyframes typing-bounce {
  0%, 80%, 100% { transform: scale(0); }
  40% { transform: scale(1); }
}

/* Chat button pulse */
.chat-btn-pulse { position: relative; }
.chat-btn-pulse::after {
  content: '';
  position: absolute;
  inset: -3px;
  border-radius: 9999px;
  background: rgba(16, 185, 129, 0.3);
  animation: pulse-ring 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}
@keyframes pulse-ring {
  0%, 100% { opacity: 0; transform: scale(0.8); }
  50% { opacity: 1; transform: scale(1.1); }
}

/* ═══════════════════════════════════════════════════════════════
   Micro-Interaction Animations & Styling Polish (Task 26)
   ═══════════════════════════════════════════════════════════════ */

/* ── Gradient Mesh Backgrounds ─────────────────────── */

.bg-mesh-gradient {
  background:
    radial-gradient(at 20% 30%, oklch(0.95 0.02 250 / 0.4) 0%, transparent 50%),
    radial-gradient(at 80% 70%, oklch(0.95 0.03 150 / 0.3) 0%, transparent 50%),
    radial-gradient(at 50% 50%, oklch(0.97 0.01 280 / 0.2) 0%, transparent 50%);
}
.dark .bg-mesh-gradient {
  background:
    radial-gradient(at 20% 30%, oklch(0.15 0.03 250 / 0.5) 0%, transparent 50%),
    radial-gradient(at 80% 70%, oklch(0.15 0.03 150 / 0.4) 0%, transparent 50%),
    radial-gradient(at 50% 50%, oklch(0.12 0.02 280 / 0.3) 0%, transparent 50%);
}

/* ── Card Hover Lift ──────────────────────────────── */

.card-lift {
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.card-lift:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 25px -5px oklch(0 0 0 / 0.1), 0 4px 10px -6px oklch(0 0 0 / 0.1);
}
.dark .card-lift:hover {
  box-shadow: 0 8px 25px -5px oklch(0 0 0 / 0.3), 0 4px 10px -6px oklch(0 0 0 / 0.2);
}

/* ── Shimmer Loading Skeleton ──────────────────────── */

.shimmer {
  position: relative;
  overflow: hidden;
}
.shimmer::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    transparent 0%,
    oklch(1 0 0 / 0.4) 50%,
    transparent 100%
  );
  animation: shimmer-slide-xform 1.5s infinite;
}
.dark .shimmer::after {
  background: linear-gradient(
    90deg,
    transparent 0%,
    oklch(1 0 0 / 0.1) 50%,
    transparent 100%
  );
}
@keyframes shimmer-slide-xform {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}

/* ── Number Counter Tabular Alignment ─────────────── */

.tabular-nums {
  font-variant-numeric: tabular-nums;
}

/* ── Status Dot Blinking ──────────────────────────── */

.status-dot-blink {
  animation: status-blink 1.5s ease-in-out infinite;
}
@keyframes status-blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.3; }
}

/* ── Hover Scale Micro-Interaction ────────────────── */

.hover-scale-sm {
  transition: transform 0.15s ease;
}
.hover-scale-sm:hover {
  transform: scale(1.02);
}
.hover-scale-sm:active {
  transform: scale(0.98);
}

/* ── Glow Effects ────────────────────────────────── */

.glow-success {
  box-shadow: 0 0 15px oklch(0.72 0.19 163 / 0.2);
}
.glow-warning {
  box-shadow: 0 0 15px oklch(0.79 0.18 86 / 0.2);
}
.glow-danger {
  box-shadow: 0 0 15px oklch(0.63 0.24 25 / 0.2);
}

/* ── Animated Gradient Border ─────────────────────── */

.gradient-border {
  position: relative;
  border: none;
}
.gradient-border::before {
  content: '';
  position: absolute;
  inset: 0;
  padding: 1px;
  border-radius: inherit;
  background: linear-gradient(135deg, oklch(0.7 0.15 250), oklch(0.7 0.15 150), oklch(0.7 0.15 200));
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  animation: gradient-rotate-bg 4s linear infinite;
}
@keyframes gradient-rotate-bg {
  from { background: linear-gradient(0deg, oklch(0.7 0.15 250), oklch(0.7 0.15 150), oklch(0.7 0.15 200)); }
  to { background: linear-gradient(360deg, oklch(0.7 0.15 250), oklch(0.7 0.15 150), oklch(0.7 0.15 200)); }
}

/* ── Tooltip Pop Animation ────────────────────────── */

.tooltip-pop {
  animation: tooltip-pop-in 0.2s ease-out;
}
@keyframes tooltip-pop-in {
  from { opacity: 0; transform: scale(0.9) translateY(4px); }
  to { opacity: 1; transform: scale(1) translateY(0); }
}

/* ── Animated Progress Bar Stripes ────────────────── */

.progress-striped {
  background-image: linear-gradient(
    45deg,
    oklch(1 0 0 / 0.15) 25%,
    transparent 25%,
    transparent 50%,
    oklch(1 0 0 / 0.15) 50%,
    oklch(1 0 0 / 0.15) 75%,
    transparent 75%,
    transparent
  );
  background-size: 1rem 1rem;
  animation: progress-stripe-move 1s linear infinite;
}
.dark .progress-striped {
  background-image: linear-gradient(
    45deg,
    oklch(1 0 0 / 0.08) 25%,
    transparent 25%,
    transparent 50%,
    oklch(1 0 0 / 0.08) 50%,
    oklch(1 0 0 / 0.08) 75%,
    transparent 75%,
    transparent
  );
}
@keyframes progress-stripe-move {
  from { background-position: 1rem 0; }
  to { background-position: 0 0; }
}

/* ── Staggered Fade-In for Children ───────────────── */

.stagger-fade > * {
  opacity: 0;
  animation: stagger-fade-in 0.4s ease-out forwards;
}
.stagger-fade > *:nth-child(1) { animation-delay: 0ms; }
.stagger-fade > *:nth-child(2) { animation-delay: 50ms; }
.stagger-fade > *:nth-child(3) { animation-delay: 100ms; }
.stagger-fade > *:nth-child(4) { animation-delay: 150ms; }
.stagger-fade > *:nth-child(5) { animation-delay: 200ms; }
.stagger-fade > *:nth-child(6) { animation-delay: 250ms; }
.stagger-fade > *:nth-child(7) { animation-delay: 300ms; }
.stagger-fade > *:nth-child(8) { animation-delay: 350ms; }
.stagger-fade > *:nth-child(9) { animation-delay: 400ms; }
.stagger-fade > *:nth-child(10) { animation-delay: 450ms; }
@keyframes stagger-fade-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ── Smooth Focus Ring ────────────────────────────── */

.focus-ring {
  transition: box-shadow 0.2s ease;
}
.focus-ring:focus-visible {
  box-shadow: 0 0 0 3px oklch(0.95 0.02 250 / 0.5), 0 0 0 1px oklch(0.5 0.15 250);
  outline: none;
}
.dark .focus-ring:focus-visible {
  box-shadow: 0 0 0 3px oklch(0.2 0.05 250 / 0.5), 0 0 0 1px oklch(0.6 0.15 250);
}

/* ── Text Glow for Important Numbers ──────────────── */

.text-glow-emerald {
  text-shadow: 0 0 10px oklch(0.7 0.17 163 / 0.4);
}
.text-glow-amber {
  text-shadow: 0 0 10px oklch(0.8 0.17 86 / 0.4);
}
.text-glow-rose {
  text-shadow: 0 0 10px oklch(0.65 0.22 15 / 0.4);
}

/* ═══════════════════════════════════════════════════════════════
   Round 22: Dark Mode Transitions, Barcode Scanner, Real-time
   ═══════════════════════════════════════════════════════════════ */

/* ── Scanner Viewfinder Animation ──────────────────── */
.scanner-viewfinder {
  position: relative;
  overflow: hidden;
}
.scanner-viewfinder::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    oklch(0.72 0.19 163) 20%,
    oklch(0.72 0.19 163 / 0.8) 50%,
    oklch(0.72 0.19 163) 80%,
    transparent 100%
  );
  box-shadow: 0 0 8px oklch(0.72 0.19 163 / 0.5), 0 0 20px oklch(0.72 0.19 163 / 0.3);
  animation: scanner-line 2.5s ease-in-out infinite;
  z-index: 10;
}
@keyframes scanner-line {
  0% { top: 0; }
  50% { top: calc(100% - 2px); }
  100% { top: 0; }
}

/* ── Scanner Corner Brackets ──────────────────────── */
.scanner-corners {
  position: relative;
}
.scanner-corners::before,
.scanner-corners::after {
  content: '';
  position: absolute;
  width: 24px;
  height: 24px;
  border-color: oklch(0.72 0.19 163);
  border-style: solid;
  border-width: 0;
  z-index: 10;
}
.scanner-corners::before {
  top: 0; left: 0;
  border-top-width: 3px; border-left-width: 3px;
  border-top-left-radius: 6px;
}
.scanner-corners::after {
  bottom: 0; right: 0;
  border-bottom-width: 3px; border-right-width: 3px;
  border-bottom-right-radius: 6px;
}
.scanner-corner-tr,
.scanner-corner-bl {
  position: absolute;
  width: 24px;
  height: 24px;
  border-color: oklch(0.72 0.19 163);
  border-style: solid;
  border-width: 0;
  z-index: 10;
}
.scanner-corner-tr {
  top: 0; right: 0;
  border-top-width: 3px; border-right-width: 3px;
  border-top-right-radius: 6px;
}
.scanner-corner-bl {
  bottom: 0; left: 0;
  border-bottom-width: 3px; border-left-width: 3px;
  border-bottom-left-radius: 6px;
}

/* ── Scanner Pulse Ring ───────────────────────────── */
.scanner-pulse {
  animation: scanner-pulse-ring 2s ease-out infinite;
}
@keyframes scanner-pulse-ring {
  0% { box-shadow: 0 0 0 0 oklch(0.72 0.19 163 / 0.4); }
  70% { box-shadow: 0 0 0 12px oklch(0.72 0.19 163 / 0); }
  100% { box-shadow: 0 0 0 0 oklch(0.72 0.19 163 / 0); }
}

/* ── Real-time Data Flash ─────────────────────────── */
.data-flash {
  animation: data-value-flash 0.6s ease-out;
}
@keyframes data-value-flash {
  0% { background-color: oklch(0.72 0.19 163 / 0.15); }
  100% { background-color: transparent; }
}
.dark .data-flash {
  animation-name: data-value-flash-dark;
}
@keyframes data-value-flash-dark {
  0% { background-color: oklch(0.72 0.19 163 / 0.1); }
  100% { background-color: transparent; }
}

/* ── Live Dot Indicator ───────────────────────────── */
.live-dot {
  position: relative;
}
.live-dot::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 6px;
  height: 6px;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  background-color: oklch(0.72 0.19 163);
  animation: live-dot-ping 1.5s cubic-bezier(0, 0, 0.2, 1) infinite;
}
@keyframes live-dot-ping {
  0% { opacity: 1; transform: translate(-50%, -50%) scale(1); }
  75%, 100% { opacity: 0; transform: translate(-50%, -50%) scale(2.5); }
}

/* ── KPI Card Pulse on Update ──────────────────────── */
.kpi-update-pulse {
  animation: kpi-pulse 0.8s ease-out;
}
@keyframes kpi-pulse {
  0% { transform: scale(1); box-shadow: none; }
  30% { transform: scale(1.02); box-shadow: 0 0 15px oklch(0.588 0.243 264 / 0.2); }
  100% { transform: scale(1); box-shadow: none; }
}

/* ── Barcode Mock Lines ───────────────────────────── */
.barcode-line {
  display: inline-block;
  width: var(--bar-width, 2px);
  height: var(--bar-height, 48px);
  background: currentColor;
  margin-right: var(--bar-gap, 1px);
  border-radius: 1px;
}

/* ── Slide-in Panel ───────────────────────────────── */
.panel-slide-in-right {
  animation: panel-slide-right 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes panel-slide-right {
  from { opacity: 0; transform: translateX(20px); }
  to { opacity: 1; transform: translateX(0); }
}

.panel-slide-in-up {
  animation: panel-slide-up 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes panel-slide-up {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ── Scan Success Checkmark ────────────────────────── */
.scan-success {
  animation: scan-check 0.5s ease-out;
}
@keyframes scan-check {
  0% { transform: scale(0); opacity: 0; }
  50% { transform: scale(1.2); }
  100% { transform: scale(1); opacity: 1; }
}

/* ── Inventory Item Highlight ───────────────────────── */
.inventory-highlight {
  animation: inv-highlight 1.5s ease-out;
}
@keyframes inv-highlight {
  0% { background-color: oklch(0.72 0.19 163 / 0.2); border-color: oklch(0.72 0.19 163); }
  100% { background-color: transparent; border-color: inherit; }
}

/* ── Tooltip Micro-pop ────────────────────────────── */
.micro-pop {
  animation: micro-pop-in 0.15s ease-out;
}
@keyframes micro-pop-in {
  from { opacity: 0; transform: scale(0.95); }
  to { opacity: 1; transform: scale(1); }
}

/* ── Badge Count Bounce ───────────────────────────── */
.badge-bounce {
  animation: badge-bounce-in 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}
@keyframes badge-bounce-in {
  0% { transform: scale(0); }
  100% { transform: scale(1); }
}


/* ── Glass Morphism Card ─────────────────────────── */
.card-glass {
  background: oklch(1 0 0 / 0.6);
  backdrop-filter: blur(16px) saturate(1.2);
  -webkit-backdrop-filter: blur(16px) saturate(1.2);
  border: 1px solid oklch(0.5 0.02 260 / 0.12);
}
.dark .card-glass {
  background: oklch(0.18 0.015 250 / 0.6);
  border-color: oklch(0.5 0.02 260 / 0.18);
}
.card-glass-hover {
  transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;
}
.card-glass-hover:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 40px -8px oklch(0 0 0 / 0.08), 0 4px 16px -4px oklch(0 0 0 / 0.06);
  border-color: oklch(0.588 0.243 264 / 0.25);
}
.dark .card-glass-hover:hover {
  box-shadow: 0 12px 40px -8px oklch(0 0 0 / 0.3), 0 4px 16px -4px oklch(0 0 0 / 0.2);
  border-color: oklch(0.588 0.243 264 / 0.35);
}

/* ── Sidebar Active Glow ──────────────────────────── */
.sidebar-active-glow {
  position: relative;
}
.sidebar-active-glow::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 3px;
  height: 60%;
  border-radius: 0 3px 3px 0;
  background: oklch(0.588 0.243 264);
  box-shadow: 0 0 8px oklch(0.588 0.243 264 / 0.4);
  transition: height 0.2s ease, opacity 0.2s ease;
}

/* ── Gradient Progress Bar ───────────────────────── */
.progress-gradient {
  background: linear-gradient(90deg, oklch(0.588 0.243 264), oklch(0.667 0.194 149));
  border-radius: 9999px;
}
.progress-gradient-amber {
  background: linear-gradient(90deg, oklch(0.815 0.184 86), oklch(0.696 0.222 41.116));
  border-radius: 9999px;
}
.progress-gradient-red {
  background: linear-gradient(90deg, oklch(0.637 0.237 22.5), oklch(0.65 0.22 15));
  border-radius: 9999px;
}

/* ── Skeleton Card Shimmer ────────────────────────── */
.skeleton-card {
  background: linear-gradient(110deg, oklch(0.96 0.005 260) 30%, oklch(0.93 0.01 260) 50%, oklch(0.96 0.005 260) 70%);
  background-size: 200% 100%;
  animation: skeleton-card-shimmer 2s ease-in-out infinite;
  border-radius: 0.75rem;
}
.dark .skeleton-card {
  background: linear-gradient(110deg, oklch(0.18 0.01 260) 30%, oklch(0.22 0.015 260) 50%, oklch(0.18 0.01 260) 70%);
  background-size: 200% 100%;
}
@keyframes skeleton-card-shimmer {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

/* ── Ripple Effect ───────────────────────────────── */
.ripple-effect {
  position: relative;
  overflow: hidden;
}
.ripple-effect::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at var(--ripple-x, 50%) var(--ripple-y, 50%), oklch(0.588 0.243 264 / 0.15) 0%, transparent 60%);
  opacity: 0;
  transition: opacity 0.4s ease;
  pointer-events: none;
}
.ripple-effect:active::after {
  opacity: 1;
  transition: opacity 0s;
}

/* ============================================================================
 * Round 24 - New CSS Micro-interactions & Utility Classes
 * ============================================================================ */

/* ── Animated gradient border on hover ── */
.animated-border-glow {
  position: relative;
  overflow: hidden;
}
.animated-border-glow::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1.5px;
  background: conic-gradient(
    from 0deg,
    theme('colors.primary') 0%,
    theme('colors.emerald.400') 25%,
    theme('colors.amber.400') 50%,
    theme('colors.primary') 100%
  );
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  opacity: 0;
  transition: opacity 0.4s ease;
  pointer-events: none;
}
.animated-border-glow:hover::before {
  opacity: 1;
  animation: spin-slow 3s linear infinite;
}
@keyframes spin-slow {
  to { transform: rotate(360deg); }
}

/* ── Pulse ring for live indicators ── */
.live-pulse-ring {
  position: relative;
}
.live-pulse-ring::after {
  content: '';
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  border: 2px solid theme('colors.emerald.400');
  opacity: 0;
  animation: live-pulse-ring-anim 2s ease-out infinite;
}
@keyframes live-pulse-ring-anim {
  0% { transform: scale(0.8); opacity: 0.8; }
  100% { transform: scale(1.6); opacity: 0; }
}

/* ── Subtle breathing glow for important cards ── */
.card-breathe {
  animation: card-breathe-anim 4s ease-in-out infinite;
}
@keyframes card-breathe-anim {
  0%, 100% { box-shadow: 0 1px 3px 0 rgb(0 0 0 / 0.05); }
  50% { box-shadow: 0 4px 12px 0 rgb(0 0 0 / 0.08), 0 0 0 1px rgb(37 99 235 / 0.06); }
}
.dark .card-breathe {
  animation-name: card-breathe-dark-anim;
}
@keyframes card-breathe-dark-anim {
  0%, 100% { box-shadow: 0 1px 3px 0 rgb(0 0 0 / 0.2); }
  50% { box-shadow: 0 4px 12px 0 rgb(0 0 0 / 0.3), 0 0 0 1px rgb(37 99 235 / 0.1); }
}

/* ── Smooth number counter animation ── */
.count-up {
  animation: count-up-flash 0.3s ease-out;
}
@keyframes count-up-flash {
  0% { transform: translateY(4px); opacity: 0; }
  100% { transform: translateY(0); opacity: 1; }
}

/* ── Skeleton loading variants ── */
.skeleton-wave {
  background: linear-gradient(
    90deg,
    theme('colors.muted') 0%,
    rgb(100 116 139 / 0.5) 40%,
    theme('colors.muted') 80%
  );
  background-size: 200% 100%;
  animation: skeleton-wave-anim 1.5s ease-in-out infinite;
}
@keyframes skeleton-wave-anim {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

/* ── Table row slide in animation ── */
.table-row-slide-in {
  animation: row-slide-in 0.35s ease-out both;
}
@keyframes row-slide-in {
  from {
    opacity: 0;
    transform: translateX(-8px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

/* ── Button press micro-interaction ── */
.btn-press {
  transition: transform 0.1s ease, box-shadow 0.15s ease;
}
.btn-press:active {
  transform: scale(0.96) translateY(1px);
  box-shadow: inset 0 2px 4px rgb(0 0 0 / 0.06);
}
.dark .btn-press:active {
  box-shadow: inset 0 2px 4px rgb(0 0 0 / 0.2);
}

/* ── Floating action button entrance ── */
.fab-enter {
  animation: fab-enter-anim 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) both;
}
@keyframes fab-enter-anim {
  from {
    opacity: 0;
    transform: scale(0.5) translateY(20px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

/* ── Notification badge bounce ── */
.badge-bounce {
  animation: badge-pop-in 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
}
@keyframes badge-pop-in {
  0% { transform: scale(0); }
  60% { transform: scale(1.2); }
  100% { transform: scale(1); }
}

/* ── Shimmer text effect for loading states ── */
.text-shimmer {
  background: linear-gradient(
    110deg,
    theme('colors.foreground') 30%,
    theme('colors.muted.foreground') 50%,
    theme('colors.foreground') 70%
  );
  background-size: 200% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: text-shimmer-anim 2s ease-in-out infinite;
}
@keyframes text-shimmer-anim {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

/* ── Smooth scrollbar styling ── */
.custom-scrollbar-thin::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
.custom-scrollbar-thin::-webkit-scrollbar-track {
  background: transparent;
}
.custom-scrollbar-thin::-webkit-scrollbar-thumb {
  background: rgb(100 116 139 / 0.2);
  border-radius: 3px;
}
.custom-scrollbar-thin::-webkit-scrollbar-thumb:hover {
  background: rgb(100 116 139 / 0.4);
}

/* ── Card hover depth effect ── */
.card-depth {
  transition: box-shadow 0.2s ease, transform 0.2s ease;
}
.card-depth:hover {
  box-shadow:
    0 4px 6px -1px rgb(0 0 0 / 0.07),
    0 2px 4px -2px rgb(0 0 0 / 0.05);
}
.dark .card-depth:hover {
  box-shadow:
    0 4px 6px -1px rgb(0 0 0 / 0.25),
    0 2px 4px -2px rgb(0 0 0 / 0.15);
}

/* ── Focus visible with offset ── */
.focus-ring-offset {
  outline: none;
}
.focus-ring-offset:focus-visible {
  outline: 2px solid theme('colors.primary');
  outline-offset: 2px;
  border-radius: 6px;
}

/* ── Gradient text for headings ── */
.heading-gradient {
  background: linear-gradient(135deg, theme('colors.primary') 0%, theme('colors.emerald.500') 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

/* ── Dot pattern background ── */
.bg-dots {
  background-image: radial-gradient(circle, rgb(100 116 139 / 0.15) 1px, transparent 1px);
  background-size: 16px 16px;
}

/* ── Tooltip slide-in ── */
.tooltip-slide-in {
  animation: tooltip-slide 0.2s ease-out both;
}
@keyframes tooltip-slide {
  from {
    opacity: 0;
    transform: translateY(4px) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* ── Status indicator dot blink ── */
.status-blink {
  animation: status-blink-anim 1.5s ease-in-out infinite;
}
@keyframes status-blink-anim {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}


/* ── Round 12: New animation utilities ── */

/* Subtle breathing glow for active status indicators */
@keyframes breathe-glow {
  0%, 100% { box-shadow: 0 0 0 0 oklch(0.7 0.15 200 / 0); }
  50% { box-shadow: 0 0 12px 2px oklch(0.7 0.15 200 / 0.15); }
}
.breathe-glow {
  animation: breathe-glow 3s ease-in-out infinite;
}

/* Smooth number tabular alignment for data tables */
.tabular-nums {
  font-variant-numeric: tabular-nums;
}

/* Active state ripple effect */
@keyframes ripple {
  0% { transform: scale(0); opacity: 0.5; }
  100% { transform: scale(4); opacity: 0; }
}
.btn-ripple {
  position: relative;
  overflow: hidden;
}
.btn-ripple::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: oklch(1 0 0 / 0.2);
  animation: ripple 0.6s ease-out forwards;
  pointer-events: none;
}

/* Skeleton loading shimmer for cards */
@keyframes skeleton-shimmer-gradient {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}
.skeleton-shimmer-new {
  background: linear-gradient(90deg, oklch(0.95 0 0 / 0) 25%, oklch(0.95 0 0 / 0.3) 50%, oklch(0.95 0 0 / 0) 75%);
  background-size: 200% 100%;
  animation: skeleton-shimmer-gradient 2s ease-in-out infinite;
}
:is(.dark) .skeleton-shimmer-new {
  background: linear-gradient(90deg, oklch(0.25 0 0 / 0) 25%, oklch(0.25 0 0 / 0.15) 50%, oklch(0.25 0 0 / 0) 75%);
  background-size: 200% 100%;
}

/* Smooth container entrance */
@keyframes container-reveal {
  from { opacity: 0; transform: translateY(8px) scale(0.99); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
.container-reveal {
  animation: container-reveal 0.4s cubic-bezier(0.22, 1, 0.36, 1) both;
}

/* Floating action button entrance */
@keyframes fab-enter {
  0% { transform: scale(0) translateY(20px); opacity: 0; }
  60% { transform: scale(1.1) translateY(-2px); opacity: 1; }
  100% { transform: scale(1) translateY(0); opacity: 1; }
}
.fab-enter {
  animation: fab-enter 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) both;
}

/* Status indicator with pulse ring */
@keyframes status-ping {
  0% { transform: scale(1); opacity: 0.8; }
  75%, 100% { transform: scale(2); opacity: 0; }
}
.status-ping {
  position: relative;
}
.status-ping::before {
  content: '';
  position: absolute;
  inset: -2px;
  border-radius: 50%;
  background: inherit;
  animation: status-ping 1.5s cubic-bezier(0, 0, 0.2, 1) infinite;
}

/* Glass morphism card */
.glass-card {
  background: oklch(1 0 0 / 0.7);
  backdrop-filter: blur(12px) saturate(1.2);
  border: 1px solid oklch(0.85 0 0 / 0.3);
}
:is(.dark) .glass-card {
  background: oklch(0.2 0 0 / 0.7);
  border: 1px solid oklch(0.35 0 0 / 0.2);
}

/* Smooth gradient border on hover */
.hover-gradient-border {
  position: relative;
  transition: transform 0.2s ease;
}
.hover-gradient-border::before {
  content: '';
  position: absolute;
  inset: -1px;
  border-radius: inherit;
  background: conic-gradient(from var(--border-angle, 0deg), oklch(0.65 0.2 250), oklch(0.7 0.15 160), oklch(0.65 0.2 250));
  z-index: -1;
  opacity: 0;
  transition: opacity 0.3s ease;
}
.hover-gradient-border:hover::before {
  opacity: 1;
  animation: rotate-gradient 3s linear infinite;
}
@property --border-angle {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}
@keyframes rotate-gradient {
  from { --border-angle: 0deg; }
  to { --border-angle: 360deg; }
}


/* ── Round 27: Enhanced interaction & visual polish ── */

/* Smooth card entrance stagger for grid children */
@keyframes stagger-grid-in {
  from { opacity: 0; transform: translateY(12px) scale(0.97); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
.stagger-grid > * {
  animation: stagger-grid-in 0.35s cubic-bezier(0.22, 1, 0.36, 1) both;
}
.stagger-grid > *:nth-child(1) { animation-delay: 0ms; }
.stagger-grid > *:nth-child(2) { animation-delay: 40ms; }
.stagger-grid > *:nth-child(3) { animation-delay: 80ms; }
.stagger-grid > *:nth-child(4) { animation-delay: 120ms; }
.stagger-grid > *:nth-child(5) { animation-delay: 160ms; }
.stagger-grid > *:nth-child(6) { animation-delay: 200ms; }
.stagger-grid > *:nth-child(7) { animation-delay: 240ms; }
.stagger-grid > *:nth-child(8) { animation-delay: 280ms; }
.stagger-grid > *:nth-child(n+9) { animation-delay: 320ms; }

/* Tooltip with smooth fade + slide */
@keyframes tooltip-enter {
  from { opacity: 0; transform: translateY(4px) scale(0.95); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
.tooltip-smooth {
  animation: tooltip-enter 0.2s cubic-bezier(0.22, 1, 0.36, 1) both;
}

/* Active nav item with animated left indicator */
@keyframes nav-indicator {
  from { transform: scaleY(0); }
  to { transform: scaleY(1); }
}
.nav-item-active::before {
  content: "";
  position: absolute;
  left: 0;
  top: 4px;
  bottom: 4px;
  width: 3px;
  border-radius: 0 3px 3px 0;
  background: oklch(0.6 0.2 250);
  animation: nav-indicator 0.25s cubic-bezier(0.22, 1, 0.36, 1) both;
}
:is(.dark) .nav-item-active::before {
  background: oklch(0.65 0.18 250);
}

/* Gradient text for headings */
.gradient-heading {
  background: linear-gradient(135deg, oklch(0.55 0.2 250), oklch(0.6 0.15 180));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Subtle hover glow for interactive cards */
@keyframes card-hover-glow-subtle {
  from { box-shadow: 0 0 0 0 oklch(0.6 0.15 250 / 0); }
  to { box-shadow: 0 4px 20px -4px oklch(0.6 0.15 250 / 0.08); }
}
.card-hover-glow-subtle {
  transition: box-shadow 0.3s ease;
}
.card-hover-glow-subtle:hover {
  animation: card-hover-glow-subtle 0.3s ease both;
}

/* Badge with count animation */
@keyframes badge-pop {
  0% { transform: scale(0.5); }
  60% { transform: scale(1.2); }
  100% { transform: scale(1); }
}
.badge-pop {
  animation: badge-pop 0.3s cubic-bezier(0.34, 1.56, 0.64, 1) both;
}

/* Smooth scrollbar for horizontal overflow */
.scrollbar-horizontal {
  overflow-x: auto;
  scrollbar-width: thin;
  scrollbar-color: oklch(0.75 0 0 / 0.3) transparent;
}
.scrollbar-horizontal::-webkit-scrollbar {
  height: 6px;
}
.scrollbar-horizontal::-webkit-scrollbar-track {
  background: transparent;
}
.scrollbar-horizontal::-webkit-scrollbar-thumb {
  background: oklch(0.75 0 0 / 0.3);
  border-radius: 3px;
}
:is(.dark) .scrollbar-horizontal::-webkit-scrollbar-thumb {
  background: oklch(0.4 0 0 / 0.3);
}

/* Focus ring for inputs with primary color */
.focus-ring-primary:focus {
  outline: none;
  box-shadow: 0 0 0 2px oklch(1 0 0 / 0.8), 0 0 0 4px oklch(0.55 0.2 250 / 0.3);
}
:is(.dark) .focus-ring-primary:focus {
  box-shadow: 0 0 0 2px oklch(0.15 0 0 / 0.8), 0 0 0 4px oklch(0.55 0.2 250 / 0.4);
}

/* ──────────────────────────────────────────────────────────────────────── */
/*  Round 28 — Inventory Detail Drawer + Micro-interactions                */
/* ──────────────────────────────────────────────────────────────────────── */

/* Drawer slide-in with subtle bounce */
@keyframes drawer-slide-in {
  0% {
    opacity: 0;
    transform: translateX(100%) scale(0.98);
  }
  60% {
    opacity: 1;
    transform: translateX(-8px) scale(1);
  }
  100% {
    opacity: 1;
    transform: translateX(0) scale(1);
  }
}
.drawer-slide-in {
  animation: drawer-slide-in 0.32s cubic-bezier(0.22, 1, 0.36, 1);
}

/* Stat card hover lift with subtle glow */
.stat-card-hover {
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}
.stat-card-hover:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 12px -2px oklch(0.4 0 0 / 0.1), 0 2px 4px -1px oklch(0.4 0 0 / 0.06);
}
:is(.dark) .stat-card-hover:hover {
  box-shadow: 0 4px 12px -2px oklch(0 0 0 / 0.3), 0 2px 4px -1px oklch(0 0 0 / 0.2);
}

/* Movement row entrance — left slide-in for history items */
@keyframes movement-row-in {
  from {
    opacity: 0;
    transform: translateX(-6px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}
.movement-row-in {
  animation: movement-row-in 0.25s ease-out both;
}

/* Health score badge — pulsing border for critical status */
@keyframes critical-pulse-border {
  0%, 100% {
    box-shadow: 0 0 0 0 oklch(0.58 0.24 27 / 0.4);
  }
  50% {
    box-shadow: 0 0 0 4px oklch(0.58 0.24 27 / 0);
  }
}
.critical-pulse-border {
  animation: critical-pulse-border 1.6s ease-out infinite;
}

/* Reorder button urgent glow */
@keyframes reorder-urgent-glow {
  0%, 100% {
    box-shadow: 0 0 0 0 oklch(0.58 0.24 27 / 0.5), 0 1px 2px oklch(0 0 0 / 0.1);
  }
  50% {
    box-shadow: 0 0 0 6px oklch(0.58 0.24 27 / 0), 0 1px 2px oklch(0 0 0 / 0.1);
  }
}
.reorder-urgent {
  animation: reorder-urgent-glow 1.8s ease-out infinite;
}

/* Drawer header gradient shimmer — subtle moving highlight */
@keyframes drawer-header-shimmer {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}
.drawer-header-shimmer {
  background-image: linear-gradient(
    90deg,
    transparent 0%,
    oklch(0.6 0.2 250 / 0.04) 50%,
    transparent 100%
  );
  background-size: 200% 100%;
  animation: drawer-header-shimmer 4s linear infinite;
}

/* Stock level progress fill animation */
@keyframes stock-fill-grow {
  from { width: 0%; }
}
.stock-fill-animate > div {
  animation: stock-fill-grow 0.8s cubic-bezier(0.22, 1, 0.36, 1);
}

/* Number ticker for stock values */
@keyframes number-ticker-up {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.number-ticker {
  animation: number-ticker-up 0.3s ease-out;
}

/* Subtle border glow on focus for inventory cards */
.inventory-card-focus:focus-within {
  border-color: oklch(0.55 0.2 250 / 0.4);
  box-shadow: 0 0 0 2px oklch(0.55 0.2 250 / 0.15);
}

/* Tabular number alignment for all .text-number instances (reaffirmed) */
.text-number {
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum";
}

/* Hover ripple effect on table rows */
@keyframes row-hover-ripple {
  0% {
    background-position: -100% 0;
  }
  100% {
    background-position: 200% 0;
  }
}
.row-hover-ripple:hover {
  background-image: linear-gradient(
    90deg,
    transparent 0%,
    oklch(0.55 0.2 250 / 0.04) 50%,
    transparent 100%
  );
  background-size: 200% 100%;
  animation: row-hover-ripple 1.2s linear infinite;
}

/* Smooth color transition for status badges */
.status-badge-smooth {
  transition: background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease;
}

/* ──────────────────────────────────────────────────────────────────────── */
/*  Round 29 — Equipment Detail Drawer + Polish                           */
/* ──────────────────────────────────────────────────────────────────────── */

/* Battery level bar — smooth width transition when value changes */
.battery-bar-fill {
  transition: width 0.6s cubic-bezier(0.22, 1, 0.36, 1), background-color 0.3s ease;
}

/* Battery charging pulse — for charging status icon */
@keyframes battery-charging-pulse {
  0%, 100% {
    opacity: 1;
    filter: drop-shadow(0 0 0 oklch(0.62 0.18 250 / 0));
  }
  50% {
    opacity: 0.85;
    filter: drop-shadow(0 0 4px oklch(0.62 0.18 250 / 0.6));
  }
}
.battery-charging-pulse {
  animation: battery-charging-pulse 1.6s ease-in-out infinite;
}

/* Maintenance overdue badge — urgent pulse */
@keyframes maintenance-overdue-pulse {
  0%, 100% {
    box-shadow: 0 0 0 0 oklch(0.58 0.24 27 / 0.5);
  }
  50% {
    box-shadow: 0 0 0 4px oklch(0.58 0.24 27 / 0);
  }
}
.maintenance-overdue-pulse {
  animation: maintenance-overdue-pulse 1.4s ease-out infinite;
}

/* Equipment card hover lift with primary tint */
.equipment-card-hover {
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}
.equipment-card-hover:hover {
  transform: translateY(-2px);
  border-color: oklch(0.55 0.2 250 / 0.3);
  box-shadow: 0 4px 16px -4px oklch(0.4 0 0 / 0.1), 0 2px 4px -1px oklch(0.4 0 0 / 0.06);
}

/* Dock card drag handle visual cue */
.dock-drag-handle {
  cursor: grab;
  transition: background-color 0.15s ease;
}
.dock-drag-handle:hover {
  background-color: oklch(0.55 0.2 250 / 0.06);
}
.dock-drag-handle:active {
  cursor: grabbing;
}

/* Dock status colors — border-left accent */
.dock-status-available {
  border-left: 3px solid oklch(0.62 0.18 145 / 0.5);
}
.dock-status-occupied {
  border-left: 3px solid oklch(0.62 0.18 250 / 0.5);
}
.dock-status-maintenance {
  border-left: 3px solid oklch(0.58 0.24 27 / 0.5);
}

/* Progress bar with animated stripe for active progress */
@keyframes progress-active-stripe {
  0% { background-position: 0 0; }
  100% { background-position: 40px 0; }
}
.progress-active-stripe > div {
  background-image: linear-gradient(
    45deg,
    oklch(1 0 0 / 0.15) 25%,
    transparent 25%,
    transparent 50%,
    oklch(1 0 0 / 0.15) 50%,
    oklch(1 0 0 / 0.15) 75%,
    transparent 75%,
    transparent
  );
  background-size: 40px 40px;
  animation: progress-active-stripe 1s linear infinite;
}

/* Stat number counter entrance */
@keyframes stat-counter-rise {
  from {
    opacity: 0;
    transform: translateY(6px) scale(0.95);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}
.stat-counter-rise {
  animation: stat-counter-rise 0.4s cubic-bezier(0.22, 1, 0.36, 1) both;
}

/* Hover ring for clickable table rows */
.clickable-row {
  cursor: pointer;
  transition: background-color 0.15s ease;
}
.clickable-row:hover {
  background-color: oklch(0.55 0.2 250 / 0.04);
}

/* Focus visible outline for keyboard nav on cards */
.card-focus-visible:focus-visible {
  outline: 2px solid oklch(0.55 0.2 250 / 0.6);
  outline-offset: 2px;
}

/* Equipment type icon tint variants */
.icon-tint-blue { color: oklch(0.55 0.2 250); }
.icon-tint-emerald { color: oklch(0.62 0.18 145); }
.icon-tint-amber { color: oklch(0.7 0.18 75); }
.icon-tint-red { color: oklch(0.58 0.24 27); }
.icon-tint-purple { color: oklch(0.55 0.2 300); }
.icon-tint-cyan { color: oklch(0.6 0.18 200); }

/* ──────────────────────────────────────────────────────────────────────── */
/*  Round 30 — Shipment Detail Drawer + Timeline polish                  */
/* ──────────────────────────────────────────────────────────────────────── */

/* Timeline dot pulse — for in-progress / current event */
@keyframes timeline-dot-pulse {
  0%, 100% {
    box-shadow: 0 0 0 0 oklch(0.62 0.18 250 / 0.5);
  }
  50% {
    box-shadow: 0 0 0 4px oklch(0.62 0.18 250 / 0);
  }
}
.timeline-dot-active {
  animation: timeline-dot-pulse 1.6s ease-out infinite;
}

/* Timeline vertical line — subtle gradient */
.timeline-line {
  background: linear-gradient(
    to bottom,
    oklch(0.62 0.18 145 / 0.4) 0%,
    oklch(0.62 0.18 250 / 0.3) 50%,
    oklch(0.4 0 0 / 0.1) 100%
  );
}

/* Status banner pulse for delayed shipments */
@keyframes delayed-banner-pulse {
  0%, 100% {
    background-color: oklch(0.58 0.24 27 / 0.08);
  }
  50% {
    background-color: oklch(0.58 0.24 27 / 0.15);
  }
}
.delayed-banner-pulse {
  animation: delayed-banner-pulse 2s ease-in-out infinite;
}

/* Progress bar with shimmer overlay for in-transit shipments */
@keyframes transit-progress-shimmer {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}
.transit-progress-shimmer {
  position: relative;
  overflow: hidden;
}
.transit-progress-shimmer::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    transparent 0%,
    oklch(1 0 0 / 0.3) 50%,
    transparent 100%
  );
  animation: transit-progress-shimmer 2s linear infinite;
}

/* Carrier logo / badge tint variants */
.carrier-tint-bluedart { color: oklch(0.55 0.22 250); }
.carrier-tint-delhivery { color: oklch(0.55 0.22 145); }
.carrier-tint-dtdc { color: oklch(0.55 0.22 25); }
.carrier-tint-ecom { color: oklch(0.55 0.22 300); }
.carrier-tint-xpressbees { color: oklch(0.55 0.22 200); }
.carrier-tint-shadowfax { color: oklch(0.55 0.22 350); }

/* Map pin bounce for origin/destination markers */
@keyframes map-pin-bounce {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-3px); }
}
.map-pin-bounce {
  animation: map-pin-bounce 1.4s ease-in-out infinite;
}

/* Distance bar — animated fill from left */
@keyframes distance-fill {
  from { width: 0%; }
}
.distance-fill-animate {
  animation: distance-fill 1s cubic-bezier(0.22, 1, 0.36, 1) both;
}

/* Hover ripple for clickable shipment rows */
.shipment-row-hover {
  transition: background-color 0.15s ease, transform 0.15s ease;
}
.shipment-row-hover:hover {
  background-color: oklch(0.55 0.2 250 / 0.04);
}

/* Driver / vehicle card subtle accent */
.driver-card-accent {
  border-left: 3px solid oklch(0.55 0.2 250 / 0.4);
}

/* COD amount highlight */
.cod-amount-highlight {
  background: linear-gradient(135deg, oklch(0.7 0.18 75 / 0.1), oklch(0.7 0.18 45 / 0.1));
  border-color: oklch(0.7 0.18 75 / 0.3);
}

/* ===========================================================================
   ROUND 32 — Warehouse Detail Drawer + Pull-to-Refresh Micro-interactions
   =========================================================================== */

/* Warehouse drawer header gradient sheen (animated) */
@keyframes wh-drawer-sheen {
  0%   { background-position: 0% 50%; }
  50%  { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}
.wh-drawer-header-sheen {
  background-size: 200% 200%;
  animation: wh-drawer-sheen 8s ease-in-out infinite;
}

/* Health ring stroke draw-in animation */
@keyframes health-ring-draw {
  from { stroke-dasharray: 0 176; }
  to   { stroke-dasharray: var(--target-dash, 100) 176; }
}

/* Capacity bar threshold marker pulse */
@keyframes threshold-marker-pulse {
  0%, 100% { opacity: 0.5; transform: scaleY(1); }
  50%      { opacity: 1;   transform: scaleY(1.3); }
}
.threshold-marker {
  animation: threshold-marker-pulse 2.4s ease-in-out infinite;
  transform-origin: center;
}

/* Zone utilization card staggered entrance */
@keyframes zone-card-enter {
  from { opacity: 0; transform: translateY(8px) scale(0.96); }
  to   { opacity: 1; transform: translateY(0)   scale(1);    }
}
.zone-card-enter {
  animation: zone-card-enter 0.4s ease-out both;
}

/* Critical warehouse strip pulse */
@keyframes critical-wh-strip {
  0%, 100% { opacity: 1;   box-shadow: 0 0 0 0 oklch(0.6 0.25 25 / 0.6); }
  50%      { opacity: 0.7; box-shadow: 0 0 0 4px oklch(0.6 0.25 25 / 0);  }
}
.critical-wh-strip {
  animation: critical-wh-strip 1.8s ease-in-out infinite;
}

/* Stat card subtle hover lift (for warehouse drawer quick-stats) */
.wh-stat-card-hover {
