/* Cost category summary card hover — for clickable cards in cost-analytics-view */
.cost-summary-card-clickable {
  position: relative;
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}
.cost-summary-card-clickable::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(135deg, transparent 50%, rgba(59, 130, 246, 0.06) 100%);
  opacity: 0;
  transition: opacity 0.2s ease;
  pointer-events: none;
}
.cost-summary-card-clickable:hover::after {
  opacity: 1;
}
.cost-summary-card-clickable:active {
  transform: scale(0.985);
}

/* Pie slice hover — for clickable pie cells in cost breakdown */
.cost-pie-slice {
  cursor: pointer;
  transition: opacity 0.15s ease, transform 0.15s ease;
  transform-origin: center;
}
.cost-pie-slice:hover {
  opacity: 0.85;
  transform: scale(1.02);
}

