  cursor: pointer;
  position: relative;
  transition: background-color 0.15s ease, color 0.15s ease;
}
.cost-mom-cell::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 4px;
  background: currentColor;
  opacity: 0;
  transition: opacity 0.15s ease;
  pointer-events: none;
}
.cost-mom-cell:hover::before {
  opacity: 0.06;
}

