  100% { transform: translateX(200%) skewX(-15deg); }
}
.predictive-drawer-header::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 50%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.15), transparent);
  animation: predictive-header-sheen 5s ease-in-out infinite;
