  transition: transform 200ms cubic-bezier(0.22, 1, 0.36, 1), box-shadow 200ms ease;
}
.hover-lift-sm:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 24px -10px hsl(var(--foreground) / 0.15);
}

/* Frosted glass card with backdrop blur */
