.dark .sa-kpi-tile-label, .dark .sa-stat-label, .dark .sa-health-label,
.dark .sa-integration-label, .dark .sa-integration-sublabel,
.dark .sa-modal-stat-label {
  color: #94a3b8;
}
.dark .sa-tabs { border-bottom-color: #334155; }
.dark .sa-tab { color: #94a3b8; }
.dark .sa-tab:hover { color: #fb923c; background: #431407; }
.dark .sa-tab-active { color: #fb923c; border-bottom-color: #f97316; background: #431407; }
.dark .sa-table-wrap { background: #1e293b; border-color: #334155; }
.dark .sa-table thead { background: #431407; }
.dark .sa-table thead th { color: #fb923c; border-bottom-color: #c2410c; }
.dark .sa-table tbody td { border-bottom-color: #334155; color: #e2e8f0; }
.dark .sa-table tbody tr:hover { background: #431407; }
.dark .sa-row-danger { background: #450a0a !important; }
.dark .sa-row-warning { background: #451a03 !important; }
.dark .sa-row-success { background: #052e16 !important; }
.dark .sa-search-wrapper { background: #1e293b; border-color: #334155; }
.dark .sa-search-input { background: transparent; color: #e2e8f0; }
.dark .sa-select { background: #1e293b; border-color: #334155; color: #e2e8f0; }
.dark .sa-result-count { color: #94a3b8; }
.dark .sa-code-pill { background: #0f172a; color: #cbd5e1; }
.dark .sa-pill { background: #334155; color: #cbd5e1; }
.dark .sa-pill-info { background: #312e81; color: #c7d2fe; }
.dark .sa-pill-success { background: #052e16; color: #6ee7b7; }
.dark .sa-pill-warning { background: #451a03; color: #fdba74; }
.dark .sa-pill-danger { background: #450a0a; color: #fca5a5; }
.dark .sa-roi-pill { background: #334155; color: #cbd5e1; }
.dark .sa-roi-positive { background: #052e16; color: #6ee7b7; }
.dark .sa-roi-negative { background: #450a0a; color: #fca5a5; }
.dark .sa-spotlight-item { background: #0f172a; border-color: #334155; }
.dark .sa-spotlight-card-warning { background: #451a03; border-color: #c2410c; }
.dark .sa-spotlight-card-warning .sa-spotlight-item { background: #78350f; border-color: #c2410c; }
.dark .sa-spotlight-title { color: #f1f5f9; }
.dark .sa-spotlight-meta { color: #cbd5e1; }
.dark .sa-insight-row { background: #1e293b; }
.dark .sa-insight-title { color: #f1f5f9; }
.dark .sa-insight-description { color: #cbd5e1; }
.dark .sa-insight-recommendation { background: #431407; color: #fdba74; }
.dark .sa-modal-overlay { background: rgba(0,0,0,0.7); }
.dark .sa-modal-content { background: #1e293b; }
