.dark .sa-modal-section h4 { color: #fb923c; }
.dark .sa-modal-section p { color: #cbd5e1; }
.dark .sa-modal-risk { background: #450a0a; }
.dark .sa-modal-action-corrective { background: #431407; }
.dark .sa-modal-action-preventive { background: #052e16; }
.dark .sa-health-tile { background: #0f172a; border-color: #334155; }
.dark .sa-health-tile-overall { background: linear-gradient(135deg, #431407, #c2410c); border-color: #f97316; }
.dark .sa-health-tile-effectiveness { background: linear-gradient(135deg, #052e16, #15803d); border-color: #10b981; }

/* Responsive */
@media (max-width: 1024px) {
  .sa-kpi-banner { grid-template-columns: 1fr; }
  .sa-kpi-grid { grid-template-columns: repeat(3, 1fr); }
  .sa-charts-row { grid-template-columns: 1fr; }
  .sa-stat-tiles { grid-template-columns: repeat(3, 1fr); }
  .sa-health-grid { grid-template-columns: repeat(2, 1fr); }
  .sa-integration-grid { grid-template-columns: repeat(2, 1fr); }
  .sa-modal-meta-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 640px) {
  .sa-container { padding: 1rem; }
  .sa-kpi-grid { grid-template-columns: repeat(2, 1fr); }
  .sa-stat-tiles { grid-template-columns: repeat(2, 1fr); }
  .sa-health-grid { grid-template-columns: 1fr; }
  .sa-integration-grid { grid-template-columns: 1fr; }
  .sa-modal-meta-grid { grid-template-columns: 1fr; }
}
/* ============================================================================
   R112: ESG & Sustainability Audit Module Styles
   Color Theme: Emerald + Teal + Lime (sustainability/green)
   Prefix: .esg-
   ============================================================================ */

/* Container & Header */
.esg-container {
  max-width: 1600px;
  margin: 0 auto;
  font-family: inherit;
  animation: esg-fadeIn 0.3s ease;
}
@keyframes esg-fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.esg-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 1.5rem;
  background: linear-gradient(135deg, #ecfdf5, #f0fdfa, #f7fee7);
  border-radius: 12px;
  border: 1px solid #d1fae5;
  position: relative;
  overflow: hidden;
}
.esg-header::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, #059669, #0d9488, #84cc16, #059669);
  background-size: 200% 100%;
  animation: esg-headerGradient 10s linear infinite;
}
@keyframes esg-headerGradient {
  0% { background-position: 0% 0%; }
  100% { background-position: 200% 0%; }
}
.esg-header-title h1 {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 1.35rem;
  font-weight: 700;
  color: #064e3b;
  margin: 0;
}
.esg-subtitle {
  font-size: 0.8rem;
  color: #6b7280;
  margin-top: 2px;
}
.esg-header-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.esg-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.3rem 0.75rem;
  border-radius: 9999px;
  font-size: 0.78rem;
  font-weight: 600;
}
.esg-badge-esg { background: #059669; color: white; }
.esg-badge-rating { background: #0d9488; color: white; }
.esg-badge-score { background: #84cc16; color: #1a2e05; }

/* KPI Banner */
.esg-kpi-banner {
  display: flex;
  gap: 1rem;
  margin-top: 1rem;
  padding: 1rem;
  background: linear-gradient(135deg, #059669, #0d9488);
  border-radius: 12px;
  color: white;
  flex-wrap: wrap;
}
.esg-kpi-main {
  flex: 1;
  min-width: 180px;
  text-align: center;
  padding: 0.75rem;
  background: rgba(255,255,255,0.1);
  border-radius: 10px;
  backdrop-filter: blur(4px);
}
.esg-kpi-main-value {
  font-size: 2.5rem;
  font-weight: 800;
  line-height: 1;
}
.esg-kpi-main-label {
  font-size: 0.85rem;
  opacity: 0.9;
  margin-top: 0.25rem;
}
.esg-kpi-main-sublabel {
  font-size: 0.72rem;
  opacity: 0.75;
  margin-top: 0.2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.3rem;
}
.esg-kpi-grid {
  flex: 3;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.5rem;
  min-width: 0;
}
.esg-kpi-tile {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0.65rem;
  border-radius: 8px;
  background: rgba(255,255,255,0.95);
  color: #1e293b;
  border-left: 3px solid #059669;
  min-width: 0;
}
.esg-kpi-tile-emerald { border-left-color: #059669; }
.esg-kpi-tile-teal { border-left-color: #0d9488; }
.esg-kpi-tile-lime { border-left-color: #84cc16; }
.esg-kpi-tile-danger { border-left-color: #dc2626; }
.esg-kpi-tile-warning { border-left-color: #d97706; }
.esg-kpi-tile svg { flex-shrink: 0; }
.esg-kpi-tile-value { font-size: 1.1rem; font-weight: 700; }
.esg-kpi-tile-label { font-size: 0.68rem; color: #6b7280; }

/* Tabs */
.esg-tabs {
  display: flex;
  gap: 0;
  margin-top: 1rem;
  border-bottom: 2px solid #e5e7eb;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}
.esg-tab {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.6rem 1rem;
  font-size: 0.82rem;
  font-weight: 500;
  color: #6b7280;
  border: none;
  background: none;
  cursor: pointer;
  white-space: nowrap;
  border-bottom: 2px solid transparent;
  margin-bottom: -2px;
  transition: all 0.2s;
}
.esg-tab:hover { color: #059669; }
.esg-tab-active {
  color: #059669;
  font-weight: 600;
  border-bottom-color: #059669;
}

/* Tab Content */
.esg-tab-content {
  margin-top: 1rem;
  min-height: 300px;
}
.esg-tab-pane {
  animation: esg-fadeIn 0.2s ease;
}

/* Loading & Error */
.esg-loading, .esg-error {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  padding: 4rem;
  color: #6b7280;
  text-align: center;
}

/* Charts */
.esg-charts-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
  margin-bottom: 1rem;
}
.esg-chart-card {
  border: 1px solid #e5e7eb;
  border-radius: 10px;
  overflow: hidden;
  border-top: 3px solid #059669;
  padding: 1rem;
}
.esg-chart-header {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin-bottom: 0.75rem;
  font-size: 0.85rem;
  font-weight: 600;
  color: #1e293b;
}
.esg-trend-card {
  margin-bottom: 1rem;
}

/* Summary Cards (Carbon Footprint) */
.esg-summary-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 1.25rem !important;
}
.esg-summary-icon {
  width: 44px;
  height: 44px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 0.5rem;
}
.esg-summary-label {
  font-size: 0.75rem;
  color: #6b7280;
  margin-bottom: 0.2rem;
}
.esg-summary-value {
  font-size: 1.5rem;
  font-weight: 800;
  color: #1e293b;
}
.esg-summary-unit {
  font-size: 0.7rem;
  color: #6b7280;
}

/* Stat Tiles */
.esg-stat-tiles {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 0.75rem;
  margin-bottom: 1rem;
}
.esg-stat-tile {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.75rem 1rem;
  background: white;
  border: 1px solid #e5e7eb;
  border-radius: 10px;
}
.esg-stat-tile-emerald { border-left: 3px solid #059669; }
.esg-stat-tile-teal { border-left: 3px solid #0d9488; }
.esg-stat-tile-lime { border-left: 3px solid #84cc16; }
.esg-stat-tile-danger { border-left: 3px solid #dc2626; }
.esg-stat-tile-warning { border-left: 3px solid #d97706; }
.esg-stat-value { font-size: 1.2rem; font-weight: 700; color: #1e293b; }
.esg-stat-label { font-size: 0.72rem; color: #6b7280; }

/* Filter Bar */
.esg-filter-bar {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 1rem;
  flex-wrap: wrap;
}
.esg-search-wrapper {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  background: white;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  padding: 0 0.6rem;
  flex: 1;
  max-width: 320px;
}
.esg-search-wrapper svg { color: #9ca3af; flex-shrink: 0; }
.esg-search-input {
  border: none !important;
  box-shadow: none !important;
  font-size: 0.82rem;
  padding: 0.5rem 0 !important;
}
.esg-select {
  padding: 0.5rem 0.75rem;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  font-size: 0.82rem;
  background: white;
  color: #1e293b;
  cursor: pointer;
}
.esg-result-count {
  font-size: 0.78rem;
  color: #6b7280;
  margin-left: auto;
}

/* Tables */
.esg-table-wrap {
  overflow-x: auto;
  border: 1px solid #e5e7eb;
  border-radius: 10px;
  margin-top: 1rem;
}
.esg-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.78rem;
  min-width: 800px;
}
.esg-table thead {
  position: sticky;
  top: 0;
  z-index: 2;
}
.esg-table thead th {
  padding: 0.6rem 0.75rem;
  text-align: left;
  font-weight: 600;
  color: #059669;
  background: #f0fdf4;
  border-bottom: 2px solid #d1fae5;
  white-space: nowrap;
  font-size: 0.74rem;
  text-transform: uppercase;
  letter-spacing: 0.3px;
}
.esg-table tbody td {
  padding: 0.5rem 0.75rem;
  border-bottom: 1px solid #f3f4f6;
  vertical-align: middle;
}
.esg-table tbody tr:hover { background: #f0fdf4; }
.esg-row-danger { background: #fef2f2 !important; }
.esg-row-warning { background: #fffbeb !important; }
.esg-row-active { background: #fff7ed !important; }
.esg-row-success { background: #f0fdf4 !important; }
.esg-cell-title {
  max-width: 220px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-weight: 500;
}
.esg-cell-compact {
  white-space: nowrap;
  font-size: 0.74rem;
  color: #475569;
}

/* Pills & Badges */
.esg-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.2rem;
  padding: 0.15rem 0.5rem;
  border-radius: 9999px;
  font-size: 0.7rem;
  font-weight: 600;
  white-space: nowrap;
}
.esg-pill-danger { background: #dc262620; color: #dc2626; }
.esg-code-pill {
  display: inline-block;
  padding: 0.1rem 0.4rem;
  background: #f0fdf4;
  border: 1px solid #d1fae5;
  border-radius: 4px;
  font-family: monospace;
  font-size: 0.7rem;
  color: #065f46;
  font-weight: 500;
}
.esg-score-pill {
  display: inline-block;
  padding: 0.15rem 0.5rem;
  border-radius: 6px;
  font-size: 0.78rem;
  font-weight: 700;
  background: #f3f4f620;
  color: #1e293b;
}
.esg-score-good { background: #05966920; color: #059669; }
.esg-score-bad { background: #dc262620; color: #dc2626; }
.esg-gri-tag {
  display: inline-block;
  padding: 0.1rem 0.35rem;
  background: #04785715;
  border: 1px solid #04785730;
  border-radius: 4px;
  font-size: 0.65rem;
  color: #047857;
  font-weight: 600;
}
.esg-sdg-tag {
  display: inline-block;
  padding: 0.1rem 0.35rem;
  background: #be185d15;
  border: 1px solid #be185d30;
  border-radius: 4px;
  font-size: 0.65rem;
  color: #be185d;
  font-weight: 600;
}
.esg-gri-team {
  font-size: 0.68rem;
  color: #6b7280;
}

/* KPI Detail Grid */
.esg-kpi-detail-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
  margin-bottom: 1rem;
}
.esg-kpi-detail-card {
  border-top: 3px solid #059669;
  padding: 0.85rem;
  border-radius: 10px;
}
.esg-kpi-detail-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 0.35rem;
}
.esg-kpi-detail-dim {
  padding: 0.1rem 0.45rem;
  border-radius: 4px;
  font-size: 0.65rem;
  font-weight: 600;
  text-transform: uppercase;
}
.esg-kpi-detail-name {
  font-size: 0.82rem;
  font-weight: 600;
  color: #1e293b;
  margin-bottom: 0.3rem;
}
.esg-kpi-detail-values {
  display: flex;
  align-items: baseline;
  gap: 0.3rem;
  margin-bottom: 0.4rem;
}
.esg-kpi-detail-actual {
  font-size: 1.2rem;
  font-weight: 700;
  color: #1e293b;
}
.esg-kpi-detail-unit {
  font-size: 0.72rem;
  color: #6b7280;
}
.esg-kpi-detail-divider {
  color: #d1d5db;
  margin: 0 0.2rem;
}
.esg-kpi-detail-target {
  font-size: 0.72rem;
  color: #6b7280;
}
.esg-progress-bar {
  height: 4px;
  background: #e5e7eb;
  border-radius: 4px;
  overflow: hidden;
  margin-bottom: 0.4rem;
}
.esg-progress-fill {
  height: 100%;
  border-radius: 4px;
  transition: width 0.5s ease;
}
.esg-kpi-detail-footer {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  flex-wrap: wrap;
}

/* GRI Grid */
.esg-gri-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.75rem;
  margin-top: 1rem;
}
.esg-gri-card {
  border-top: 3px solid #059669;
  padding: 1rem;
  border-radius: 10px;
}
.esg-gri-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 0.35rem;
}
.esg-gri-code {
  font-family: monospace;
  font-size: 0.85rem;
  font-weight: 700;
  color: #059669;
}
.esg-gri-card-topic {
  font-size: 0.85rem;
  font-weight: 600;
  color: #1e293b;
  margin-bottom: 0.3rem;
}
.esg-gri-card-desc {
  font-size: 0.75rem;
  color: #6b7280;
  margin-bottom: 0.5rem;
  line-height: 1.4;
}
.esg-gri-card-footer {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.3rem;
}
.esg-gri-tag {
  padding: 0.1rem 0.4rem;
  border-radius: 4px;
  font-size: 0.68rem;
  font-weight: 500;
}
.esg-gri-card-meta {
  display: flex;
  gap: 0.75rem;
  font-size: 0.68rem;
  color: #9ca3af;
  flex-wrap: wrap;
}

/* Risk Heatmap */
.esg-heatmap-container {
  display: flex;
  gap: 0.5rem;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}
.esg-heatmap-label-y, .esg-heatmap-label-x {
  font-size: 0.75rem;
  font-weight: 600;
  color: #059669;
  writing-mode: vertical-lr;
  transform: rotate(180deg);
  padding: 0.5rem;
}
.esg-heatmap-label-x {
  writing-mode: horizontal-tb;
  transform: none;
  text-align: center;
}
.esg-heatmap-grid {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.esg-heatmap-row {
  display: flex;
  align-items: center;
  gap: 4px;
}
.esg-heatmap-row-label {
  font-size: 0.65rem;
  color: #6b7280;
  width: 70px;
  text-align: right;
  padding-right: 0.5rem;
}
.esg-heatmap-col-labels {
  display: flex;
  gap: 4px;
  margin-left: 70px;
  margin-top: 4px;
}
.esg-heatmap-col-label {
  font-size: 0.6rem;
  color: #6b7280;
  text-align: center;
  flex: 1;
}
.esg-heatmap-cell {
  width: 64px;
  height: 48px;
  border-radius: 6px;
  border: 1px solid;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  transition: transform 0.15s;
}
.esg-heatmap-cell:hover {
  transform: scale(1.1);
  z-index: 1;
}
.esg-heatmap-cell-score {
  font-size: 0.9rem;
  font-weight: 700;
  color: inherit;
}
.esg-heatmap-cell-count {
  font-size: 0.65rem;
  color: inherit;
  opacity: 0.8;
}

/* Compliance Deadline List */
.esg-deadline-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  max-height: 240px;
  overflow-y: auto;
}
.esg-deadline-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0.65rem;
  background: #f9fafb;
  border-radius: 8px;
  border-left: 3px solid #e5e7eb;
}
.esg-deadline-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}
.esg-deadline-content {
  flex: 1;
  min-width: 0;
}
.esg-deadline-title {
  font-size: 0.78rem;
  font-weight: 500;
  color: #1e293b;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.esg-deadline-meta {
  font-size: 0.68rem;
  color: #9ca3af;
}

/* Insights Section */
.esg-section-title {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 1rem;
  font-weight: 700;
  color: #1e293b;
  margin: 1.5rem 0 0.75rem;
}
.esg-insight-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.esg-insight-row {
  display: flex;
  gap: 0.75rem;
  padding: 0.85rem 1rem;
  border-radius: 10px;
  border: 1px solid #e5e7eb;
  border-left: 4px solid;
}
.esg-insight-danger { border-left-color: #dc2626; background: #fef2f2; }
.esg-insight-warning { border-left-color: #d97706; background: #fffbeb; }
.esg-insight-success { border-left-color: #059669; background: #f0fdf4; }
.esg-insight-info { border-left-color: #2563eb; background: #eff6ff; }
.esg-insight-icon { flex-shrink: 0; padding-top: 0.1rem; }
.esg-insight-danger .esg-insight-icon { color: #dc2626; }
.esg-insight-warning .esg-insight-icon { color: #d97706; }
.esg-insight-success .esg-insight-icon { color: #059669; }
.esg-insight-info .esg-insight-icon { color: #2563eb; }
.esg-insight-content { flex: 1; min-width: 0; }
.esg-insight-title { font-size: 0.85rem; font-weight: 600; color: #1e293b; margin-bottom: 0.2rem; }
.esg-insight-desc { font-size: 0.78rem; color: #475569; margin-bottom: 0.3rem; line-height: 1.4; }
.esg-insight-rec { font-size: 0.75rem; color: #6b7280; line-height: 1.4; }

/* Health Scorecard */
.esg-health-tiles {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 0.75rem;
}
.esg-health-tile {
  text-align: center;
  padding: 1rem;
  border-radius: 10px;
  border-top: 3px solid #059669;
}
.esg-health-tile-icon {
  width: 44px;
  height: 44px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 0.5rem;
}
.esg-health-tile-value {
  font-size: 1.8rem;
  font-weight: 800;
  line-height: 1;
}
.esg-health-tile-label {
  font-size: 0.72rem;
  color: #6b7280;
  margin-top: 0.25rem;
}
.esg-health-tile-bar {
  height: 4px;
  background: #e5e7eb;
  border-radius: 4px;
  overflow: hidden;
  margin-top: 0.5rem;
}
.esg-health-tile-fill {
  height: 100%;
  border-radius: 4px;
  transition: width 0.6s ease;
}

/* SDG Grid */
.esg-sdg-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 0.75rem;
}
.esg-sdg-tile {
  border-radius: 12px;
  padding: 1.25rem;
  color: white;
  text-align: center;
  min-height: 140px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
}
.esg-sdg-tile-number {
  font-size: 0.72rem;
  font-weight: 700;
  opacity: 0.9;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.esg-sdg-tile-name {
  font-size: 0.82rem;
  font-weight: 600;
  line-height: 1.3;
}
.esg-sdg-tile-stats {
  display: flex;
  gap: 0.75rem;
  font-size: 0.68rem;
  opacity: 0.85;
}

/* Modal */
.esg-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  animation: esg-fadeIn 0.15s ease;
}
.esg-modal {
  background: white;
  border-radius: 14px;
  max-width: 800px;
  width: 100%;
  max-height: 85vh;
  overflow-y: auto;
  box-shadow: 0 25px 50px -12px rgba(0,0,0,0.25);
  border-top: 4px solid #059669;
}
.esg-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 1.25rem;
  border-bottom: 1px solid #e5e7eb;
}
.esg-modal-header h3 {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 1rem;
  font-weight: 600;
  color: #1e293b;
}
.esg-modal-header button {
  background: none;
  border: none;
  cursor: pointer;
  color: #6b7280;
  padding: 0.25rem;
  border-radius: 6px;
}
.esg-modal-header button:hover { background: #f3f4f6; color: #1e293b; }
.esg-modal-body {
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
.esg-modal-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
}
.esg-modal-field {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}
.esg-modal-label {
  font-size: 0.7rem;
  font-weight: 600;
  color: #6b7280;
  text-transform: uppercase;
  letter-spacing: 0.3px;
}
.esg-modal-field > span:last-child {
  font-size: 0.85rem;
  color: #1e293b;
}
.esg-modal-subsection {
  margin-top: 0.75rem;
  padding-top: 0.75rem;
  border-top: 1px solid #e5e7eb;
}
.esg-modal-subsection h4 {
  font-size: 0.85rem;
  font-weight: 600;
  color: #1e293b;
  margin-bottom: 0.5rem;
}
.esg-modal-finding-row {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.4rem 0.5rem;
  background: #f9fafb;
  border-radius: 6px;
  margin-bottom: 0.35rem;
}
.esg-finding-summary {
  font-size: 0.75rem;
  color: #475569;
  flex: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Dark Mode */
@media (prefers-color-scheme: dark) {
  .esg-header {
    background: linear-gradient(135deg, #052e16, #042f2e, #1a2e05);
    border-color: #064e3b;
  }
  .esg-header-title h1 { color: #ecfdf5; }
  .esg-kpi-banner { background: linear-gradient(135deg, #064e3b, #115e59); }
  .esg-kpi-tile { background: rgba(15,23,42,0.95); color: #e2e8f0; }
  .esg-tab { color: #9ca3af; }
  .esg-tab-active { color: #34d399; border-bottom-color: #34d399; }
  .esg-tabs { border-bottom-color: #374151; }
  .esg-chart-card { border-color: #374151; background: #0f172a; border-top-color: #059669; }
  .esg-chart-header { color: #e2e8f0; }
  .esg-table-wrap { border-color: #374151; }
  .esg-table thead th { background: #052e16; color: #34d399; border-bottom-color: #064e3b; }
  .esg-table tbody td { border-bottom-color: #1e293b; color: #cbd5e1; }
  .esg-table tbody tr:hover { background: #052e1630; }
  .esg-row-danger { background: #450a0a40 !important; }
  .esg-row-warning { background: #451a0340 !important; }
  .esg-row-active { background: #43140740 !important; }
  .esg-stat-tile { background: #0f172a; border-color: #374151; }
  .esg-code-pill { background: #052e16; border-color: #064e3b; color: #34d399; }
  .esg-select { background: #0f172a; border-color: #374151; color: #e2e8f0; }
  .esg-search-wrapper { background: #0f172a; border-color: #374151; }
  .esg-cell-title { color: #e2e8f0; }
  .esg-cell-compact { color: #94a3b8; }
  .esg-insight-row { background: #0f172a; border-color: #374151; }
  .esg-insight-danger { border-left-color: #f87171; background: #1c0a0a; }
  .esg-insight-warning { border-left-color: #fbbf24; background: #1a1506; }
  .esg-insight-success { border-left-color: #34d399; background: #052e16; }
  .esg-insight-info { border-left-color: #60a5fa; background: #0a1628; }
  .esg-insight-title { color: #e2e8f0; }
  .esg-kpi-detail-card { background: #0f172a; }
  .esg-kpi-detail-name { color: #e2e8f0; }
  .esg-kpi-detail-actual { color: #e2e8f0; }
  .esg-kpi-detail-target { color: #9ca3af; }
  .esg-progress-bar { background: #1e293b; }
  .esg-gri-card { background: #0f172a; }
  .esg-gri-card-topic { color: #e2e8f0; }
  .esg-gri-card-desc { color: #94a3b8; }
  .esg-gri-card-meta { color: #6b7280; }
  .esg-health-tile { background: #0f172a; }
  .esg-health-tile-label { color: #9ca3af; }
  .esg-health-tile-bar { background: #1e293b; }
  .esg-modal { background: #0f172a; border-top-color: #059669; }
  .esg-modal-header { border-bottom-color: #374151; }
  .esg-modal-header h3 { color: #e2e8f0; }
  .esg-modal-label { color: #9ca3af; }
  .esg-modal-field > span:last-child { color: #e2e8f0; }
  .esg-modal-finding-row { background: #1e293b; }
  .esg-finding-summary { color: #94a3b8; }
  .esg-deadline-item { background: #1e293b; border-left-color: #374151; }
  .esg-deadline-title { color: #e2e8f0; }
  .esg-section-title { color: #e2e8f0; }
  .esg-score-pill { background: #1e293b20; color: #e2e8f0; }
  .esg-score-good { background: #05966920; color: #34d399; }
  .esg-score-bad { background: #dc262620; color: #f87171; }
  .esg-heatmap-cell { border-color: #374151; }
  .esg-heatmap-row-label { color: #9ca3af; }
  .esg-heatmap-col-label { color: #9ca3af; }
}

/* Responsive */
@media (max-width: 1024px) {
  .esg-charts-row { grid-template-columns: repeat(2, 1fr); }
  .esg-kpi-grid { grid-template-columns: repeat(2, 1fr); }
  .esg-stat-tiles { grid-template-columns: repeat(3, 1fr); }
  .esg-kpi-detail-grid { grid-template-columns: repeat(2, 1fr); }
  .esg-health-tiles { grid-template-columns: repeat(3, 1fr); }
  .esg-sdg-grid { grid-template-columns: repeat(3, 1fr); }
  .esg-gri-grid { grid-template-columns: 1fr; }
  .esg-modal-row { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 640px) {
  .esg-container { padding: 0.75rem; }
  .esg-header { flex-direction: column; gap: 0.75rem; text-align: center; }
  .esg-header-actions { flex-wrap: wrap; justify-content: center; }
  .esg-kpi-banner { flex-direction: column; }
  .esg-kpi-grid { grid-template-columns: repeat(2, 1fr); }
  .esg-charts-row { grid-template-columns: 1fr; }
  .esg-stat-tiles { grid-template-columns: repeat(2, 1fr); }
  .esg-kpi-detail-grid { grid-template-columns: 1fr; }
  .esg-health-tiles { grid-template-columns: repeat(2, 1fr); }
  .esg-sdg-grid { grid-template-columns: repeat(2, 1fr); }
  .esg-modal-row { grid-template-columns: 1fr; }
  .esg-filter-bar { flex-direction: column; align-items: stretch; }
  .esg-search-wrapper { max-width: 100%; }
  .esg-tabs { gap: 0; }
  .esg-tab { padding: 0.5rem 0.6rem; font-size: 0.75rem; }
}
/* ============================================================================
   R111: Fixed Asset Register CSS
   ============================================================================ */

/* Container */
.far-container {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
  font-family: 'Inter', system-ui, sans-serif;
  color: #0f172a;
  animation: far-fade-in 0.4s ease-out;
}

@keyframes far-fade-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Loading state */
.far-loading {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 4rem;
  gap: 1rem;
  color: #6366f1;
}

.far-loading-icon {
  animation: far-spin 1s linear infinite;
  width: 2rem;
  height: 2rem;
}

@keyframes far-spin {
  to { transform: rotate(360deg); }
}

/* Header */
.far-header {
  position: relative;
  background: linear-gradient(135deg, #1e1b4b 0%, #312e81 50%, #4338ca 100%);
  color: #fff;
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 10px 30px -10px rgba(99, 102, 241, 0.4);
}

.far-header-top-border {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(90deg, #6366f1, #8b5cf6, #d946ef, #8b5cf6, #6366f1);
  background-size: 200% 100%;
  animation: far-gradient-shift 10s linear infinite;
}

@keyframes far-gradient-shift {
  0% { background-position: 0% 50%; }
  100% { background-position: 200% 50%; }
}

.far-header-content {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 1.5rem;
  gap: 1rem;
  flex-wrap: wrap;
}

.far-header-left {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.far-header-icon-wrapper {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  background: linear-gradient(135deg, #818cf8 0%, #c084fc 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 4px 12px rgba(129, 140, 248, 0.5);
}

.far-header-icon {
  width: 24px;
  height: 24px;
  color: #fff;
}

.far-header-title {
  font-size: 1.5rem;
  font-weight: 700;
  margin: 0;
  letter-spacing: -0.025em;
  background: linear-gradient(135deg, #fff 0%, #e0e7ff 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.far-header-subtitle {
  font-size: 0.8rem;
  color: #c7d2fe;
  margin: 0.25rem 0 0 0;
}

.far-header-right {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.far-header-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.375rem 0.75rem;
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.025em;
}

.far-header-badge-primary {
  background: rgba(129, 140, 248, 0.2);
  color: #c7d2fe;
  border: 1px solid rgba(129, 140, 248, 0.4);
}

.far-header-badge-info {
  background: rgba(34, 211, 238, 0.15);
  color: #a5f3fc;
  border: 1px solid rgba(34, 211, 238, 0.3);
}

.far-header-refresh {
  background: rgba(255, 255, 255, 0.1) !important;
  color: #fff !important;
  border: 1px solid rgba(255, 255, 255, 0.2) !important;
  backdrop-filter: blur(8px);
}

.far-header-refresh:hover {
  background: rgba(255, 255, 255, 0.2) !important;
}

/* KPI Banner */
.far-kpi-banner {
  display: grid;
  grid-template-columns: minmax(260px, 1fr) 3fr;
  gap: 1rem;
}

.far-kpi-main {
  background: linear-gradient(135deg, #4338ca 0%, #6366f1 50%, #818cf8 100%);
  border-radius: 14px;
  padding: 1.25rem 1.5rem;
  color: #fff;
  display: flex;
  align-items: center;
  gap: 1rem;
  box-shadow: 0 8px 24px -8px rgba(67, 56, 202, 0.5);
  position: relative;
  overflow: hidden;
}

.far-kpi-main::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.1) 0%, transparent 60%);
  animation: far-shimmer 8s linear infinite;
}

@keyframes far-shimmer {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

.far-kpi-main-icon {
  width: 56px;
  height: 56px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  backdrop-filter: blur(8px);
  flex-shrink: 0;
  position: relative;
  z-index: 1;
}

.far-kpi-main-label {
  font-size: 0.7rem;
  color: #c7d2fe;
  margin: 0;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-weight: 500;
}

.far-kpi-main-value {
  font-size: 1.75rem;
  font-weight: 700;
  margin: 0.125rem 0;
  letter-spacing: -0.025em;
  position: relative;
  z-index: 1;
}

.far-kpi-main-sub {
  font-size: 0.75rem;
  color: #e0e7ff;
  margin: 0;
  position: relative;
  z-index: 1;
}

