  padding: 6px 12px;
  font-size: 12px;
  color: white;
}

/* Tab Bar */
.wps-tab-bar {
  margin-top: 12px;
}
.wps-tab {
  padding: 8px 16px;
  border-radius: 8px 8px 0 0;
  font-size: 13px;
  font-weight: 500;
  color: #6b7280;
  background: transparent;
  border: none;
  cursor: pointer;
  transition: all 0.2s;
  white-space: nowrap;
  position: relative;
}
.wps-tab:hover {
  color: #7c3aed;
