  overflow: hidden;
  box-shadow: 0 4px 24px rgba(220, 38, 38, 0.2), 0 0 0 1px rgba(255,255,255,0.1);
}
.sim-header::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, #fbbf24, #ef4444, #3b82f6, #fbbf24);
  background-size: 200% 100%;
  animation: sim-gradientBorder 6s linear infinite;
}
@keyframes sim-gradientBorder {
  0% { background-position: 0% 0%; }
  100% { background-position: 200% 0%; }
}
.sim-header-content {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  position: relative;
  z-index: 1;
}
.sim-header-icon {
  width: 44px;
  height: 44px;
  background: rgba(255,255,255,0.15);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  backdrop-filter: blur(8px);
  border: 1px solid rgba(255,255,255,0.2);
}
.sim-header-badges {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
}
.sim-header-badge {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.375rem 0.75rem;
  border-radius: 8px;
  border: 1px solid;
  backdrop-filter: blur(8px);
}

/* Tabs */
.sim-tabs {
  display: flex;
  gap: 0.25rem;
  margin-top: 1rem;
  padding: 0.25rem;
  background: hsl(var(--muted));
  border-radius: 10px;
  overflow-x: auto;
  scrollbar-width: thin;
}
.sim-tab {
  padding: 0.5rem 1rem;
  border-radius: 8px;
  font-size: 0.75rem;
  font-weight: 500;
  color: hsl(var(--muted-foreground));
  cursor: pointer;
  transition: all 0.25s ease;
  white-space: nowrap;
  border: none;
  background: transparent;
}
.sim-tab:hover {
  color: hsl(var(--foreground));
  background: hsl(var(--accent));
}
.sim-tab.active {
  background: #dc2626;
  color: white;
  font-weight: 600;
  box-shadow: 0 2px 8px rgba(220, 38, 38, 0.3);
}

/* Content */
.sim-content {
  margin-top: 1rem;
}

/* KPI Cards */
.sim-kpi-card {
  border-radius: 12px;
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  position: relative;
  overflow: hidden;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
  animation: sim-slideUp 0.4s ease-out both;
}
.sim-kpi-card:nth-child(1) { animation-delay: 0.05s; }
.sim-kpi-card:nth-child(2) { animation-delay: 0.1s; }
.sim-kpi-card:nth-child(3) { animation-delay: 0.15s; }
.sim-kpi-card:nth-child(4) { animation-delay: 0.2s; }
.sim-kpi-card:nth-child(5) { animation-delay: 0.25s; }
@keyframes sim-slideUp {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}
.sim-kpi-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 24px rgba(0,0,0,0.15);
}
.sim-kpi-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  border-radius: 12px 12px 0 0;
}
.sim-kpi-total { background: linear-gradient(135deg, #1e40af, #3b82f6); }
.sim-kpi-total::before { background: linear-gradient(90deg, #60a5fa, #93c5fd); }
.sim-kpi-open { background: linear-gradient(135deg, #b91c1c, #ef4444); }
.sim-kpi-open::before { background: linear-gradient(90deg, #f87171, #fca5a5); }
.sim-kpi-critical { background: linear-gradient(135deg, #92400e, #f59e0b); }
.sim-kpi-critical::before { background: linear-gradient(90deg, #fbbf24, #fde68a); }
.sim-kpi-nearmiss { background: linear-gradient(135deg, #9f1239, #e11d48); }
.sim-kpi-nearmiss::before { background: linear-gradient(90deg, #fb7185, #fda4af); }
.sim-kpi-cost { background: linear-gradient(135deg, #065f46, #10b981); }
.sim-kpi-cost::before { background: linear-gradient(90deg, #34d399, #6ee7b7); }

/* Card wrapper */
.sim-card {
  transition: transform 0.25s ease, box-shadow 0.25s ease;
  animation: sim-cardFadeIn 0.5s ease-out both;
}
.sim-card:hover {
  box-shadow: 0 4px 20px rgba(0,0,0,0.08);
}
@keyframes sim-cardFadeIn {
  from { opacity: 0; transform: scale(0.98); }
  to { opacity: 1; transform: scale(1); }
}

/* Filter Bar */
.sim-filter-bar {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1rem;
  background: hsl(var(--card));
  border: 1px solid hsl(var(--border));
  border-radius: 10px;
  flex-wrap: wrap;
  animation: sim-cardFadeIn 0.3s ease-out;
}
.sim-search-box {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.375rem 0.75rem;
  background: hsl(var(--muted));
  border: 1px solid transparent;
  border-radius: 8px;
  flex: 1;
  min-width: 180px;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.sim-search-box:focus-within {
  border-color: #dc2626;
  box-shadow: 0 0 0 2px rgba(220, 38, 38, 0.15);
}
.sim-search-input {
  border: none;
  background: transparent;
  outline: none;
  font-size: 0.75rem;
  width: 100%;
  color: hsl(var(--foreground));
}
.sim-filter-select {
  padding: 0.375rem 0.625rem;
  border: 1px solid hsl(var(--border));
  border-radius: 8px;
  font-size: 0.75rem;
  background: hsl(var(--muted));
  color: hsl(var(--foreground));
  cursor: pointer;
  transition: border-color 0.2s ease;
}
.sim-filter-select:focus {
  border-color: #dc2626;
  outline: none;
  box-shadow: 0 0 0 2px rgba(220, 38, 38, 0.15);
}

/* Table */
.sim-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  font-size: 0.75rem;
}
.sim-table thead th {
  padding: 0.625rem 0.75rem;
  text-align: left;
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: hsl(var(--muted-foreground));
  border-bottom: 2px solid hsl(var(--border));
  background: hsl(var(--muted) / 0.5);
  position: sticky;
  top: 0;
}
.sim-table-row {
  transition: background-color 0.15s ease, transform 0.15s ease;
