/* ========================================================================
   R120: Cold Chain & Temperature Logistics
   Theme: Cyan + Blue + Amber (#06b6d4, #3b82f6, #f59e0b)
   Prefix: cc-
   ======================================================================== */

/* Container & Header */
.cc-container {
  max-width: 100%;
}

.cc-header {
  position: relative;
  background: linear-gradient(135deg, #0e7490, #1d4ed8, #d97706);
  border-radius: 12px;
  padding: 24px;
  overflow: hidden;
  animation: cc-header-glow 6s ease-in-out infinite alternate;
}

.cc-header::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, #06b6d4, #3b82f6, #f59e0b, #06b6d4);
  background-size: 300% 100%;
  animation: cc-gradient-shift 6s linear infinite;
}

@keyframes cc-gradient-shift {
  0% { background-position: 0% 50%; }
  100% { background-position: 300% 50%; }
}

@keyframes cc-header-glow {
  0% { box-shadow: 0 4px 20px rgba(6, 182, 212, 0.3); }
  50% { box-shadow: 0 4px 20px rgba(59, 130, 246, 0.3); }
  100% { box-shadow: 0 4px 20px rgba(245, 158, 11, 0.3); }
}

.cc-header-content {
  display: flex;
  align-items: center;
  gap: 16px;
}

.cc-header-icon-wrap {
  width: 48px;
  height: 48px;
  background: rgba(255, 255, 255, 0.15);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  backdrop-filter: blur(10px);
}

.cc-header-title {
  font-size: 1.25rem;
  font-weight: 700;
  color: white;
  line-height: 1.3;
}

.cc-header-subtitle {
  font-size: 0.8rem;
  color: rgba(255, 255, 255, 0.7);
  margin-top: 2px;
}

.cc-header-badges {
  display: flex;
  gap: 12px;
  margin-top: 16px;
  flex-wrap: wrap;
}

.cc-header-badge {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  border-radius: 8px;
  font-size: 0.75rem;
  font-weight: 600;
  backdrop-filter: blur(10px);
}

.cc-badge-green {
  background: rgba(16, 185, 129, 0.25);
  color: #6ee7b7;
  border: 1px solid rgba(16, 185, 129, 0.3);
}

.cc-badge-red {
  background: rgba(239, 68, 68, 0.25);
  color: #fca5a5;
  border: 1px solid rgba(239, 68, 68, 0.3);
}

.cc-badge-blue {
  background: rgba(59, 130, 246, 0.25);
  color: #93c5fd;
  border: 1px solid rgba(59, 130, 246, 0.3);
}

/* Tabs */
.cc-tabs {
  display: flex;
  gap: 4px;
  padding: 4px;
  background: hsl(var(--muted));
  border-radius: 10px;
  overflow-x: auto;
}

.cc-tab {
  padding: 8px 16px;
