.cc-kpi-green { background: linear-gradient(135deg, #ecfdf5, #d1fae5); }
.cc-kpi-red { background: linear-gradient(135deg, #fef2f2, #fee2e2); }
.cc-kpi-amber { background: linear-gradient(135deg, #fffbeb, #fef3c7); }
