/* ===== STAGGER ANIMATIONS ===== */
@keyframes snSlideUp {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}
.sn-stagger-1 { animation: snSlideUp 0.35s ease-out 0.02s both; }
.sn-stagger-2 { animation: snSlideUp 0.35s ease-out 0.06s both; }
.sn-stagger-3 { animation: snSlideUp 0.35s ease-out 0.1s both; }
.sn-stagger-4 { animation: snSlideUp 0.35s ease-out 0.14s both; }
.sn-stagger-5 { animation: snSlideUp 0.35s ease-out 0.18s both; }
.sn-stagger-6 { animation: snSlideUp 0.35s ease-out 0.22s both; }
.sn-stagger-7 { animation: snSlideUp 0.35s ease-out 0.26s both; }
.sn-stagger-8 { animation: snSlideUp 0.35s ease-out 0.3s both; }
.sn-stagger-9 { animation: snSlideUp 0.35s ease-out 0.34s both; }
.sn-stagger-10 { animation: snSlideUp 0.35s ease-out 0.38s both; }
.sn-stagger-11 { animation: snSlideUp 0.35s ease-out 0.42s both; }
.sn-stagger-12 { animation: snSlideUp 0.35s ease-out 0.46s both; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .sn-overview-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .sn-recall-kpis {
    grid-template-columns: repeat(3, 1fr);
  }
  .sn-compliance-kpis {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .sn-overview-grid {
    grid-template-columns: 1fr;
  }
  .sn-recall-kpis {
    grid-template-columns: repeat(2, 1fr);
  }
  .sn-compliance-kpis {
    grid-template-columns: repeat(2, 1fr);
  }
  .sn-header-content {
    flex-direction: column;
    align-items: flex-start;
  }
  .sn-drawer {
    width: 100%;
  }
  .sn-drawer-info-grid {
    grid-template-columns: 1fr;
  }
}

