/* ============================================================
   R126: Packaging Standards & Specifications Management
   Theme: Rose + Cyan + Lime (#f43f5e, #06b6d4, #84cc16)
   Prefix: pkg-*
   ============================================================ */

/* --- Animated Gradient Top Border (Rose → Cyan → Lime, 6s) --- */
.pkg-header-banner {
  position: relative;
  background: linear-gradient(135deg, #fff1f2 0%, #ecfeff 50%, #f7fee7 100%);
  border-radius: 16px;
  padding: 24px 28px 20px;
  overflow: hidden;
  border: 1px solid rgba(244, 63, 94, 0.1);
}
.pkg-header-banner::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(90deg, #f43f5e, #06b6d4, #84cc16, #f43f5e);
  background-size: 300% 100%;
  animation: pkgGradientShift 6s ease infinite;
}
@keyframes pkgGradientShift {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

/* --- Dark Mode Header --- */
:is(.dark .pkg-header-banner) {
  background: linear-gradient(135deg, rgba(244, 63, 94, 0.08) 0%, rgba(6, 182, 212, 0.08) 50%, rgba(132, 204, 22, 0.08) 100%);
  border-color: rgba(244, 63, 94, 0.15);
}

/* --- KPI Cards --- */
.pkg-kpi-card {
  border-radius: 14px;
  padding: 20px;
  border: 1px solid rgba(0, 0, 0, 0.06);
  transition: transform 0.25s ease, box-shadow 0.25s ease;
  position: relative;
  overflow: hidden;
}
.pkg-kpi-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 25px -5px rgba(0, 0, 0, 0.1);
}
.pkg-kpi-card::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 3px;
}
.pkg-kpi-rose { background: linear-gradient(135deg, #fff1f2 0%, #ffe4e6 100%); }
.pkg-kpi-rose::after { background: linear-gradient(90deg, #f43f5e, #fb7185); }
.pkg-kpi-cyan { background: linear-gradient(135deg, #ecfeff 0%, #cffafe 100%); }
.pkg-kpi-cyan::after { background: linear-gradient(90deg, #06b6d4, #22d3ee); }
.pkg-kpi-lime { background: linear-gradient(135deg, #f7fee7 0%, #ecfccb 100%); }
.pkg-kpi-lime::after { background: linear-gradient(90deg, #84cc16, #a3e635); }
.pkg-kpi-amber { background: linear-gradient(135deg, #fffbeb 0%, #fef3c7 100%); }
.pkg-kpi-amber::after { background: linear-gradient(90deg, #f59e0b, #fbbf24); }
.pkg-kpi-indigo { background: linear-gradient(135deg, #eef2ff 0%, #e0e7ff 100%); }
.pkg-kpi-indigo::after { background: linear-gradient(90deg, #6366f1, #818cf8); }
.pkg-kpi-emerald { background: linear-gradient(135deg, #ecfdf5 0%, #d1fae5 100%); }
.pkg-kpi-emerald::after { background: linear-gradient(90deg, #10b981, #34d399); }

/* Dark KPI */
:is(.dark .pkg-kpi-rose) { background: linear-gradient(135deg, rgba(244,63,94,0.1) 0%, rgba(244,63,94,0.05) 100%); }
:is(.dark .pkg-kpi-cyan) { background: linear-gradient(135deg, rgba(6,182,212,0.1) 0%, rgba(6,182,212,0.05) 100%); }
:is(.dark .pkg-kpi-lime) { background: linear-gradient(135deg, rgba(132,204,22,0.1) 0%, rgba(132,204,22,0.05) 100%); }
:is(.dark .pkg-kpi-amber) { background: linear-gradient(135deg, rgba(245,158,11,0.1) 0%, rgba(245,158,11,0.05) 100%); }
:is(.dark .pkg-kpi-indigo) { background: linear-gradient(135deg, rgba(99,102,241,0.1) 0%, rgba(99,102,241,0.05) 100%); }
:is(.dark .pkg-kpi-emerald) { background: linear-gradient(135deg, rgba(16,185,129,0.1) 0%, rgba(16,185,129,0.05) 100%); }

/* --- Packaging Type Badges --- */
