:is(.dark .pkg-badge-under-review) { background: rgba(59,130,246,0.15); color: #93c5fd; border-color: rgba(59,130,246,0.3); }

/* --- Stock Status Badges --- */
.pkg-badge-in-stock { background: #dcfce7; color: #166534; }
.pkg-badge-low-stock { background: #fef3c7; color: #92400e; animation: pkgLowStockPulse 2s ease-in-out infinite; }
.pkg-badge-critical { background: #fee2e2; color: #991b1b; animation: pkgCriticalPulse 1.5s ease-in-out infinite; }
.pkg-badge-out-of-stock { background: #fee2e2; color: #991b1b; }
@keyframes pkgLowStockPulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.7; } }
@keyframes pkgCriticalPulse { 0%, 100% { opacity: 1; box-shadow: 0 0 0 0 rgba(239,68,68,0.3); } 50% { opacity: 0.85; box-shadow: 0 0 8px 2px rgba(239,68,68,0.2); } }
:is(.dark .pkg-badge-in-stock) { background: rgba(34,197,94,0.15); color: #86efac; }
:is(.dark .pkg-badge-low-stock) { background: rgba(245,158,11,0.15); color: #fbbf24; }
:is(.dark .pkg-badge-critical) { background: rgba(239,68,68,0.15); color: #fca5a5; }
:is(.dark .pkg-badge-out-of-stock) { background: rgba(239,68,68,0.15); color: #fca5a5; }

