:is(.dark .pkg-badge-low-priority) { background: rgba(34,197,94,0.15); color: #86efac; }

/* --- Spec Detail Drawer --- */
.pkg-drawer-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.4);
  backdrop-filter: blur(4px);
  z-index: 50;
  animation: pkgFadeIn 0.2s ease;
}
.pkg-drawer-panel {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: 520px;
  background: white;
  z-index: 51;
  box-shadow: -8px 0 30px rgba(0, 0, 0, 0.12);
  overflow-y: auto;
  animation: pkgSlideIn 0.3s ease;
}
:is(.dark .pkg-drawer-panel) {
  background: #1e293b;
  box-shadow: -8px 0 30px rgba(0, 0, 0, 0.4);
}
@keyframes pkgFadeIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes pkgSlideIn { from { transform: translateX(100%); } to { transform: translateX(0); } }

/* --- Drawer Status Banner --- */
.pkg-drawer-status-banner {
  padding: 16px 20px;
  border-radius: 10px;
  margin-bottom: 16px;
}
