.slot-progress-purple { background: linear-gradient(90deg, #8b5cf6, #a78bfa); }
.slot-progress-orange { background: linear-gradient(90deg, #f97316, #fb923c); }
.slot-progress-teal { background: linear-gradient(90deg, #14b8a6, #2dd4bf); }
.slot-progress-green { background: linear-gradient(90deg, #22c55e, #4ade80); }
.slot-progress-amber { background: linear-gradient(90deg, #f59e0b, #fbbf24); }
.slot-progress-red { background: linear-gradient(90deg, #ef4444, #f87171); }
.slot-progress-rose { background: linear-gradient(90deg, #f43f5e, #fb7185); }
:is(.dark .slot-progress-bar) { background: #374151; }

/* --- Heatmap cell (for pick frequency) --- */
.slot-heat-0 { background: #f0fdf4; border-color: #86efac; }
.slot-heat-1 { background: #dcfce7; border-color: #4ade80; }
.slot-heat-2 { background: #fef08a; border-color: #facc15; }
.slot-heat-3 { background: #fed7aa; border-color: #fb923c; }
.slot-heat-4 { background: #fecaca; border-color: #f87171; }
:is(.dark .slot-heat-0) { background: rgba(34,197,94,0.08); border-color: rgba(34,197,94,0.2); }
:is(.dark .slot-heat-1) { background: rgba(34,197,94,0.15); border-color: rgba(34,197,94,0.3); }
:is(.dark .slot-heat-2) { background: rgba(234,179,8,0.15); border-color: rgba(234,179,8,0.3); }
:is(.dark .slot-heat-3) { background: rgba(249,115,22,0.15); border-color: rgba(249,115,22,0.3); }
:is(.dark .slot-heat-4) { background: rgba(239,68,68,0.15); border-color: rgba(239,68,68,0.3); }

/* --- Filter Bar --- */
.slot-filter-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  padding: 16px 20px;
  background: white;
  border-radius: 12px;
  border: 1px solid rgba(0, 0, 0, 0.06);
  margin-bottom: 16px;
}
:is(.dark .slot-filter-bar) {
  background: #1e293b;
  border-color: rgba(255, 255, 255, 0.08);
}

/* --- Data Table --- */
.slot-data-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
}
.slot-data-table thead th {
  padding: 12px 16px;
  text-align: left;
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #6b7280;
  background: #f9fafb;
  border-bottom: 2px solid #e5e7eb;
  white-space: nowrap;
}
.slot-data-table tbody td {
  padding: 12px 16px;
  font-size: 14px;
  border-bottom: 1px solid #f3f4f6;
  color: #1f2937;
}
.slot-data-table tbody tr:hover { background: #f9fafb; }
.slot-data-table tbody tr:last-child td { border-bottom: none; }
:is(.dark .slot-data-table thead th) { background: #0f172a; color: #9ca3af; border-bottom-color: #374151; }
:is(.dark .slot-data-table tbody td) { color: #e5e7eb; border-bottom-color: #1f2937; }
:is(.dark .slot-data-table tbody tr:hover) { background: #1e293b; }

/* --- Section Cards --- */
.slot-section-card {
  background: white;
  border-radius: 12px;
  border: 1px solid rgba(0, 0, 0, 0.06);
  padding: 20px;
  margin-bottom: 16px;
}
:is(.dark .slot-section-card) {
  background: #1e293b;
  border-color: rgba(255, 255, 255, 0.08);
}

/* --- Drawer --- */
.slot-drawer-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.4);
  backdrop-filter: blur(4px);
  z-index: 50;
  animation: slotFadeIn 0.2s ease;
}
.slot-drawer-panel {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: 520px;
  background: white;
  z-index: 51;
  box-shadow: -8px 0 30px rgba(0, 0, 0, 0.12);
  overflow-y: auto;
  animation: slotSlideIn 0.3s ease;
}
:is(.dark .slot-drawer-panel) {
  background: #1e293b;
  box-shadow: -8px 0 30px rgba(0, 0, 0, 0.4);
}
@keyframes slotFadeIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes slotSlideIn { from { transform: translateX(100%); } to { transform: translateX(0); } }

/* --- Drawer Info Grid --- */
.slot-info-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}
.slot-info-item {
  padding: 10px 14px;
  border-radius: 8px;
  background: #f8fafc;
  border: 1px solid #f1f5f9;
}
:is(.dark .slot-info-item) {
  background: #0f172a;
  border-color: rgba(255, 255, 255, 0.06);
}

/* --- Ergonomic Zone Strips --- */
.slot-ergo-strip {
  height: 28px;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 600;
  margin-bottom: 4px;
}
.slot-ergo-floor { background: #fee2e2; color: #991b1b; }
.slot-ergo-low { background: #fed7aa; color: #9a3412; }
.slot-ergo-golden { background: #dcfce7; color: #166534; }
.slot-ergo-high { background: #fef08a; color: #854d0e; }
.slot-ergo-top { background: #fee2e2; color: #991b1b; }
:is(.dark .slot-ergo-floor) { background: rgba(239,68,68,0.15); color: #fca5a5; }
:is(.dark .slot-ergo-low) { background: rgba(249,115,22,0.15); color: #fdba74; }
:is(.dark .slot-ergo-golden) { background: rgba(34,197,94,0.15); color: #86efac; }
:is(.dark .slot-ergo-high) { background: rgba(234,179,8,0.15); color: #fde047; }
:is(.dark .slot-ergo-top) { background: rgba(239,68,68,0.15); color: #fca5a5; }

/* --- Staggered Slide-Up Animations (12 levels) --- */
.slot-anim-1 { animation: slotSlideUp 0.4s ease 0.05s both; }
.slot-anim-2 { animation: slotSlideUp 0.4s ease 0.1s both; }
.slot-anim-3 { animation: slotSlideUp 0.4s ease 0.15s both; }
.slot-anim-4 { animation: slotSlideUp 0.4s ease 0.2s both; }
.slot-anim-5 { animation: slotSlideUp 0.4s ease 0.25s both; }
.slot-anim-6 { animation: slotSlideUp 0.4s ease 0.3s both; }
.slot-anim-7 { animation: slotSlideUp 0.4s ease 0.35s both; }
.slot-anim-8 { animation: slotSlideUp 0.4s ease 0.4s both; }
.slot-anim-9 { animation: slotSlideUp 0.4s ease 0.45s both; }
.slot-anim-10 { animation: slotSlideUp 0.4s ease 0.5s both; }
.slot-anim-11 { animation: slotSlideUp 0.4s ease 0.55s both; }
.slot-anim-12 { animation: slotSlideUp 0.4s ease 0.6s both; }
@keyframes slotSlideUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

/* --- Responsive Breakpoints --- */
@media (max-width: 1024px) {
  .slot-kpi-grid-6 { grid-template-columns: repeat(3, 1fr) !important; }
  .slot-chart-grid-2 { grid-template-columns: 1fr !important; }
  .slot-drawer-panel { width: 420px; }
  .slot-bin-grid { grid-template-columns: repeat(auto-fill, minmax(60px, 1fr)); }
}
@media (max-width: 768px) {
  .slot-kpi-grid-6 { grid-template-columns: repeat(2, 1fr) !important; }
  .slot-drawer-panel { width: 100%; }
  .slot-info-grid { grid-template-columns: 1fr; }
  .slot-filter-bar { flex-direction: column; }
}
/* ═══════════════════════════════════════════════════════════════════════════
   R128: Wave Planning & Picking Management
   Theme: Amber (#f59e0b) + Indigo (#6366f1) + Emerald (#10b981)
   Prefix: wave-
   ═══════════════════════════════════════════════════════════════════════════ */

/* ── Container & Header ───────────────────────────────────────────────── */
.wave-container {
  padding: 0 0 2rem 0;
}

.wave-header {
  background: linear-gradient(135deg, #fffbeb 0%, #eef2ff 50%, #ecfdf5 100%);
  border-bottom: 3px solid transparent;
  border-image: linear-gradient(90deg, #f59e0b, #6366f1, #10b981, #f59e0b) 1;
  background-size: 200% 200%;
