.dark .wave-hb-completed { background: rgba(16,185,129,0.1); color: #34d399; border-color: rgba(16,185,129,0.2); }
.wave-hb-pending { background: rgba(107,114,128,0.15); color: #4b5563; border: 1px solid rgba(107,114,128,0.3); }
.dark .wave-hb-pending { background: rgba(107,114,128,0.1); color: #9ca3af; border-color: rgba(107,114,128,0.2); }
.wave-hb-rate { background: rgba(245,158,11,0.15); color: #d97706; border: 1px solid rgba(245,158,11,0.3); }
.dark .wave-hb-rate { background: rgba(245,158,11,0.1); color: #fbbf24; border-color: rgba(245,158,11,0.2); }
