.bcl-badge-scan-dup { background: rgba(245,158,11,0.15); color: #d97706; border: 1px solid rgba(245,158,11,0.25); }
.bcl-badge-scan-damaged { background: rgba(239,68,68,0.15); color: #dc2626; border: 1px solid rgba(239,68,68,0.3); }

/* Grade badges */
.bcl-badge-grade { font-weight: 700; font-size: 0.7rem; min-width: 1.5rem; text-align: center; }
.bcl-badge-grade-a { background: rgba(16,185,129,0.15); color: #059669; border: 1px solid rgba(16,185,129,0.3); }
.bcl-badge-grade-b { background: rgba(6,182,212,0.15); color: #0891b2; border: 1px solid rgba(6,182,212,0.25); }
.bcl-badge-grade-c { background: rgba(245,158,11,0.15); color: #d97706; border: 1px solid rgba(245,158,11,0.25); }
.bcl-badge-grade-d { background: rgba(249,115,22,0.15); color: #ea580c; border: 1px solid rgba(249,115,22,0.25); }
.bcl-badge-grade-f { background: rgba(239,68,68,0.2); color: #dc2626; border: 2px solid rgba(239,68,68,0.4); }

/* Printer status */
