.bcl-badge-printer-maint { background: rgba(245,158,11,0.15); color: #d97706; border: 1px solid rgba(245,158,11,0.3); animation: bcl-pulse-amber 2s ease-in-out infinite; }
.bcl-badge-printer-offline { background: rgba(239,68,68,0.15); color: #dc2626; border: 1px solid rgba(239,68,68,0.3); }

/* Table */
.bcl-table-header th { font-size: 0.7rem; text-transform: uppercase; letter-spacing: 0.04em; font-weight: 600; color: #6b7280; padding: 0.6rem 0.75rem; white-space: nowrap; }
.dark .bcl-table-header th { color: #9ca3af; }
.bcl-table-row td { padding: 0.55rem 0.75rem; border-bottom: 1px solid rgba(0,0,0,0.04); vertical-align: middle; }
.dark .bcl-table-row td { border-bottom-color: rgba(255,255,255,0.04); }
.bcl-table-row:hover { background: rgba(124,58,237,0.03); }
.bcl-table-row-alt { background: rgba(249,250,251,0.5); }
.dark .bcl-table-row-alt { background: rgba(255,255,255,0.01); }
.bcl-th, .bcl-td { white-space: nowrap; }

.bcl-mini-bar { width: 3rem; height: 0.35rem; background: #e5e7eb; border-radius: 9999px; overflow: hidden; flex-shrink: 0; }
.dark .bcl-mini-bar { background: rgba(255,255,255,0.1); }
.bcl-mini-bar-fill { height: 100%; border-radius: 9999px; transition: width 0.4s ease; }
.bcl-bar-purple { background: linear-gradient(90deg, #7c3aed, #a78bfa); }
.bcl-bar-cyan { background: linear-gradient(90deg, #06b6d4, #22d3ee); }
.bcl-bar-amber { background: linear-gradient(90deg, #f59e0b, #fbbf24); }
.bcl-bar-red { background: linear-gradient(90deg, #ef4444, #f87171); }

/* Label Preview (Drawer) */
.bcl-label-preview { margin-bottom: 1rem; }
.bcl-label-preview-box {
