.pa-strat-cross-dock { background: rgba(236, 72, 153, 0.12); color: #db2777; border: 1px solid rgba(236, 72, 153, 0.25); padding: 2px 8px; border-radius: 6px; font-size: 0.65rem; font-weight: 600; }

:is(.dark .pa-strat-zone-based) { background: rgba(99, 102, 241, 0.18); }
:is(.dark .pa-strat-velocity-based) { background: rgba(16, 185, 129, 0.18); }
:is(.dark .pa-strat-abc-classified) { background: rgba(245, 158, 11, 0.18); }
:is(.dark .pa-strat-random-assignment) { background: rgba(148, 163, 184, 0.18); }
:is(.dark .pa-strat-bulk-storage) { background: rgba(139, 92, 246, 0.18); }
:is(.dark .pa-strat-cross-dock) { background: rgba(236, 72, 153, 0.18); }

