/* ── Zone Type Badges ────────────────────────────────────────────────────── */
.pa-zone-picking { background: rgba(99, 102, 241, 0.12); color: #4f46e5; border: 1px solid rgba(99, 102, 241, 0.25); padding: 2px 8px; border-radius: 6px; font-size: 0.65rem; font-weight: 600; }
.pa-zone-bulk { background: rgba(139, 92, 246, 0.12); color: #7c3aed; border: 1px solid rgba(139, 92, 246, 0.25); padding: 2px 8px; border-radius: 6px; font-size: 0.65rem; font-weight: 600; }
.pa-zone-cold { background: rgba(6, 182, 212, 0.12); color: #0891b2; border: 1px solid rgba(6, 182, 212, 0.25); padding: 2px 8px; border-radius: 6px; font-size: 0.65rem; font-weight: 600; }
.pa-zone-high-value { background: rgba(245, 158, 11, 0.12); color: #d97706; border: 1px solid rgba(245, 158, 11, 0.25); padding: 2px 8px; border-radius: 6px; font-size: 0.65rem; font-weight: 600; }
.pa-zone-hazmat { background: rgba(239, 68, 68, 0.12); color: #dc2626; border: 1px solid rgba(239, 68, 68, 0.25); padding: 2px 8px; border-radius: 6px; font-size: 0.65rem; font-weight: 600; }
.pa-zone-returns { background: rgba(236, 72, 153, 0.12); color: #db2777; border: 1px solid rgba(236, 72, 153, 0.25); padding: 2px 8px; border-radius: 6px; font-size: 0.65rem; font-weight: 600; }

:is(.dark .pa-zone-picking) { background: rgba(99, 102, 241, 0.18); }
:is(.dark .pa-zone-bulk) { background: rgba(139, 92, 246, 0.18); }
:is(.dark .pa-zone-cold) { background: rgba(6, 182, 212, 0.18); }
:is(.dark .pa-zone-high-value) { background: rgba(245, 158, 11, 0.18); }
:is(.dark .pa-zone-hazmat) { background: rgba(239, 68, 68, 0.18); }
:is(.dark .pa-zone-returns) { background: rgba(236, 72, 153, 0.18); }

/* ── Equipment Badges ────────────────────────────────────────────────────── */
.pa-equip-badge {
  background: rgba(99, 102, 241, 0.1);
  color: #4f46e5;
  border: 1px solid rgba(99, 102, 241, 0.2);
  padding: 2px 8px;
  border-radius: 6px;
  font-size: 0.6rem;
  font-weight: 500;
  white-space: nowrap;
}
:is(.dark .pa-equip-badge) { background: rgba(99, 102, 241, 0.15); color: #818cf8; border-color: rgba(99, 102, 241, 0.3); }

/* ── Certification Badges ─────────────────────────────────────────────────── */
.pa-cert-l1 { background: rgba(16, 185, 129, 0.15); color: #059669; border: 1px solid rgba(16, 185, 129, 0.3); padding: 1px 6px; border-radius: 4px; font-size: 0.6rem; font-weight: 700; letter-spacing: 0.05em; }
.pa-cert-l2 { background: rgba(99, 102, 241, 0.15); color: #4f46e5; border: 1px solid rgba(99, 102, 241, 0.3); padding: 1px 6px; border-radius: 4px; font-size: 0.6rem; font-weight: 700; letter-spacing: 0.05em; }
.pa-cert-l3 { background: rgba(245, 158, 11, 0.15); color: #d97706; border: 1px solid rgba(245, 158, 11, 0.3); padding: 1px 6px; border-radius: 4px; font-size: 0.6rem; font-weight: 700; letter-spacing: 0.05em; }

:is(.dark .pa-cert-l1) { background: rgba(16, 185, 129, 0.2); }
:is(.dark .pa-cert-l2) { background: rgba(99, 102, 241, 0.2); }
:is(.dark .pa-cert-l3) { background: rgba(245, 158, 11, 0.2); }

/* ── Rank Badges ─────────────────────────────────────────────────────────── */
.pa-rank-gold { color: #d97706; }
.pa-rank-silver { color: #6b7280; }
.pa-rank-bronze { color: #b45309; }

/* ── Star Rating ─────────────────────────────────────────────────────────── */
.pa-star-filled { color: #f59e0b; }
.pa-star-empty { color: #d1d5db; }
:is(.dark .pa-star-empty) { color: #4b5563; }

/* ── Item Flow Visualization ────────────────────────────────────────────── */
.pa-item-flow {
  display: flex;
  align-items: center;
  gap: 0;
  padding: 12px 16px;
  background: #f8fafc;
  border-radius: 10px;
  border: 1px solid #e2e8f0;
}
.pa-flow-dot {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 8px 12px;
  border-radius: 8px;
  min-width: 72px;
}
.pa-flow-dock { background: rgba(99, 102, 241, 0.1); color: #4f46e5; }
.pa-flow-staging { background: rgba(245, 158, 11, 0.1); color: #d97706; }
.pa-flow-bin { background: rgba(16, 185, 129, 0.1); color: #059669; }
.pa-flow-arrow { display: flex; align-items: center; color: #cbd5e1; margin: 0 4px; }
:is(.dark .pa-item-flow) { background: #1e293b; border-color: #334155; }
:is(.dark .pa-flow-dock) { background: rgba(99, 102, 241, 0.15); }
:is(.dark .pa-flow-staging) { background: rgba(245, 158, 11, 0.15); }
:is(.dark .pa-flow-bin) { background: rgba(16, 185, 129, 0.15); }

/* ── Compliance Box ──────────────────────────────────────────────────────── */
.pa-compliance-box {
  padding: 0.75rem 1rem;
  background: rgba(16, 185, 129, 0.06);
  border: 1px solid rgba(16, 185, 129, 0.2);
  border-radius: 10px;
}
.pa-compliance-box h4 {
  font-size: 0.8rem;
  font-weight: 600;
  color: #059669;
  margin-bottom: 0.5rem;
}
.pa-compliance-check {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.75rem;
  color: #15803d;
}
.pa-compliance-check svg { color: #10b981; flex-shrink: 0; }
:is(.dark .pa-compliance-box) { background: rgba(16, 185, 129, 0.08); border-color: rgba(16, 185, 129, 0.25); }
:is(.dark .pa-compliance-box h4) { color: #34d399; }
:is(.dark .pa-compliance-check) { color: #4ade80; }

/* ── Timeline Track ───────────────────────────────────────────────────────── */
.pa-timeline { display: flex; flex-direction: column; gap: 0.75rem; }
.pa-timeline-track { display: flex; align-items: flex-start; justify-content: space-between; position: relative; padding: 8px 0; }
.pa-timeline-step { display: flex; flex-direction: column; align-items: center; gap: 4px; position: relative; z-index: 1; }
.pa-timeline-dot {
  width: 16px; height: 16px;
  border-radius: 50%;
  background: #e2e8f0;
  border: 2px solid #cbd5e1;
  transition: all 0.3s;
}
.pa-dot-done { background: #10b981; border-color: #059669; box-shadow: 0 0 6px rgba(16, 185, 129, 0.4); }
.pa-dot-current { background: #6366f1; border-color: #4f46e5; box-shadow: 0 0 8px rgba(99, 102, 241, 0.5); animation: pa-pulse-dot 1.5s infinite; }
.pa-dot-exception { background: #ef4444; border-color: #dc2626; box-shadow: 0 0 6px rgba(239, 68, 68, 0.4); }
@keyframes pa-pulse-dot {
  0%, 100% { box-shadow: 0 0 4px rgba(99, 102, 241, 0.4); }
  50% { box-shadow: 0 0 14px rgba(99, 102, 241, 0.7); }
}
.pa-timeline-label { font-size: 0.65rem; color: #94a3b8; text-align: center; max-width: 60px; }
.pa-timeline-date { font-size: 0.6rem; color: #cbd5e1; }
.pa-label-done { color: #059669; font-weight: 600; }
.pa-label-current { color: #4f46e5; font-weight: 700; }
.pa-label-exception { color: #dc2626; font-weight: 600; }
.pa-timeline-connector {
  flex: 1; height: 2px;
  background: #e2e8f0;
  position: absolute;
  top: 16px; left: 50%; right: -50%;
  z-index: 0;
}
.pa-connector-done { background: #10b981; }
.pa-connector-current { background: linear-gradient(90deg, #10b981, #6366f1); }
:is(.dark .pa-timeline-dot) { background: #334155; border-color: #475569; }
:is(.dark .pa-timeline-label) { color: #64748b; }
:is(.dark .pa-timeline-date) { color: #475569; }
:is(.dark .pa-timeline-connector) { background: #334155; }

/* ── Drawer ───────────────────────────────────────────────────────────────── */
.pa-drawer-overlay {
  position: fixed; inset: 0;
  background: rgba(0, 0, 0, 0.4);
  backdrop-filter: blur(4px);
  z-index: 50;
  animation: pa-drawer-fade 0.2s ease-out;
}
.pa-drawer-panel {
  position: fixed; top: 0; right: 0;
  width: 440px; max-width: 100%; height: 100vh;
  background: #fff;
  border-left: 3px solid transparent;
  border-image: linear-gradient(to bottom, #6366f1, #10b981, #f59e0b) 1;
  box-shadow: -8px 0 30px rgba(0, 0, 0, 0.15);
  overflow-y: auto;
  padding: 1.25rem;
  animation: pa-drawer-slide 0.25s ease-out;
  z-index: 51;
}
.pa-drawer-close {
  position: absolute; top: 12px; right: 12px;
  width: 28px; height: 28px;
  border-radius: 6px;
  display: flex; align-items: center; justify-content: center;
  background: #f1f5f9;
  color: #64748b;
  border: none;
  cursor: pointer;
  transition: background 0.15s;
}
.pa-drawer-close:hover { background: #e2e8f0; }
.pa-drawer-content { padding-right: 1rem; }
.pa-drawer-status {
  display: flex; align-items: center; gap: 8px;
  padding: 10px 14px;
  border-radius: 10px;
  margin-bottom: 1rem;
  font-weight: 600;
}
.pa-drawer-done { background: rgba(16, 185, 129, 0.1); color: #059669; border: 1px solid rgba(16, 185, 129, 0.2); }
.pa-drawer-active { background: rgba(99, 102, 241, 0.1); color: #4f46e5; border: 1px solid rgba(99, 102, 241, 0.2); }
.pa-drawer-assigned { background: rgba(245, 158, 11, 0.1); color: #d97706; border: 1px solid rgba(245, 158, 11, 0.2); }
.pa-drawer-default { background: rgba(148, 163, 184, 0.1); color: #64748b; border: 1px solid rgba(148, 163, 184, 0.2); }
.pa-drawer-exception { background: rgba(239, 68, 68, 0.1); color: #dc2626; border: 1px solid rgba(239, 68, 68, 0.2); }
.pa-drawer-title { font-size: 1.1rem; font-weight: 700; color: #1e293b; margin-bottom: 0.25rem; }
.pa-drawer-subtitle { font-size: 0.8rem; color: #64748b; margin-bottom: 1rem; }
.pa-drawer-footer {
  display: flex; flex-wrap: wrap; gap: 8px;
  padding-top: 0.75rem;
  border-top: 1px solid #e2e8f0;
  margin-top: 0.25rem;
}
.pa-footer-item { flex: 1; min-width: 80px; display: flex; flex-direction: column; gap: 2px; }

@keyframes pa-drawer-fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes pa-drawer-slide { from { transform: translateX(100%); } to { transform: translateX(0); } }

:is(.dark .pa-drawer-panel) { background: #0f172a; box-shadow: -8px 0 30px rgba(0, 0, 0, 0.4); }
:is(.dark .pa-drawer-close) { background: #1e293b; color: #94a3b8; }
:is(.dark .pa-drawer-close:hover) { background: #334155; }
:is(.dark .pa-drawer-done) { background: rgba(16, 185, 129, 0.12); }
:is(.dark .pa-drawer-active) { background: rgba(99, 102, 241, 0.12); }
:is(.dark .pa-drawer-assigned) { background: rgba(245, 158, 11, 0.12); }
:is(.dark .pa-drawer-default) { background: rgba(148, 163, 184, 0.12); }
:is(.dark .pa-drawer-exception) { background: rgba(239, 68, 68, 0.12); }
:is(.dark .pa-drawer-title) { color: #f1f5f9; }
:is(.dark .pa-drawer-subtitle) { color: #94a3b8; }
:is(.dark .pa-drawer-footer) { border-top-color: #334155; }

/* ── Info Grid (for drawer) ───────────────────────────────────────────────── */
.pa-info-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.pa-info-item { display: flex; flex-direction: column; gap: 2px; padding: 8px 10px; background: #f8fafc; border-radius: 8px; }
.pa-info-label { font-size: 0.65rem; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.03em; }
.pa-info-value { font-size: 0.8rem; color: #1e293b; font-weight: 500; }
:is(.dark .pa-info-item) { background: #1e293b; }
:is(.dark .pa-info-value) { color: #e2e8f0; }

/* ── Assignment Box ────────────────────────────────────────────────────────── */
.pa-assign-box {
  padding: 0.75rem 1rem;
  background: rgba(99, 102, 241, 0.04);
  border: 1px solid rgba(99, 102, 241, 0.15);
  border-radius: 10px;
}
.pa-assign-box h4 { font-size: 0.8rem; font-weight: 600; color: #4f46e5; margin-bottom: 0.5rem; }
:is(.dark .pa-assign-box) { background: rgba(99, 102, 241, 0.06); border-color: rgba(99, 102, 241, 0.2); }
:is(.dark .pa-assign-box h4) { color: #818cf8; }

/* ── Table Row Highlighting ──────────────────────────────────────────────── */
.pa-row-in-progress { border-left: 3px solid #6366f1; }
.pa-row-exception { border-left: 3px solid #ef4444; }
.pa-row-assigned { border-left: 3px solid #f59e0b; }

/* ── Progress Bars ────────────────────────────────────────────────────────── */
.pa-progress-bar {
  width: 60px; height: 6px;
  background: #e2e8f0;
  border-radius: 3px;
  overflow: hidden;
}
.pa-progress-fill-indigo { height: 100%; background: linear-gradient(90deg, #6366f1, #818cf8); border-radius: 3px; }
.pa-progress-fill-emerald { height: 100%; background: linear-gradient(90deg, #10b981, #34d399); border-radius: 3px; }
.pa-progress-fill-amber { height: 100%; background: linear-gradient(90deg, #f59e0b, #fbbf24); border-radius: 3px; }
.pa-progress-fill-red { height: 100%; background: linear-gradient(90deg, #ef4444, #f87171); border-radius: 3px; }
.pa-progress-fill-violet { height: 100%; background: linear-gradient(90deg, #8b5cf6, #a78bfa); border-radius: 3px; }

:is(.dark .pa-progress-bar) { background: #334155; }

/* ── Action Badge (Rebalance/Consolidate/Expand/Relocate/Merge) ────────────── */
.pa-action-rebalance { background: rgba(99, 102, 241, 0.12); color: #4f46e5; border: 1px solid rgba(99, 102, 241, 0.25); padding: 2px 8px; border-radius: 6px; font-size: 0.65rem; font-weight: 600; }
.pa-action-consolidate { background: rgba(16, 185, 129, 0.12); color: #059669; border: 1px solid rgba(16, 185, 129, 0.25); padding: 2px 8px; border-radius: 6px; font-size: 0.65rem; font-weight: 600; }
.pa-action-expand { background: rgba(245, 158, 11, 0.12); color: #d97706; border: 1px solid rgba(245, 158, 11, 0.25); padding: 2px 8px; border-radius: 6px; font-size: 0.65rem; font-weight: 600; }
.pa-action-relocate { background: rgba(139, 92, 246, 0.12); color: #7c3aed; border: 1px solid rgba(139, 92, 246, 0.25); padding: 2px 8px; border-radius: 6px; font-size: 0.65rem; font-weight: 600; }
.pa-action-merge { background: rgba(236, 72, 153, 0.12); color: #db2777; border: 1px solid rgba(236, 72, 153, 0.25); padding: 2px 8px; border-radius: 6px; font-size: 0.65rem; font-weight: 600; }

:is(.dark .pa-action-rebalance) { background: rgba(99, 102, 241, 0.18); }
:is(.dark .pa-action-consolidate) { background: rgba(16, 185, 129, 0.18); }
:is(.dark .pa-action-expand) { background: rgba(245, 158, 11, 0.18); }
:is(.dark .pa-action-relocate) { background: rgba(139, 92, 246, 0.18); }
:is(.dark .pa-action-merge) { background: rgba(236, 72, 153, 0.18); }

/* ── Staggered Fade-in Animations ─────────────────────────────────────────── */
.pa-container > .pa-header { animation: pa-stagger-1 0.4s ease-out both; }
.pa-container > .pa-tabs-wrapper { animation: pa-stagger-2 0.4s ease-out 0.1s both; }
@keyframes pa-stagger-1 {
  from { opacity: 0; transform: translateY(-12px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes pa-stagger-2 {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ── Mini Bar (for accuracy bars in tables) ───────────────────────────────── */
.pa-mini-bar {
  width: 50px; height: 5px;
  background: #e2e8f0;
  border-radius: 3px;
  overflow: hidden;
  display: inline-block;
  vertical-align: middle;
}
.pa-mini-bar-fill {
  height: 100%;
  border-radius: 3px;
}
:is(.dark .pa-mini-bar) { background: #334155; }

/* ── Responsive ───────────────────────────────────────────────────────────── */
@media (max-width: 768px) {
  .pa-info-grid { grid-template-columns: 1fr; }
  .pa-item-flow { flex-wrap: wrap; justify-content: center; }
  .pa-flow-arrow { margin: 4px 8px; }
  .pa-drawer-panel { width: 100%; max-width: 100%; }
  .pa-timeline-track { flex-wrap: wrap; gap: 8px; }
  .pa-timeline-connector { display: none; }
}
@media (max-width: 640px) {
  .pa-kpi-card { padding: 0.75rem; }
}

/* ── Section Heading ────────────────────────────────────────────────────── */
.pa-section-heading { font-size: 0.8rem; font-weight: 600; color: #475569; margin-bottom: 0.5rem; }
:is(.dark .pa-section-heading) { color: #94a3b8; }

/* ── Filter Bar ───────────────────────────────────────────────────────────── */
.pa-filter-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: 0.75rem;
  background: #f8fafc;
  border-radius: 10px;
  border: 1px solid #e2e8f0;
  margin-bottom: 0.75rem;
}
.pa-filter-bar input,
.pa-filter-bar select {
  font-size: 0.8rem;
  padding: 0.4rem 0.6rem;
  border-radius: 8px;
  border: 1px solid #e2e8f0;
  background: #fff;
  color: #1e293b;
  outline: none;
  transition: border-color 0.15s;
}
.pa-filter-bar input:focus,
.pa-filter-bar select:focus {
  border-color: #6366f1;
  box-shadow: 0 0 0 2px rgba(99, 102, 241, 0.15);
}
:is(.dark .pa-filter-bar) { background: #1e293b; border-color: #334155; }
:is(.dark .pa-filter-bar input),
:is(.dark .pa-filter-bar select) { background: #0f172a; color: #e2e8f0; border-color: #475569; }
:is(.dark .pa-filter-bar input:focus),
:is(.dark .pa-filter-bar select:focus) { border-color: #818cf8; box-shadow: 0 0 0 2px rgba(99, 102, 241, 0.2); }

/* ── Utilization Bar (wide, for zone utilization) ───────────────────────── */
.pa-util-bar {
  width: 100px; height: 8px;
  background: #e2e8f0;
  border-radius: 4px;
  overflow: hidden;
  display: inline-block;
  vertical-align: middle;
}
.pa-util-bar-fill {
  height: 100%;
  border-radius: 4px;
  transition: width 0.5s ease-out;
}
.pa-util-high { background: linear-gradient(90deg, #10b981, #34d399); }
.pa-util-medium { background: linear-gradient(90deg, #f59e0b, #fbbf24); }
.pa-util-low { background: linear-gradient(90deg, #6366f1, #818cf8); }
.pa-util-over { background: linear-gradient(90deg, #ef4444, #f87171); }
:is(.dark .pa-util-bar) { background: #334155; }

/* ── Table Container (scrollable) ─────────────────────────────────────────── */
.pa-table-wrap {
  overflow-x: auto;
  border-radius: 10px;
  border: 1px solid #e2e8f0;
}
:is(.dark .pa-table-wrap) { border-color: #334155; }

/* ── Action Button (small) ────────────────────────────────────────────────── */
.pa-action-btn {
  width: 28px; height: 28px;
  border-radius: 6px;
  display: inline-flex; align-items: center; justify-content: center;
  background: rgba(99, 102, 241, 0.08);
  color: #4f46e5;
  border: 1px solid rgba(99, 102, 241, 0.2);
  cursor: pointer;
  transition: all 0.15s;
}
.pa-action-btn:hover { background: rgba(99, 102, 241, 0.15); border-color: rgba(99, 102, 241, 0.35); }
:is(.dark .pa-action-btn) { background: rgba(99, 102, 241, 0.12); color: #818cf8; border-color: rgba(99, 102, 241, 0.25); }

/* ── Stat Chip (drawer bottom stats) ─────────────────────────────────────── */
.pa-stat-chip {
  display: flex; flex-direction: column; gap: 2px;
  padding: 6px 10px; background: #f8fafc; border-radius: 6px;
}
:is(.dark .pa-stat-chip) { background: #1e293b; }

/* ── Temperature Badge ───────────────────────────────────────────────────── */
.pa-temp-badge {
  background: rgba(6, 182, 212, 0.1);
  color: #0891b2;
  border: 1px solid rgba(6, 182, 212, 0.2);
  padding: 2px 8px;
  border-radius: 6px;
  font-size: 0.65rem;
  font-weight: 600;
}
:is(.dark .pa-temp-badge) { background: rgba(6, 182, 212, 0.15); color: #22d3ee; }
/* ════════════════════════════════════════════════════════════════════════════
   R134 Loading & Dispatch Management – ld-* CSS Module
   Theme: Slate (#475569) + Sky (#0ea5e9) + Rose (#f43f5e)
   ════════════════════════════════════════════════════════════════════════════ */

/* ── Animated Gradient Top Border ─────────────────────────────────────────── */
.ld-top-border {
  position: relative;
  overflow: hidden;
}
.ld-top-border::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: linear-gradient(90deg, #475569, #0ea5e9, #f43f5e, #0ea5e9, #475569);
  background-size: 200% 100%;
  animation: ld-gradient-slide 6s linear infinite;
}
@keyframes ld-gradient-slide {
  0% { background-position: 0% 50%; }
  100% { background-position: 200% 50%; }
}

/* ── KPI Cards ─────────────────────────────────────────────────────────────── */
.ld-kpi-card {
  border-radius: 12px;
  padding: 16px 20px;
  position: relative;
  overflow: hidden;
  transition: transform 0.2s, box-shadow 0.2s;
}
.ld-kpi-card:hover { transform: translateY(-2px); box-shadow: 0 8px 24px rgba(0,0,0,0.1); }
.ld-kpi-card::after {
  content: "";
  position: absolute;
  top: -20px; right: -20px;
  width: 80px; height: 80px;
  border-radius: 50%;
  background: rgba(255,255,255,0.1);
}
.ld-kpi-slate  { background: linear-gradient(135deg, #475569, #64748b); color: #fff; }
.ld-kpi-sky    { background: linear-gradient(135deg, #0284c7, #0ea5e9); color: #fff; }
.ld-kpi-rose   { background: linear-gradient(135deg, #e11d48, #f43f5e); color: #fff; }
.ld-kpi-emerald{ background: linear-gradient(135deg, #059669, #10b981); color: #fff; }
.ld-kpi-amber  { background: linear-gradient(135deg, #d97706, #f59e0b); color: #fff; }
.ld-kpi-violet { background: linear-gradient(135deg, #7c3aed, #8b5cf6); color: #fff; }
:is(.dark .ld-kpi-slate)   { background: linear-gradient(135deg, #334155, #475569); }
:is(.dark .ld-kpi-sky)     { background: linear-gradient(135deg, #0369a1, #0284c7); }
:is(.dark .ld-kpi-rose)    { background: linear-gradient(135deg, #be123c, #e11d48); }
:is(.dark .ld-kpi-emerald) { background: linear-gradient(135deg, #047857, #059669); }
:is(.dark .ld-kpi-amber)   { background: linear-gradient(135deg, #b45309, #d97706); }
:is(.dark .ld-kpi-violet)  { background: linear-gradient(135deg, #6d28d9, #7c3aed); }
.ld-kpi-value { font-size: 1.75rem; font-weight: 700; line-height: 1.2; }
.ld-kpi-label { font-size: 0.75rem; opacity: 0.85; margin-top: 2px; }
.ld-kpi-icon  { width: 36px; height: 36px; border-radius: 8px; background: rgba(255,255,255,0.2); display: flex; align-items: center; justify-content: center; }

/* ── Status Badges ─────────────────────────────────────────────────────────── */
.ld-badge { padding: 2px 10px; border-radius: 9999px; font-size: 0.7rem; font-weight: 600; display: inline-flex; align-items: center; gap: 4px; white-space: nowrap; }
.ld-badge-scheduled    { background: rgba(148,163,184,0.15); color: #64748b; border: 1px solid rgba(148,163,184,0.3); }
.ld-badge-staging      { background: rgba(245,158,11,0.12); color: #d97706; border: 1px solid rgba(245,158,11,0.25); }
.ld-badge-loading      { background: rgba(14,165,233,0.12); color: #0284c7; border: 1px solid rgba(14,165,233,0.25); animation: ld-pulse-sky 2s ease-in-out infinite; }
.ld-badge-quality-check{ background: rgba(6,182,212,0.12); color: #0891b2; border: 1px solid rgba(6,182,212,0.25); animation: ld-pulse-cyan 2s ease-in-out infinite; }
.ld-badge-sealed       { background: rgba(16,185,129,0.12); color: #059669; border: 1px solid rgba(16,185,129,0.25); }
.ld-badge-dispatched   { background: rgba(14,165,233,0.12); color: #0284c7; border: 1px solid rgba(14,165,233,0.25); }
.ld-badge-in-transit   { background: rgba(99,102,241,0.12); color: #6366f1; border: 1px solid rgba(99,102,241,0.25); animation: ld-pulse-indigo 2s ease-in-out infinite; }
.ld-badge-delivered    { background: rgba(34,197,94,0.12); color: #16a34a; border: 1px solid rgba(34,197,94,0.25); }
:is(.dark .ld-badge-scheduled)    { background: rgba(148,163,184,0.2); color: #94a3b8; }
:is(.dark .ld-badge-staging)      { background: rgba(245,158,11,0.18); color: #fbbf24; }
:is(.dark .ld-badge-loading)      { background: rgba(14,165,233,0.18); color: #38bdf8; }
:is(.dark .ld-badge-quality-check){ background: rgba(6,182,212,0.18); color: #22d3ee; }
:is(.dark .ld-badge-sealed)       { background: rgba(16,185,129,0.18); color: #34d399; }
:is(.dark .ld-badge-dispatched)   { background: rgba(14,165,233,0.18); color: #38bdf8; }
:is(.dark .ld-badge-in-transit)   { background: rgba(99,102,241,0.18); color: #818cf8; }
:is(.dark .ld-badge-delivered)    { background: rgba(34,197,94,0.18); color: #4ade80; }

@keyframes ld-pulse-sky   { 0%,100% { box-shadow: 0 0 0 0 rgba(14,165,233,0.3); } 50% { box-shadow: 0 0 0 6px rgba(14,165,233,0); } }
@keyframes ld-pulse-cyan  { 0%,100% { box-shadow: 0 0 0 0 rgba(6,182,212,0.3); } 50% { box-shadow: 0 0 0 6px rgba(6,182,212,0); } }
@keyframes ld-pulse-indigo { 0%,100% { box-shadow: 0 0 0 0 rgba(99,102,241,0.3); } 50% { box-shadow: 0 0 0 6px rgba(99,102,241,0); } }

/* ── Vehicle Type Badges ──────────────────────────────────────────────────── */
.ld-vt-badge { padding: 2px 8px; border-radius: 6px; font-size: 0.65rem; font-weight: 600; white-space: nowrap; }
.ld-vt-0 { background: rgba(14,165,233,0.1); color: #0284c7; border: 1px solid rgba(14,165,233,0.2); }
.ld-vt-1 { background: rgba(99,102,241,0.1); color: #6366f1; border: 1px solid rgba(99,102,241,0.2); }
.ld-vt-2 { background: rgba(245,158,11,0.1); color: #d97706; border: 1px solid rgba(245,158,11,0.2); }
.ld-vt-3 { background: rgba(244,63,94,0.1); color: #e11d48; border: 1px solid rgba(244,63,94,0.2); }
.ld-vt-4 { background: rgba(6,182,212,0.1); color: #0891b2; border: 1px solid rgba(6,182,212,0.2); }
.ld-vt-5 { background: rgba(139,92,246,0.1); color: #7c3aed; border: 1px solid rgba(139,92,246,0.2); }
.ld-vt-6 { background: rgba(16,185,129,0.1); color: #059669; border: 1px solid rgba(16,185,129,0.2); }
.ld-vt-7 { background: rgba(236,72,153,0.1); color: #db2777; border: 1px solid rgba(236,72,153,0.2); }
:is(.dark .ld-vt-0) { background: rgba(14,165,233,0.15); color: #38bdf8; }
:is(.dark .ld-vt-1) { background: rgba(99,102,241,0.15); color: #818cf8; }
:is(.dark .ld-vt-2) { background: rgba(245,158,11,0.15); color: #fbbf24; }
:is(.dark .ld-vt-3) { background: rgba(244,63,94,0.15); color: #fb7185; }
:is(.dark .ld-vt-4) { background: rgba(6,182,212,0.15); color: #22d3ee; }
:is(.dark .ld-vt-5) { background: rgba(139,92,246,0.15); color: #a78bfa; }
:is(.dark .ld-vt-6) { background: rgba(16,185,129,0.15); color: #34d399; }
:is(.dark .ld-vt-7) { background: rgba(236,72,153,0.15); color: #f472b6; }

/* ── Load Type Badges ──────────────────────────────────────────────────────── */
.ld-lt-badge { padding: 2px 8px; border-radius: 6px; font-size: 0.65rem; font-weight: 600; white-space: nowrap; }
.ld-lt-0 { background: rgba(14,165,233,0.1); color: #0284c7; border: 1px solid rgba(14,165,233,0.2); }
.ld-lt-1 { background: rgba(245,158,11,0.1); color: #d97706; border: 1px solid rgba(245,158,11,0.2); }
.ld-lt-2 { background: rgba(99,102,241,0.1); color: #6366f1; border: 1px solid rgba(99,102,241,0.2); }
.ld-lt-3 { background: rgba(244,63,94,0.1); color: #e11d48; border: 1px solid rgba(244,63,94,0.2); }
.ld-lt-4 { background: rgba(6,182,212,0.1); color: #0891b2; border: 1px solid rgba(6,182,212,0.2); }
.ld-lt-5 { background: rgba(139,92,246,0.1); color: #7c3aed; border: 1px solid rgba(139,92,246,0.2); }
:is(.dark .ld-lt-0) { background: rgba(14,165,233,0.15); color: #38bdf8; }
:is(.dark .ld-lt-1) { background: rgba(245,158,11,0.15); color: #fbbf24; }
:is(.dark .ld-lt-2) { background: rgba(99,102,241,0.15); color: #818cf8; }
:is(.dark .ld-lt-3) { background: rgba(244,63,94,0.15); color: #fb7185; }
:is(.dark .ld-lt-4) { background: rgba(6,182,212,0.15); color: #22d3ee; }
:is(.dark .ld-lt-5) { background: rgba(139,92,246,0.15); color: #a78bfa; }

/* ── Priority Badges ───────────────────────────────────────────────────────── */
.ld-pri-badge { padding: 2px 8px; border-radius: 6px; font-size: 0.65rem; font-weight: 700; white-space: nowrap; }
.ld-pri-critical { background: rgba(244,63,94,0.12); color: #e11d48; border: 1px solid rgba(244,63,94,0.25); }
.ld-pri-high     { background: rgba(245,158,11,0.12); color: #d97706; border: 1px solid rgba(245,158,11,0.25); }
.ld-pri-medium   { background: rgba(14,165,233,0.12); color: #0284c7; border: 1px solid rgba(14,165,233,0.25); }
.ld-pri-low      { background: rgba(148,163,184,0.12); color: #64748b; border: 1px solid rgba(148,163,184,0.25); }
:is(.dark .ld-pri-critical) { background: rgba(244,63,94,0.18); color: #fb7185; }
:is(.dark .ld-pri-high)     { background: rgba(245,158,11,0.18); color: #fbbf24; }
:is(.dark .ld-pri-medium)   { background: rgba(14,165,233,0.18); color: #38bdf8; }
:is(.dark .ld-pri-low)      { background: rgba(148,163,184,0.18); color: #94a3b8; }

/* ── Dock Status Indicators ────────────────────────────────────────────────── */
.ld-dock-occupied    { background: rgba(14,165,233,0.08); border: 2px solid #0ea5e9; border-radius: 12px; }
.ld-dock-available   { background: rgba(34,197,94,0.06); border: 2px solid #22c55e; border-radius: 12px; }
.ld-dock-maintenance { background: rgba(148,163,184,0.08); border: 2px solid #94a3b8; border-radius: 12px; }
:is(.dark .ld-dock-occupied)    { background: rgba(14,165,233,0.12); border-color: #38bdf8; }
:is(.dark .ld-dock-available)   { background: rgba(34,197,94,0.1); border-color: #4ade80; }
:is(.dark .ld-dock-maintenance) { background: rgba(148,163,184,0.12); border-color: #cbd5e1; }
.ld-dock-dot-occupied    { width: 10px; height: 10px; border-radius: 50%; background: #0ea5e9; box-shadow: 0 0 6px rgba(14,165,233,0.5); }
.ld-dock-dot-available   { width: 10px; height: 10px; border-radius: 50%; background: #22c55e; box-shadow: 0 0 6px rgba(34,197,94,0.5); }
.ld-dock-dot-maintenance { width: 10px; height: 10px; border-radius: 50%; background: #94a3b8; }

/* ── Driver Rating Stars ───────────────────────────────────────────────────── */
.ld-stars { display: inline-flex; gap: 1px; }
.ld-star { color: #f59e0b; font-size: 0.8rem; }
.ld-star-empty { color: #e2e8f0; font-size: 0.8rem; }
:is(.dark .ld-star-empty) { color: #334155; }

/* ── Route Flow Visualization ──────────────────────────────────────────────── */
.ld-route-flow { display: flex; align-items: center; gap: 0; padding: 16px 0; }
.ld-route-node { width: 40px; height: 40px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 0.7rem; font-weight: 700; color: #fff; flex-shrink: 0; position: relative; z-index: 1; }
.ld-route-node-0 { background: #0ea5e9; }
.ld-route-node-1 { background: #475569; }
.ld-route-node-2 { background: #f43f5e; }
.ld-route-node-3 { background: #10b981; }
.ld-route-arrow { flex: 1; height: 2px; background: #cbd5e1; position: relative; min-width: 24px; }
.ld-route-arrow::after { content: ""; position: absolute; right: -1px; top: -4px; border: 5px solid transparent; border-left-color: #cbd5e1; }
:is(.dark .ld-route-arrow) { background: #475569; }
:is(.dark .ld-route-arrow::after) { border-left-color: #475569; }
.ld-route-label { font-size: 0.6rem; color: #64748b; text-align: center; margin-top: 4px; }
:is(.dark .ld-route-label) { color: #94a3b8; }

/* ── Compliance Checklist Box ──────────────────────────────────────────────── */
.ld-compliance { background: rgba(34,197,94,0.06); border: 1px solid rgba(34,197,94,0.2); border-radius: 10px; padding: 14px 18px; }
:is(.dark .ld-compliance) { background: rgba(34,197,94,0.08); border-color: rgba(34,197,94,0.25); }
.ld-compliance-item { display: flex; align-items: center; gap: 8px; font-size: 0.8rem; color: #16a34a; }
.ld-compliance-check { width: 18px; height: 18px; border-radius: 50%; background: #22c55e; display: inline-flex; align-items: center; justify-content: center; color: #fff; font-size: 0.6rem; flex-shrink: 0; }
:is(.dark .ld-compliance-item) { color: #4ade80; }

/* ── Dispatch Timeline Track ───────────────────────────────────────────────── */
.ld-timeline { display: flex; align-items: flex-start; gap: 0; padding: 8px 0; }
.ld-timeline-step { display: flex; flex-direction: column; align-items: center; gap: 6px; flex: 1; position: relative; }
.ld-timeline-dot { width: 20px; height: 20px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 0.55rem; font-weight: 700; color: #fff; z-index: 1; flex-shrink: 0; }
.ld-timeline-dot-done    { background: #10b981; }
.ld-timeline-dot-current { background: #0ea5e9; animation: ld-pulse-sky 2s ease-in-out infinite; }
.ld-timeline-dot-pending { background: #cbd5e1; color: #64748b; }
:is(.dark .ld-timeline-dot-pending) { background: #334155; color: #94a3b8; }
.ld-timeline-label { font-size: 0.6rem; color: #475569; text-align: center; max-width: 70px; line-height: 1.2; }
:is(.dark .ld-timeline-label) { color: #94a3b8; }
.ld-timeline-time { font-size: 0.55rem; color: #94a3b8; }
.ld-timeline-line { position: absolute; top: 10px; left: calc(50% + 12px); right: calc(-50% + 12px); height: 2px; background: #e2e8f0; z-index: 0; }
.ld-timeline-line-done { background: #10b981; }
:is(.dark .ld-timeline-line) { background: #334155; }

/* ── Drawer ────────────────────────────────────────────────────────────────── */
.ld-drawer-backdrop { position: fixed; inset: 0; background: rgba(0,0,0,0.4); backdrop-filter: blur(4px); z-index: 40; animation: ld-fade-in 0.2s ease; }
.ld-drawer { position: fixed; top: 0; right: 0; bottom: 0; width: 480px; max-width: 95vw; background: #fff; border-left: 3px solid transparent; border-image: linear-gradient(to bottom, #0ea5e9, #475569, #f43f5e) 1; z-index: 50; overflow-y: auto; animation: ld-slide-in 0.25s ease; box-shadow: -8px 0 24px rgba(0,0,0,0.1); }
:is(.dark .ld-drawer) { background: #0f172a; box-shadow: -8px 0 24px rgba(0,0,0,0.3); }
@keyframes ld-slide-in { from { transform: translateX(100%); } to { transform: translateX(0); } }
@keyframes ld-fade-in { from { opacity: 0; } to { opacity: 1; } }

/* ── Status Banner (Drawer top) ────────────────────────────────────────────── */
.ld-status-banner { padding: 20px 24px; font-size: 1.1rem; font-weight: 700; color: #fff; }
.ld-banner-sky       { background: linear-gradient(135deg, #0284c7, #0ea5e9); }
.ld-banner-sky-pulse { background: linear-gradient(135deg, #0284c7, #0ea5e9); animation: ld-pulse-bg-sky 2s ease-in-out infinite; }
.ld-banner-amber     { background: linear-gradient(135deg, #d97706, #f59e0b); }
.ld-banner-cyan-pulse{ background: linear-gradient(135deg, #0891b2, #06b6d4); animation: ld-pulse-bg-cyan 2s ease-in-out infinite; }
.ld-banner-emerald   { background: linear-gradient(135deg, #059669, #10b981); }
.ld-banner-indigo-pulse { background: linear-gradient(135deg, #4f46e5, #6366f1); animation: ld-pulse-bg-indigo 2s ease-in-out infinite; }
.ld-banner-green     { background: linear-gradient(135deg, #16a34a, #22c55e); }
.ld-banner-gray      { background: linear-gradient(135deg, #475569, #64748b); }
@keyframes ld-pulse-bg-sky    { 0%,100% { box-shadow: inset 0 0 0 0 rgba(255,255,255,0); } 50% { box-shadow: inset 0 0 20px rgba(255,255,255,0.1); } }
@keyframes ld-pulse-bg-cyan   { 0%,100% { box-shadow: inset 0 0 0 0 rgba(255,255,255,0); } 50% { box-shadow: inset 0 0 20px rgba(255,255,255,0.1); } }
@keyframes ld-pulse-bg-indigo { 0%,100% { box-shadow: inset 0 0 0 0 rgba(255,255,255,0); } 50% { box-shadow: inset 0 0 20px rgba(255,255,255,0.1); } }

/* ── Table Row Highlighting ────────────────────────────────────────────────── */
.ld-row-loading    { border-left: 3px solid #0ea5e9; }
.ld-row-in-transit { border-left: 3px solid #6366f1; }
.ld-row-quality    { border-left: 3px solid #06b6d4; }
:is(.dark .ld-row-loading)    { border-left-color: #38bdf8; }
:is(.dark .ld-row-in-transit) { border-left-color: #818cf8; }
:is(.dark .ld-row-quality)    { border-left-color: #22d3ee; }

/* ── Progress Bars ─────────────────────────────────────────────────────────── */
.ld-progress-bar { height: 6px; border-radius: 3px; background: #e2e8f0; overflow: hidden; }
.ld-progress-fill { height: 100%; border-radius: 3px; transition: width 0.6s ease; }
.ld-progress-sky    { background: linear-gradient(90deg, #0284c7, #38bdf8); }
.ld-progress-slate  { background: linear-gradient(90deg, #475569, #94a3b8); }
.ld-progress-rose   { background: linear-gradient(90deg, #e11d48, #fb7185); }
.ld-progress-emerald{ background: linear-gradient(90deg, #059669, #34d399); }
:is(.dark .ld-progress-bar) { background: #1e293b; }

/* ── Staggered Fade-In Animations ──────────────────────────────────────────── */
.ld-fade-in { animation: ld-fade-in 0.4s ease forwards; opacity: 0; }
.ld-fade-in-1 { animation-delay: 0.05s; }
.ld-fade-in-2 { animation-delay: 0.1s; }
.ld-fade-in-3 { animation-delay: 0.15s; }
.ld-fade-in-4 { animation-delay: 0.2s; }
.ld-fade-in-5 { animation-delay: 0.25s; }
.ld-fade-in-6 { animation-delay: 0.3s; }

/* ── Filter Bar ────────────────────────────────────────────────────────────── */
.ld-filter-bar { display: flex; flex-wrap: wrap; gap: 8px; padding: 12px 16px; background: #f8fafc; border-radius: 10px; border: 1px solid #e2e8f0; }
:is(.dark .ld-filter-bar) { background: #1e293b; border-color: #334155; }
.ld-search-input { background: #fff; border: 1px solid #e2e8f0; border-radius: 8px; padding: 6px 12px 6px 32px; font-size: 0.8rem; width: 240px; outline: none; transition: border-color 0.15s; }
.ld-search-input:focus { border-color: #0ea5e9; box-shadow: 0 0 0 2px rgba(14,165,233,0.15); }
:is(.dark .ld-search-input) { background: #0f172a; border-color: #334155; color: #e2e8f0; }

/* ── Info Grid (Drawer) ────────────────────────────────────────────────────── */
.ld-info-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.ld-info-item { display: flex; flex-direction: column; gap: 2px; }
.ld-info-label { font-size: 0.65rem; color: #94a3b8; font-weight: 500; text-transform: uppercase; letter-spacing: 0.05em; }
.ld-info-value { font-size: 0.85rem; font-weight: 600; color: #1e293b; }
:is(.dark .ld-info-label) { color: #64748b; }
:is(.dark .ld-info-value) { color: #e2e8f0; }

/* ── Load Summary Cards ────────────────────────────────────────────────────── */
.ld-load-card { background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px; padding: 10px 14px; text-align: center; }
:is(.dark .ld-load-card) { background: #1e293b; border-color: #334155; }
.ld-load-card-value { font-size: 1.1rem; font-weight: 700; color: #0ea5e9; }
.ld-load-card-label { font-size: 0.65rem; color: #94a3b8; margin-top: 2px; }
:is(.dark .ld-load-card-value) { color: #38bdf8; }
:is(.dark .ld-load-card-label) { color: #64748b; }

/* ── Footer Stats (Drawer) ─────────────────────────────────────────────────── */
.ld-footer-stat { display: flex; flex-direction: column; gap: 1px; padding: 6px 12px; background: #f1f5f9; border-radius: 6px; }
:is(.dark .ld-footer-stat) { background: #1e293b; }
.ld-footer-stat-label { font-size: 0.6rem; color: #94a3b8; }
.ld-footer-stat-value { font-size: 0.8rem; font-weight: 600; color: #1e293b; }
:is(.dark .ld-footer-stat-label) { color: #64748b; }
:is(.dark .ld-footer-stat-value) { color: #e2e8f0; }

/* ── Responsive ────────────────────────────────────────────────────────────── */
@media (max-width: 768px) {
  .ld-drawer { width: 100vw; }
  .ld-kpi-card { padding: 12px 14px; }
  .ld-kpi-value { font-size: 1.35rem; }
  .ld-filter-bar { flex-direction: column; }
  .ld-search-input { width: 100%; }
  .ld-info-grid { grid-template-columns: 1fr; }
}
@media (max-width: 640px) {
  .ld-route-flow { gap: 0; }
  .ld-route-arrow { min-width: 12px; }
  .ld-timeline-step { gap: 3px; }
}

/* R135 Goods Receipt & GRN Management */
/* ═══════════════════════════════════════════════════════════════ */
/* R135 Goods Receipt & GRN Management — grn-* prefix            */
/* Theme: Teal #14b8a6 + Orange #f97316 + Lime #84cc16          */
/* ═══════════════════════════════════════════════════════════════ */

/* ── Animated gradient top border ── */
.grn-container {
  position: relative;
  padding-top: 3px;
  animation: grn-fade-in 0.3s ease-out;
}
.grn-container::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, #14b8a6, #f97316, #84cc16, #14b8a6);
  background-size: 300% 100%;
  animation: grn-gradient-slide 6s ease infinite;
  border-radius: 8px 8px 0 0;
}
@keyframes grn-gradient-slide {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}
@keyframes grn-fade-in {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ── Top bar ── */
.grn-top-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 2px;
}

/* ── KPI cards ── */
.grn-kpi-card {
  border-radius: 0.75rem;
  border: 1px solid transparent;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
  animation: grn-stagger 0.4s ease-out both;
}
.grn-kpi-card:nth-child(1) { animation-delay: 0ms; }
.grn-kpi-card:nth-child(2) { animation-delay: 60ms; }
.grn-kpi-card:nth-child(3) { animation-delay: 120ms; }
.grn-kpi-card:nth-child(4) { animation-delay: 180ms; }
.grn-kpi-card:nth-child(5) { animation-delay: 240ms; }
.grn-kpi-card:nth-child(6) { animation-delay: 300ms; }
@keyframes grn-stagger {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}
.grn-kpi-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(20, 184, 166, 0.12);
}
.dark .grn-kpi-card {
  background: linear-gradient(135deg, rgba(20, 184, 166, 0.08), rgba(249, 115, 22, 0.06));
  border-color: rgba(20, 184, 166, 0.15);
}
.grn-kpi-icon {
  width: 36px;
  height: 36px;
  border-radius: 0.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.grn-text-teal { color: #14b8a6; }
.grn-text-orange { color: #f97316; }
.grn-text-lime { color: #84cc16; }
.grn-text-red { color: #ef4444; }
.grn-text-muted { color: #94a3b8; }

/* ── Tab list & triggers ── */
.grn-tab-list {
  flex-wrap: wrap;
  gap: 4px;
}
.grn-tab-trigger {
  font-size: 0.75rem;
  padding: 6px 12px;
}
.grn-tab-content {
  animation: grn-fade-in 0.25s ease-out;
}

/* ── Status badges ── */
.grn-badge-draft { background: #f1f5f9; color: #64748b; border: 1px solid #e2e8f0; }
.grn-badge-submitted { background: #eff6ff; color: #3b82f6; border: 1px solid #bfdbfe; }
.grn-badge-under-qc { background: #fff7ed; color: #f97316; border: 1px solid #fed7aa; }
.grn-badge-qc-passed { background: #f0fdf4; color: #22c55e; border: 1px solid #bbf7d0; }
.grn-badge-qc-failed { background: #fef2f2; color: #ef4444; border: 1px solid #fecaca; }
.grn-badge-partial { background: #fefce8; color: #eab308; border: 1px solid #fef08a; }
.grn-badge-accepted { background: #ecfdf5; color: #14b8a6; border: 1px solid #99f6e4; }
.grn-badge-rejected { background: #fef2f2; color: #dc2626; border: 1px solid #fecaca; }

/* ── Receipt type badges ── */
.grn-badge-po { background: #f0fdf4; color: #14b8a6; border: 1px solid #99f6e4; }
.grn-badge-transfer { background: #eff6ff; color: #3b82f6; border: 1px solid #bfdbfe; }
.grn-badge-cust-return { background: #fefce8; color: #eab308; border: 1px solid #fef08a; }
.grn-badge-vendor-return { background: #fef2f2; color: #ef4444; border: 1px solid #fecaca; }
.grn-badge-sample { background: #faf5ff; color: #a855f7; border: 1px solid #e9d5ff; }
.grn-badge-interco { background: #f0f9ff; color: #0284c7; border: 1px solid #bae6fd; }

/* ── Priority badges ── */
.grn-badge-critical { background: #fef2f2; color: #dc2626; border: 1px solid #fecaca; font-weight: 600; }
.grn-badge-high { background: #fff7ed; color: #f97316; border: 1px solid #fed7aa; }
.grn-badge-medium { background: #fefce8; color: #ca8a04; border: 1px solid #fef08a; }
.grn-badge-low { background: #f1f5f9; color: #64748b; border: 1px solid #e2e8f0; }

/* ── QC method badges ── */
.grn-badge-qc-method {
  background: #f0fdfa; color: #0d9488; border: 1px solid #99f6e4;
  font-size: 0.6rem; padding: 2px 6px; white-space: nowrap;
}

/* ── QC result badges ── */
.grn-badge-pass { background: #f0fdf4; color: #16a34a; border: 1px solid #bbf7d0; }
.grn-badge-fail { background: #fef2f2; color: #dc2626; border: 1px solid #fecaca; }
.grn-badge-conditional { background: #fff7ed; color: #ea580c; border: 1px solid #fed7aa; }

/* ── Match status badges ── */
.grn-badge-matched { background: #f0fdf4; color: #16a34a; border: 1px solid #bbf7d0; }
.grn-badge-mismatch { background: #fef2f2; color: #dc2626; border: 1px solid #fecaca; }
.grn-badge-pending { background: #f1f5f9; color: #64748b; border: 1px solid #e2e8f0; }

/* ── Teal generic badge ── */
.grn-badge-teal {
  background: #14b8a6; color: white; border: none; font-size: 0.6rem; padding: 1px 6px;
}

/* ── Pulse badge animation ── */
.grn-pulse-badge {
  animation: grn-pulse 1.8s ease-in-out infinite;
}
@keyframes grn-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.6; }
}

/* ── Star ratings ── */
.grn-star { transition: color 0.15s ease; }
.grn-star-filled { color: #f59e0b; fill: #f59e0b; }
.grn-star-empty { color: #d1d5db; }

/* ── Filter bar ── */
.grn-filter-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  padding: 8px 12px;
  border-radius: 0.75rem;
  background: hsl(var(--card));
  border: 1px solid hsl(var(--border));
}

/* ── Table styles ── */
.grn-table { font-size: 0.75rem; }
.grn-table-header { background: linear-gradient(135deg, #f0fdfa, #fef7ed); }
.dark .grn-table-header { background: rgba(20, 184, 166, 0.08); }
.grn-table-row { transition: background-color 0.15s ease; }
.grn-table-row:hover { background-color: rgba(20, 184, 166, 0.04); }
.dark .grn-table-row:hover { background-color: rgba(20, 184, 166, 0.08); }

/* ── Variance display ── */
.grn-variance { font-variant-numeric: tabular-nums; font-weight: 600; }
.grn-var-pos { color: #16a34a; }
.grn-var-neg { color: #ef4444; }

/* ── Chart card ── */
.grn-chart-card {
  border-radius: 0.75rem;
  transition: box-shadow 0.2s ease;
}
.grn-chart-card:hover {
  box-shadow: 0 2px 12px rgba(20, 184, 166, 0.08);
}

/* ── Receipt flow (4 dots) ── */
.grn-receipt-flow {
  display: flex;
  align-items: flex-start;
  justify-content: space-around;
  padding: 12px 8px;
  border-radius: 0.75rem;
  background: linear-gradient(135deg, rgba(20, 184, 166, 0.04), rgba(249, 115, 22, 0.03));
}
.grn-flow-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  font-size: 0.65rem;
  color: hsl(var(--muted-foreground));
}
.grn-flow-dot {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  border: 2px solid #d1d5db;
  background: white;
  color: #94a3b8;
  transition: all 0.2s ease;
}
.grn-flow-dot-active {
  border-color: #14b8a6;
  background: #14b8a6;
  color: white;
}
.grn-flow-dot-current {
  border-color: #f97316;
  background: #fff7ed;
  color: #f97316;
  box-shadow: 0 0 0 3px rgba(249, 115, 22, 0.2);
}
.dark .grn-flow-dot { background: #1e293b; border-color: #475569; }
.dark .grn-flow-dot-current { background: rgba(249, 115, 22, 0.15); }

/* ── Info grid ── */
.grn-info-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}
.grn-info-item {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 6px 8px;
  border-radius: 0.5rem;
  background: hsl(var(--muted) / 0.5);
}

/* ── Qty summary boxes ── */
.grn-qty-box {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 10px 8px;
  border-radius: 0.5rem;
  border: 1px solid;
}
.grn-qty-ordered { border-color: #3b82f6; background: #eff6ff; color: #3b82f6; }
.grn-qty-received { border-color: #14b8a6; background: #f0fdfa; color: #14b8a6; }
.grn-qty-accepted { border-color: #84cc16; background: #f7fee7; color: #84cc16; }
.grn-qty-rejected { border-color: #ef4444; background: #fef2f2; color: #ef4444; }
.dark .grn-qty-ordered { background: rgba(59, 130, 246, 0.1); }
.dark .grn-qty-received { background: rgba(20, 184, 166, 0.1); }
.dark .grn-qty-accepted { background: rgba(132, 204, 22, 0.1); }
.dark .grn-qty-rejected { background: rgba(239, 68, 68, 0.1); }

/* ── Financial summary boxes ── */
.grn-fin-box {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  padding: 10px 8px;
  border-radius: 0.5rem;
  border: 1px solid hsl(var(--border));
  background: hsl(var(--muted) / 0.3);
}
.grn-fin-po { border-left: 3px solid #14b8a6; }
.grn-fin-inv { border-left: 3px solid #f97316; }
.grn-fin-var { border-left: 3px solid #84cc16; }

/* ── QC result box ── */
.grn-qc-result-box {
  padding: 12px;
  border-radius: 0.75rem;
  background: linear-gradient(135deg, #fff7ed, #fffbeb);
  border: 1px solid #fed7aa;
}
.dark .grn-qc-result-box {
  background: linear-gradient(135deg, rgba(249, 115, 22, 0.08), rgba(234, 179, 8, 0.06));
  border-color: rgba(249, 115, 22, 0.2);
}

/* ── Timeline ── */
.grn-timeline {
  display: flex;
  flex-direction: column;
  gap: 0;
  padding-left: 4px;
}
.grn-timeline-step {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 6px 0;
  position: relative;
}
.grn-timeline-step:not(:last-child)::after {
  content: "";
  position: absolute;
  left: 7px;
  top: 22px;
  width: 2px;
  height: calc(100% - 14px);
  background: #e2e8f0;
}
.grn-timeline-step:not(:last-child).grn-timeline-step::after {
  left: 7px;
}
.grn-timeline-dot {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid #d1d5db;
  background: white;
  flex-shrink: 0;
  margin-top: 2px;
}
.grn-timeline-dot-done {
  border-color: #14b8a6;
  background: #14b8a6;
  color: white;
}
.dark .grn-timeline-dot { background: #1e293b; border-color: #475569; }

/* ── Drawer ── */
.grn-drawer {
  backdrop-filter: blur(8px);
}
.grn-drawer::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 4px;
  height: 100%;
  background: linear-gradient(180deg, #14b8a6, #f97316, #84cc16);
  border-radius: 0 4px 4px 0;
}
.grn-drawer-header {
  background: linear-gradient(135deg, #f0fdfa, #fef7ed);
  border-bottom: 1px solid hsl(var(--border));
  flex-wrap: wrap;
  gap: 8px;
}
.dark .grn-drawer-header {
  background: linear-gradient(135deg, rgba(20, 184, 166, 0.06), rgba(249, 115, 22, 0.04));
}

/* ── Drawer footer ── */
.grn-drawer-footer {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  padding: 10px 12px;
  border-radius: 0.5rem;
  background: hsl(var(--muted) / 0.4);
  font-size: 0.7rem;
  color: hsl(var(--muted-foreground));
}
.grn-drawer-footer > div {
  display: flex;
  align-items: center;
  gap: 4px;
}

/* ── Quality bar ── */
.grn-quality-bar-bg {
  background: hsl(var(--muted));
  border-radius: 9999px;
  overflow: hidden;
}
.grn-quality-bar-fill {
  background: linear-gradient(90deg, #14b8a6, #84cc16);
  border-radius: 9999px;
  transition: width 0.5s ease;
}

/* ── Progress bars ── */
.grn-progress-bar {
  height: 6px;
  border-radius: 9999px;
  background: hsl(var(--muted));
  overflow: hidden;
}
.grn-progress-bar-fill {
  height: 100%;
  border-radius: 9999px;
  transition: width 0.5s ease;
}

/* ── Responsive ── */
@media (max-width: 768px) {
  .grn-info-grid { grid-template-columns: 1fr; }
  .grn-filter-bar { flex-direction: column; align-items: stretch; }
  .grn-receipt-flow { gap: 4px; }
}

/* ── Dark mode refinements ── */
.dark .grn-badge-draft { background: rgba(100, 116, 139, 0.15); border-color: rgba(100, 116, 139, 0.25); }
.dark .grn-badge-submitted { background: rgba(59, 130, 246, 0.12); border-color: rgba(59, 130, 246, 0.25); }
.dark .grn-badge-under-qc { background: rgba(249, 115, 22, 0.12); border-color: rgba(249, 115, 22, 0.25); }
.dark .grn-badge-qc-passed { background: rgba(34, 197, 94, 0.12); border-color: rgba(34, 197, 94, 0.25); }
.dark .grn-badge-qc-failed { background: rgba(239, 68, 68, 0.12); border-color: rgba(239, 68, 68, 0.25); }
.dark .grn-badge-partial { background: rgba(234, 179, 8, 0.12); border-color: rgba(234, 179, 8, 0.25); }
.dark .grn-badge-accepted { background: rgba(20, 184, 166, 0.12); border-color: rgba(20, 184, 166, 0.25); }
.dark .grn-badge-rejected { background: rgba(220, 38, 38, 0.12); border-color: rgba(220, 38, 38, 0.25); }
.dark .grn-badge-critical { background: rgba(220, 38, 38, 0.15); border-color: rgba(220, 38, 38, 0.3); }
.dark .grn-badge-high { background: rgba(249, 115, 22, 0.12); border-color: rgba(249, 115, 22, 0.25); }
.dark .grn-badge-medium { background: rgba(202, 138, 4, 0.12); border-color: rgba(202, 138, 4, 0.25); }
.dark .grn-badge-low { background: rgba(100, 116, 139, 0.15); border-color: rgba(100, 116, 139, 0.25); }
.dark .grn-badge-po { background: rgba(20, 184, 166, 0.12); border-color: rgba(20, 184, 166, 0.25); }
.dark .grn-badge-transfer { background: rgba(59, 130, 246, 0.12); border-color: rgba(59, 130, 246, 0.25); }
.dark .grn-badge-cust-return { background: rgba(234, 179, 8, 0.12); border-color: rgba(234, 179, 8, 0.25); }
.dark .grn-badge-vendor-return { background: rgba(239, 68, 68, 0.12); border-color: rgba(239, 68, 68, 0.25); }
.dark .grn-badge-sample { background: rgba(168, 85, 247, 0.12); border-color: rgba(168, 85, 247, 0.25); }
.dark .grn-badge-interco { background: rgba(2, 132, 199, 0.12); border-color: rgba(2, 132, 199, 0.25); }
.dark .grn-badge-pass { background: rgba(22, 163, 74, 0.12); border-color: rgba(22, 163, 74, 0.25); }
.dark .grn-badge-fail { background: rgba(220, 38, 38, 0.12); border-color: rgba(220, 38, 38, 0.25); }
.dark .grn-badge-conditional { background: rgba(234, 88, 12, 0.12); border-color: rgba(234, 88, 12, 0.25); }
.dark .grn-badge-matched { background: rgba(22, 163, 74, 0.12); border-color: rgba(22, 163, 74, 0.25); }
.dark .grn-badge-mismatch { background: rgba(220, 38, 38, 0.12); border-color: rgba(220, 38, 38, 0.25); }
.dark .grn-badge-pending { background: rgba(100, 116, 139, 0.15); border-color: rgba(100, 116, 139, 0.25); }
.dark .grn-badge-qc-method { background: rgba(13, 148, 136, 0.12); border-color: rgba(13, 148, 136, 0.25); }
.dark .grn-star-empty { color: #475569; }

/* ── Staggered animation utilities ── */
.grn-stagger-1 { animation: grn-stagger 0.4s ease-out 0.05s both; }
.grn-stagger-2 { animation: grn-stagger 0.4s ease-out 0.1s both; }
.grn-stagger-3 { animation: grn-stagger 0.4s ease-out 0.15s both; }
.grn-stagger-4 { animation: grn-stagger 0.4s ease-out 0.2s both; }

/* ── Hover card lift ── */
.grn-hover-lift {
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.grn-hover-lift:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 25px rgba(20, 184, 166, 0.12);
}

/* ── Tooltip custom ── */
.grn-tooltip {
  background: #1e293b !important;
  border: 1px solid rgba(20, 184, 166, 0.3) !important;
  border-radius: 8px !important;
  font-size: 0.7rem !important;
}
.dark .grn-tooltip {
  background: #0f172a !important;
  border-color: rgba(20, 184, 166, 0.2) !important;
}

/* ── Scrollbar in drawer ── */
.grn-drawer::-webkit-scrollbar {
  width: 5px;
}
.grn-drawer::-webkit-scrollbar-track {
  background: transparent;
}
.grn-drawer::-webkit-scrollbar-thumb {
  background: rgba(20, 184, 166, 0.25);
  border-radius: 10px;
}
.grn-drawer::-webkit-scrollbar-thumb:hover {
  background: rgba(20, 184, 166, 0.45);
}

/* ── Mini stat box inside drawer ── */
