.dark .fsr-table-head { background: #1e293b; }
.fsr-table-head th { padding: 0.6rem 0.75rem; text-align: left; font-size: 0.7rem; font-weight: 600; color: #64748b; text-transform: uppercase; letter-spacing: 0.04em; border-bottom: 1px solid #e2e8f0; }
